window.SAIF_COMMUNITY = {"schemaVersion":1,"edition":"frozen","generatedAt":"2026-08-14T14:58:25.675Z","release":{"schemaVersion":1,"releaseId":"saif-community-hub-2026-08-14","status":"approved","approvedAt":"2026-08-14","repository":"sinai-computational-pathology/saif-community-hub","siteUrl":"https://sinai-computational-pathology.github.io/saif-community-hub/supplement/v1/","atlasUrl":"https://sinai-computational-pathology.github.io/saif-results-atlas/supplement/v1/","atlasReleaseId":"saif-results-2026-07-31","claimCount":28},"stats":{"dossiers":28,"claims":232,"organs":14,"citations":94,"verifiedClaims":0},"dossiers":[{"combo":"breast__age","organ_slug":"breast","organ":"Breast","demographic":"age","demographic_label":"Age","summary":"Breast age signal is a high-priority residual-signal candidate. The strongest literature-supported carrier is background terminal duct lobular unit (TDLU) involution with adipose replacement and stromal remodeling. Clinical-context signal may also arise from age-skewed screening, benign disease, cancer incidence, procedure type, and subtype mix.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Older breast specimens are enriched for cancer, screening-related lesions, and different procedure types.","mechanism":"Age changes the mix of benign biopsies, cancer resections, DCIS/invasive carcinoma, and screening-detected lesions.","features":"Benign vs malignant tissue, DCIS/invasive carcinoma, biopsy vs resection, tumor subtype.","confounders":"Diagnosis, DCIS/invasive status, procedure type, screening indication, treatment status.","validation":"Compare age prediction within benign-only and cancer-only subsets; match procedure type.","literature":[{"short_citation":"Radisky et al., 2016","citation":"Radisky DC, Visscher DW, Frank RD, et al. Natural history of age-related lobular involution and impact on breast cancer risk. Breast Cancer Research and Treatment. 2016","pmid":"26846985","pmcid":"PMC4764623","doi":"10.1007/s10549-015-3665-5","evidence_status":"needs claim-level validation"},{"short_citation":"Ginsburg et al., 2008","citation":"Ginsburg OM, Martin LJ, Boyd NF. Mammographic density, lobular involution, and risk of breast cancer. British Journal of Cancer. 2008","pmcid":"PMC2579686","doi":"10.1038/sj.bjc.6604635","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Breast cancer risk context can be encoded through tissue composition.","mechanism":"Mammographic density and lobular involution are breast-cancer-risk markers linked to fibroglandular composition.","features":"Fibroglandular density, epithelial/stromal fraction, adipose replacement, lobular involution.","confounders":"Density, benign disease indication, menopausal status, sampling site.","validation":"Test whether attention localizes to background fibroglandular tissue after diagnosis matching.","literature":[{"short_citation":"Ginsburg et al., 2008","citation":"Ginsburg OM, Martin LJ, Boyd NF. Mammographic density, lobular involution, and risk of breast cancer. British Journal of Cancer. 2008","pmcid":"PMC2579686","doi":"10.1038/sj.bjc.6604635","evidence_status":"needs claim-level validation"},{"short_citation":"Walker & Martin, 2007","citation":"Walker RA, Martin CV. The aged breast. Journal of Pathology. 2007","doi":"10.1002/path.2079","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Menopausal status may create an age-associated sampling and morphology axis.","mechanism":"Menopause changes breast density, epithelial activity, lobular involution, and the clinical indication mix.","features":"Postmenopausal involution, adipose replacement, stromal density, benign proliferative disease.","confounders":"Menopausal status, hormone therapy, BMI, parity, biopsy indication.","validation":"If metadata allow, stratify premenopausal vs postmenopausal cases before age prediction review.","literature":[{"short_citation":"Walker & Martin, 2007","citation":"Walker RA, Martin CV. The aged breast. Journal of Pathology. 2007","doi":"10.1002/path.2079","evidence_status":"needs claim-level validation"},{"short_citation":"Ginsburg et al., 2008","citation":"Ginsburg OM, Martin LJ, Boyd NF. Mammographic density, lobular involution, and risk of breast cancer. British Journal of Cancer. 2008","pmcid":"PMC2579686","doi":"10.1038/sj.bjc.6604635","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Benign high-risk lesions and DCIS may differ by age and screening intensity.","mechanism":"Screening and age-dependent risk can shift the fraction of atypia, DCIS, and excisional biopsies.","features":"Atypical ductal/lobular hyperplasia, DCIS, calcification-associated biopsies, excision scars.","confounders":"Screening status, procedure type, lesion diagnosis, calcifications, prior biopsy.","validation":"Match benign/high-risk/DCIS/invasive categories and review whether age signal follows lesion mix.","literature":[{"short_citation":"Radisky et al., 2016","citation":"Radisky DC, Visscher DW, Frank RD, et al. Natural history of age-related lobular involution and impact on breast cancer risk. Breast Cancer Research and Treatment. 2016","pmid":"26846985","pmcid":"PMC4764623","doi":"10.1007/s10549-015-3665-5","evidence_status":"needs claim-level validation"},{"short_citation":"Ginsburg et al., 2008","citation":"Ginsburg OM, Martin LJ, Boyd NF. Mammographic density, lobular involution, and risk of breast cancer. British Journal of Cancer. 2008","pmcid":"PMC2579686","doi":"10.1038/sj.bjc.6604635","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"TDLU involution increases with age and can remain visible after diagnosis matching.","mechanism":"Aging and reproductive/hormonal history reduce lobular epithelial and acinar compartments.","features":"TDLU density, lobular size, acinar number, epithelial cellularity.","confounders":"Menopausal status, parity/reproductive history, benign disease, tumor-adjacent tissue.","validation":"Quantify TDLU involution in benign/background tissue matched by diagnosis and procedure.","literature":[{"short_citation":"Radisky et al., 2016","citation":"Radisky DC, Visscher DW, Frank RD, et al. Natural history of age-related lobular involution and impact on breast cancer risk. Breast Cancer Research and Treatment. 2016","pmid":"26846985","pmcid":"PMC4764623","doi":"10.1007/s10549-015-3665-5","evidence_status":"needs claim-level validation"},{"short_citation":"Walker & Martin, 2007","citation":"Walker RA, Martin CV. The aged breast. Journal of Pathology. 2007","doi":"10.1002/path.2079","evidence_status":"needs claim-level validation"},{"short_citation":"Oh et al., 2016","citation":"Oh H, Khodr ZG, Sherman ME, et al. Ages at menarche- and menopause-related genetic variants in relation to terminal duct lobular unit involution of the normal breast. Breast Cancer Research. 2016","pmid":"27439764","pmcid":"PMC4955231","doi":"10.1186/s13058-016-0738-5","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Adipose replacement and stromal remodeling encode breast aging.","mechanism":"Lobular regression shifts tissue composition from epithelial/stromal units toward fat and altered stroma.","features":"Adipose fraction, stromal density, duct/lobule ratio, collagen texture.","confounders":"Sampling site, obesity, specimen type, fixation, tumor desmoplasia.","validation":"Review attention maps for background adipose/stromal compartments outside tumor.","literature":[{"short_citation":"Walker & Martin, 2007","citation":"Walker RA, Martin CV. The aged breast. Journal of Pathology. 2007","doi":"10.1002/path.2079","evidence_status":"needs claim-level validation"},{"short_citation":"Ginsburg et al., 2008","citation":"Ginsburg OM, Martin LJ, Boyd NF. Mammographic density, lobular involution, and risk of breast cancer. British Journal of Cancer. 2008","pmcid":"PMC2579686","doi":"10.1038/sj.bjc.6604635","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Reproductive-timing biology may modulate normal breast involution.","mechanism":"Genetic/life-course factors linked to menarche and menopause can relate to TDLU involution measures.","features":"TDLU involution score, epithelial area, acinar count.","confounders":"Age, menopausal status, ancestry, benign disease cohort composition.","validation":"Interpret residual age signal as life-course morphology only after direct tissue review.","literature":[{"short_citation":"Oh et al., 2016","citation":"Oh H, Khodr ZG, Sherman ME, et al. Ages at menarche- and menopause-related genetic variants in relation to terminal duct lobular unit involution of the normal breast. Breast Cancer Research. 2016","pmid":"27439764","pmcid":"PMC4955231","doi":"10.1186/s13058-016-0738-5","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Mammographic-density correlates may map to H&E tissue composition.","mechanism":"Dense breast tissue reflects higher epithelial/fibrous content relative to fat and can change with age.","features":"Fibroglandular fraction, collagen-rich stroma, adipose fraction, epithelial area.","confounders":"BMI, menopause, parity, site, tumor adjacency.","validation":"Compare model attention with manual fibroglandular/adipose estimates in benign background.","literature":[{"short_citation":"Ginsburg et al., 2008","citation":"Ginsburg OM, Martin LJ, Boyd NF. Mammographic density, lobular involution, and risk of breast cancer. British Journal of Cancer. 2008","pmcid":"PMC2579686","doi":"10.1038/sj.bjc.6604635","evidence_status":"needs claim-level validation"},{"short_citation":"Walker & Martin, 2007","citation":"Walker RA, Martin CV. The aged breast. Journal of Pathology. 2007","doi":"10.1002/path.2079","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["Best histology-review target: benign/background TDLU involution, adipose replacement, and stromal density.","Main shortcut risk: cancer/benign mix, screening context, and biopsy versus resection.","Priority Score rationale: high residual S3_CC performance with strong specimen availability and low Drop %."],"references":[{"n":1,"raw":"Radisky DC, Visscher DW, Frank RD, et al. Natural history of age-related lobular involution and impact on breast cancer risk. Breast Cancer Research and Treatment. 2016. PMID: 26846985. PMCID: PMC4764623. DOI: 10.1007/s10549-015-3665-5.","citation":"Radisky DC, Visscher DW, Frank RD, et al. Natural history of age-related lobular involution and impact on breast cancer risk. Breast Cancer Research and Treatment. 2016","year":"2016","pmid":"26846985","pmcid":"PMC4764623","doi":"10.1007/s10549-015-3665-5"},{"n":2,"raw":"Walker RA, Martin CV. The aged breast. Journal of Pathology. 2007. DOI: 10.1002/path.2079.","citation":"Walker RA, Martin CV. The aged breast. Journal of Pathology. 2007","year":"2007","doi":"10.1002/path.2079"},{"n":3,"raw":"Ginsburg OM, Martin LJ, Boyd NF. Mammographic density, lobular involution, and risk of breast cancer. British Journal of Cancer. 2008. PMCID: PMC2579686. DOI: 10.1038/sj.bjc.6604635.","citation":"Ginsburg OM, Martin LJ, Boyd NF. Mammographic density, lobular involution, and risk of breast cancer. British Journal of Cancer. 2008","year":"2008","pmcid":"PMC2579686","doi":"10.1038/sj.bjc.6604635"},{"n":4,"raw":"Oh H, Khodr ZG, Sherman ME, et al. Ages at menarche- and menopause-related genetic variants in relation to terminal duct lobular unit involution of the normal breast. Breast Cancer Research. 2016. PMID: 27439764. PMCID: PMC4955231. DOI: 10.1186/s13058-016-0738-5.","citation":"Oh H, Khodr ZG, Sherman ME, et al. Ages at menarche- and menopause-related genetic variants in relation to terminal duct lobular unit involution of the normal breast. Breast Cancer Research. 2016","year":"2016","pmid":"27439764","pmcid":"PMC4955231","doi":"10.1186/s13058-016-0738-5"}],"filename":"breast__age.yaml"},{"combo":"breast__race_self_reported_ancestry","organ_slug":"breast","organ":"Breast","demographic":"race_self_reported_ancestry","demographic_label":"Race / Self-Reported Ancestry","summary":"Breast race or ancestry signal should be framed as a mixture of tumor subtype, screening/access context, treatment pathway, body composition, and tumor microenvironment hypotheses. The most literature-supported H&E-visible carriers are triple-negative/basal-like tumor enrichment, higher grade, necrosis, stromal and immune features, and mammographic-density-related fibroglandular composition. This page should not be interpreted as evidence of intrinsic racial morphology; race is a social and imperfect proxy for ancestry, structural exposure, and care access.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Race-associated breast signal may be driven by tumor subtype distribution.","mechanism":"Triple-negative and basal-like breast cancers are more common among Black/African American women in many U.S. cohorts.","features":"ER/PR/HER2 status, TNBC/basal-like morphology, high grade, pushing borders, necrosis.","confounders":"Tumor subtype, grade, age, stage, treatment status, institution.","validation":"Match ER/PR/HER2 subtype and grade; test whether race signal persists within TNBC-only and non-TNBC-only sets.","literature":[{"short_citation":"Lund et al., 2009","citation":"Lund MJ, Trivers KF, Porter PL, et al. Race and triple negative threats to breast cancer survival: a population-based study in Atlanta, GA. Breast Cancer Research and Treatment. 2009;113(2):357-370","pmid":"18324472","doi":"10.1007/s10549-008-9926-3","url":"https://pubmed.ncbi.nlm.nih.gov/18324472/","evidence_status":"needs claim-level validation"},{"short_citation":"Dietze et al., 2015","citation":"Dietze EC, Sistrunk C, Miranda-Carboni G, O'Regan R, Seewaldt VL. Triple-negative breast cancer in African-American women: disparities versus biology. Nature Reviews Cancer. 2015;15(4):248-254","pmid":"25673085","pmcid":"PMC5470637","doi":"10.1038/nrc3896","url":"https://pubmed.ncbi.nlm.nih.gov/25673085/","evidence_status":"needs claim-level validation"},{"short_citation":"Torres et al., 2024","citation":"Torres JM, Sodipo MO, Hopkins MF, Chandler P, Warner ET. Racial Differences in Breast Cancer Survival Between Black and White Women According to Tumor Subtype: A Systematic Review and Meta-Analysis. Journal of Clinical Oncology. 2024;42:3867-3879","doi":"10.1200/JCO.23.02311","url":"https://ascopubs.org/doi/10.1200/JCO.23.02311","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Stage, screening, and treatment access can produce race-associated pathology context.","mechanism":"Structural inequities influence stage at presentation, treatment timing, and procedure mix, creating H&E-visible case-mix differences.","features":"Tumor size surrogate, nodal/metastatic context, resection vs biopsy, treatment effect, margins.","confounders":"Stage, procedure type, neoadjuvant therapy, screening status, institution/access proxies.","validation":"Match stage/procedure/treatment status; audit whether signal disappears after care-pathway matching.","literature":[{"short_citation":"Reeder-Hayes et al., 2023","citation":"Reeder-Hayes K, Roberson ML, Wheeler SB, Abdou Y, Troester MA. From Race to Racism and Disparities to Equity: An Actionable Biopsychosocial Approach to Breast Cancer Outcomes. Cancer Journal. 2023;29(6):316-322","pmid":"37963365","pmcid":"PMC10651167","doi":"10.1097/PPO.0000000000000677","url":"https://pubmed.ncbi.nlm.nih.gov/37963365/","evidence_status":"needs claim-level validation"},{"short_citation":"Torres et al., 2024","citation":"Torres JM, Sodipo MO, Hopkins MF, Chandler P, Warner ET. Racial Differences in Breast Cancer Survival Between Black and White Women According to Tumor Subtype: A Systematic Review and Meta-Analysis. Journal of Clinical Oncology. 2024;42:3867-3879","doi":"10.1200/JCO.23.02311","url":"https://ascopubs.org/doi/10.1200/JCO.23.02311","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Background density and breast composition may vary by race/ethnicity and BMI.","mechanism":"Mammographic density reflects epithelial/fibrous vs adipose composition and varies with age, BMI, parity, menopausal status, and race/ethnicity.","features":"Fibroglandular fraction, adipose fraction, stromal density, collagen texture, lobular density.","confounders":"BMI, age, parity, menopausal status, sampling site, benign vs tumor-adjacent tissue.","validation":"Review benign/background tissue only; match BMI/age/menopause if available.","literature":[{"short_citation":"McCarthy et al., 2016","citation":"McCarthy AM, Keller BM, Pantalone LM, et al. Racial Differences in Quantitative Measures of Area and Volumetric Breast Density. Journal of the National Cancer Institute. 2016;108(10):djw104","pmid":"27130893","pmcid":"PMC5939658","doi":"10.1093/jnci/djw104","url":"https://pubmed.ncbi.nlm.nih.gov/27130893/","evidence_status":"needs claim-level validation"},{"short_citation":"Burton et al., 2017","citation":"Burton A, Maskarinec G, Perez-Gomez B, et al. Mammographic density: intersection of advocacy, science, and clinical practice. Breast Cancer Research. 2017/2020 indexed","pmid":"33312342","pmcid":"PMC7728377","doi":"10.1007/s12609-019-00316-4","url":"https://pubmed.ncbi.nlm.nih.gov/33312342/","evidence_status":"needs claim-level validation"},{"short_citation":"Mariapun et al., 2015","citation":"Mariapun S, Li J, Yip CH, Taib NAM, Teo S-H. Ethnic Differences in Mammographic Densities: An Asian Cross-Sectional Study. PLOS ONE. 2015;10(2):e0117568","doi":"10.1371/journal.pone.0117568","url":"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0117568","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Benign breast disease and biopsy indication may differ by access and screening pathway.","mechanism":"Screening intensity and diagnostic follow-up influence benign biopsies, high-risk lesions, and surgical excision mix.","features":"Fibrocystic change, fibroadenoma, papilloma, atypia, DCIS, biopsy vs excision.","confounders":"Diagnosis, screening indication, procedure type, age, institution.","validation":"Stratify benign lesions and DCIS/invasive cancer separately.","literature":[{"short_citation":"Reeder-Hayes et al., 2023","citation":"Reeder-Hayes K, Roberson ML, Wheeler SB, Abdou Y, Troester MA. From Race to Racism and Disparities to Equity: An Actionable Biopsychosocial Approach to Breast Cancer Outcomes. Cancer Journal. 2023;29(6):316-322","pmid":"37963365","pmcid":"PMC10651167","doi":"10.1097/PPO.0000000000000677","url":"https://pubmed.ncbi.nlm.nih.gov/37963365/","evidence_status":"needs claim-level validation"},{"short_citation":"Burton et al., 2017","citation":"Burton A, Maskarinec G, Perez-Gomez B, et al. Mammographic density: intersection of advocacy, science, and clinical practice. Breast Cancer Research. 2017/2020 indexed","pmid":"33312342","pmcid":"PMC7728377","doi":"10.1007/s12609-019-00316-4","url":"https://pubmed.ncbi.nlm.nih.gov/33312342/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"TNBC/basal-like morphology may be the dominant H&E carrier.","mechanism":"Subtype enrichment produces visible high-grade tumor morphology and necrosis.","features":"Nuclear grade, mitotic activity, necrosis, lymphocytic infiltrate, pushing/infiltrative border.","confounders":"ER/PR/HER2, grade, stage, treatment, age.","validation":"Within-subtype review; compare attention maps before and after subtype matching.","literature":[{"short_citation":"Lund et al., 2009","citation":"Lund MJ, Trivers KF, Porter PL, et al. Race and triple negative threats to breast cancer survival: a population-based study in Atlanta, GA. Breast Cancer Research and Treatment. 2009;113(2):357-370","pmid":"18324472","doi":"10.1007/s10549-008-9926-3","url":"https://pubmed.ncbi.nlm.nih.gov/18324472/","evidence_status":"needs claim-level validation"},{"short_citation":"Dietze et al., 2015","citation":"Dietze EC, Sistrunk C, Miranda-Carboni G, O'Regan R, Seewaldt VL. Triple-negative breast cancer in African-American women: disparities versus biology. Nature Reviews Cancer. 2015;15(4):248-254","pmid":"25673085","pmcid":"PMC5470637","doi":"10.1038/nrc3896","url":"https://pubmed.ncbi.nlm.nih.gov/25673085/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Tumor immune microenvironment may contribute to residual signal.","mechanism":"Race-associated differences in TNBC immune microenvironment have been reported, though interpretation must separate biology from context.","features":"TIL density, stromal lymphocytes, lymphoid aggregates, necrosis-associated inflammation.","confounders":"Subtype, grade, treatment, tumor size, fixation, institution.","validation":"Quantify TILs within matched TNBC cases and validate externally.","literature":[{"short_citation":"Yaghoobi et al., 2021","citation":"Yaghoobi V, Tewari M, Miller R, et al. Quantitative assessment of the immune microenvironment in African American Triple Negative Breast Cancer: a case-control study. Breast Cancer Research. 2021;23:99","doi":"10.1186/s13058-021-01493-w","url":"https://breast-cancer-research.biomedcentral.com/articles/10.1186/s13058-021-01493-w","evidence_status":"needs claim-level validation"},{"short_citation":"Dietze et al., 2015","citation":"Dietze EC, Sistrunk C, Miranda-Carboni G, O'Regan R, Seewaldt VL. Triple-negative breast cancer in African-American women: disparities versus biology. Nature Reviews Cancer. 2015;15(4):248-254","pmid":"25673085","pmcid":"PMC5470637","doi":"10.1038/nrc3896","url":"https://pubmed.ncbi.nlm.nih.gov/25673085/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Stromal/collagen and density-related background tissue may encode case composition.","mechanism":"Mammographic density and collagen structure relate to breast cancer risk and may vary with race/ethnicity through BMI and reproductive factors.","features":"Collagen density, stromal texture, fibroglandular vs adipose composition, TDLU density.","confounders":"BMI, age, parity, menopause, sampling site, tumor adjacency.","validation":"Analyze benign/background tissue excluding tumor; match BMI/reproductive variables if available.","literature":[{"short_citation":"Burton et al., 2017","citation":"Burton A, Maskarinec G, Perez-Gomez B, et al. Mammographic density: intersection of advocacy, science, and clinical practice. Breast Cancer Research. 2017/2020 indexed","pmid":"33312342","pmcid":"PMC7728377","doi":"10.1007/s12609-019-00316-4","url":"https://pubmed.ncbi.nlm.nih.gov/33312342/","evidence_status":"needs claim-level validation"},{"short_citation":"McCarthy et al., 2016","citation":"McCarthy AM, Keller BM, Pantalone LM, et al. Racial Differences in Quantitative Measures of Area and Volumetric Breast Density. Journal of the National Cancer Institute. 2016;108(10):djw104","pmid":"27130893","pmcid":"PMC5939658","doi":"10.1093/jnci/djw104","url":"https://pubmed.ncbi.nlm.nih.gov/27130893/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Direct intrinsic race-specific benign breast morphology is not established.","mechanism":"Persistent signal outside tumor/subtype/density may reflect unmeasured socioeconomic, reproductive, obesity, or workflow variables.","features":"Benign lobules, ducts, stroma, adipose, inflammation.","confounders":"BMI, parity, menopause, screening, institution, procedure type.","validation":"Treat as exploratory; require reviewer confirmation and DOI-backed added references.","literature":[{"short_citation":"Reeder-Hayes et al., 2023","citation":"Reeder-Hayes K, Roberson ML, Wheeler SB, Abdou Y, Troester MA. From Race to Racism and Disparities to Equity: An Actionable Biopsychosocial Approach to Breast Cancer Outcomes. Cancer Journal. 2023;29(6):316-322","pmid":"37963365","pmcid":"PMC10651167","doi":"10.1097/PPO.0000000000000677","url":"https://pubmed.ncbi.nlm.nih.gov/37963365/","evidence_status":"needs claim-level validation"},{"short_citation":"Burton et al., 2017","citation":"Burton A, Maskarinec G, Perez-Gomez B, et al. Mammographic density: intersection of advocacy, science, and clinical practice. Breast Cancer Research. 2017/2020 indexed","pmid":"33312342","pmcid":"PMC7728377","doi":"10.1007/s12609-019-00316-4","url":"https://pubmed.ncbi.nlm.nih.gov/33312342/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The strongest review priority is subtype/stage/procedure matching, especially TNBC versus non-TNBC.","The most plausible H&E carriers are high-grade TNBC morphology, immune infiltrates, necrosis, and background fibroglandular/stromal composition.","Any residual race signal must be interpreted through structural determinants, ancestry limitations, and care-pathway confounding."],"references":[{"n":1,"raw":"Lund MJ, Trivers KF, Porter PL, et al. Race and triple negative threats to breast cancer survival: a population-based study in Atlanta, GA. Breast Cancer Research and Treatment. 2009;113(2):357-370. PMID: 18324472. DOI: 10.1007/s10549-008-9926-3. https://pubmed.ncbi.nlm.nih.gov/18324472/","citation":"Lund MJ, Trivers KF, Porter PL, et al. Race and triple negative threats to breast cancer survival: a population-based study in Atlanta, GA. Breast Cancer Research and Treatment. 2009;113(2):357-370","year":"2009","pmid":"18324472","doi":"10.1007/s10549-008-9926-3","url":"https://pubmed.ncbi.nlm.nih.gov/18324472/"},{"n":2,"raw":"Dietze EC, Sistrunk C, Miranda-Carboni G, O'Regan R, Seewaldt VL. Triple-negative breast cancer in African-American women: disparities versus biology. Nature Reviews Cancer. 2015;15(4):248-254. PMID: 25673085; PMCID: PMC5470637. DOI: 10.1038/nrc3896. https://pubmed.ncbi.nlm.nih.gov/25673085/","citation":"Dietze EC, Sistrunk C, Miranda-Carboni G, O'Regan R, Seewaldt VL. Triple-negative breast cancer in African-American women: disparities versus biology. Nature Reviews Cancer. 2015;15(4):248-254","year":"2015","pmid":"25673085","pmcid":"PMC5470637","doi":"10.1038/nrc3896","url":"https://pubmed.ncbi.nlm.nih.gov/25673085/"},{"n":3,"raw":"Yaghoobi V, Tewari M, Miller R, et al. Quantitative assessment of the immune microenvironment in African American Triple Negative Breast Cancer: a case-control study. Breast Cancer Research. 2021;23:99. DOI: 10.1186/s13058-021-01493-w. https://breast-cancer-research.biomedcentral.com/articles/10.1186/s13058-021-01493-w","citation":"Yaghoobi V, Tewari M, Miller R, et al. Quantitative assessment of the immune microenvironment in African American Triple Negative Breast Cancer: a case-control study. Breast Cancer Research. 2021;23:99","year":"2021","doi":"10.1186/s13058-021-01493-w","url":"https://breast-cancer-research.biomedcentral.com/articles/10.1186/s13058-021-01493-w"},{"n":4,"raw":"Torres JM, Sodipo MO, Hopkins MF, Chandler P, Warner ET. Racial Differences in Breast Cancer Survival Between Black and White Women According to Tumor Subtype: A Systematic Review and Meta-Analysis. Journal of Clinical Oncology. 2024;42:3867-3879. DOI: 10.1200/JCO.23.02311. https://ascopubs.org/doi/10.1200/JCO.23.02311","citation":"Torres JM, Sodipo MO, Hopkins MF, Chandler P, Warner ET. Racial Differences in Breast Cancer Survival Between Black and White Women According to Tumor Subtype: A Systematic Review and Meta-Analysis. Journal of Clinical Oncology. 2024;42:3867-3879","year":"2024","doi":"10.1200/JCO.23.02311","url":"https://ascopubs.org/doi/10.1200/JCO.23.02311"},{"n":5,"raw":"Reeder-Hayes K, Roberson ML, Wheeler SB, Abdou Y, Troester MA. From Race to Racism and Disparities to Equity: An Actionable Biopsychosocial Approach to Breast Cancer Outcomes. Cancer Journal. 2023;29(6):316-322. PMID: 37963365; PMCID: PMC10651167. DOI: 10.1097/PPO.0000000000000677. https://pubmed.ncbi.nlm.nih.gov/37963365/","citation":"Reeder-Hayes K, Roberson ML, Wheeler SB, Abdou Y, Troester MA. From Race to Racism and Disparities to Equity: An Actionable Biopsychosocial Approach to Breast Cancer Outcomes. Cancer Journal. 2023;29(6):316-322","year":"2023","pmid":"37963365","pmcid":"PMC10651167","doi":"10.1097/PPO.0000000000000677","url":"https://pubmed.ncbi.nlm.nih.gov/37963365/"},{"n":6,"raw":"Burton A, Maskarinec G, Perez-Gomez B, et al. Mammographic density: intersection of advocacy, science, and clinical practice. Breast Cancer Research. 2017/2020 indexed. PMID: 33312342; PMCID: PMC7728377. DOI: 10.1007/s12609-019-00316-4. https://pubmed.ncbi.nlm.nih.gov/33312342/","citation":"Burton A, Maskarinec G, Perez-Gomez B, et al. Mammographic density: intersection of advocacy, science, and clinical practice. Breast Cancer Research. 2017/2020 indexed","year":"2017","pmid":"33312342","pmcid":"PMC7728377","doi":"10.1007/s12609-019-00316-4","url":"https://pubmed.ncbi.nlm.nih.gov/33312342/"},{"n":7,"raw":"McCarthy AM, Keller BM, Pantalone LM, et al. Racial Differences in Quantitative Measures of Area and Volumetric Breast Density. Journal of the National Cancer Institute. 2016;108(10):djw104. PMID: 27130893; PMCID: PMC5939658. DOI: 10.1093/jnci/djw104. https://pubmed.ncbi.nlm.nih.gov/27130893/","citation":"McCarthy AM, Keller BM, Pantalone LM, et al. Racial Differences in Quantitative Measures of Area and Volumetric Breast Density. Journal of the National Cancer Institute. 2016;108(10):djw104","year":"2016","pmid":"27130893","pmcid":"PMC5939658","doi":"10.1093/jnci/djw104","url":"https://pubmed.ncbi.nlm.nih.gov/27130893/"},{"n":8,"raw":"Mariapun S, Li J, Yip CH, Taib NAM, Teo S-H. Ethnic Differences in Mammographic Densities: An Asian Cross-Sectional Study. PLOS ONE. 2015;10(2):e0117568. DOI: 10.1371/journal.pone.0117568. https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0117568","citation":"Mariapun S, Li J, Yip CH, Taib NAM, Teo S-H. Ethnic Differences in Mammographic Densities: An Asian Cross-Sectional Study. PLOS ONE. 2015;10(2):e0117568","year":"2015","doi":"10.1371/journal.pone.0117568","url":"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0117568"}],"filename":"breast__race_self_reported_ancestry.yaml"},{"combo":"cervix__age","organ_slug":"cervix","organ":"Cervix","demographic":"age","demographic_label":"Age","summary":"Cervix age signal is a stable residual candidate. Literature support centers on transformation-zone migration, squamous metaplasia, menopausal epithelial atrophy, glandular/squamous composition, and age-dependent screening/HPV/CIN context. The major review need is stronger modern pathology sources beyond the older transformation-zone literature.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Screening history and HPV/CIN diagnostic mix vary by age.","mechanism":"Younger patients may be enriched for HPV/CIN screening biopsies; older patients may have postmenopausal workups or invasive cancer contexts.","features":"CIN grade, HPV-related koilocytosis, invasive carcinoma, biopsy vs excision.","confounders":"Diagnosis, CIN grade, procedure type, screening indication, HPV status.","validation":"Match CIN grade and procedure type; test residual age signal within benign/CIN-only strata.","literature":[{"short_citation":"Singer, 1975","citation":"Singer A. The uterine cervix from adolescence to the menopause. British Journal of Obstetrics and Gynaecology. 1975","pmid":"1125147","doi":"10.1111/j.1471-0528.1975.tb02204.x","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Transformation-zone sampling differs by age.","mechanism":"The transformation zone changes position across life stages and menopause, altering squamous/endocervical tissue composition.","features":"Transformation zone, squamocolumnar junction, endocervical glands, ectocervical squamous mucosa.","confounders":"Sampling site, procedure type, menopausal status, inflammation.","validation":"Use report/site labels to stratify transformation-zone versus ectocervical/endocervical samples.","literature":[{"short_citation":"Singer, 1975","citation":"Singer A. The uterine cervix from adolescence to the menopause. British Journal of Obstetrics and Gynaecology. 1975","pmid":"1125147","doi":"10.1111/j.1471-0528.1975.tb02204.x","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Older patients may be enriched for atrophy-related or postmenopausal bleeding workups.","mechanism":"Low-estrogen mucosa is more fragile and may be sampled for bleeding, cytologic abnormality, or cancer exclusion.","features":"Atrophic squamous epithelium, scant stroma, inflammation, biopsy fragments with limited TZ.","confounders":"Menopausal status, hormone therapy, bleeding indication, procedure type.","validation":"Compare age signal in benign/postmenopausal workups separately from CIN/cancer.","literature":[{"short_citation":"Singer, 1975","citation":"Singer A. The uterine cervix from adolescence to the menopause. British Journal of Obstetrics and Gynaecology. 1975","pmid":"1125147","doi":"10.1111/j.1471-0528.1975.tb02204.x","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Excision versus biopsy mix may encode age and screening pathway.","mechanism":"LEEP/cone, hysterectomy, and punch biopsy have different tissue composition and age distributions.","features":"Cone/LEEP margins, cautery, endocervical glands, stromal depth, invasive carcinoma.","confounders":"Procedure type, CIN grade, margin status, cancer diagnosis.","validation":"Match procedure type before evaluating tissue-level age features.","literature":[{"short_citation":"Singer, 1975","citation":"Singer A. The uterine cervix from adolescence to the menopause. British Journal of Obstetrics and Gynaecology. 1975","pmid":"1125147","doi":"10.1111/j.1471-0528.1975.tb02204.x","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Menopause/age alters cervical squamous epithelium.","mechanism":"Hormonal involution can produce epithelial thinning/atrophy and altered maturation.","features":"Atrophic squamous epithelium, maturation pattern, basal/parabasal prominence.","confounders":"Menopausal status, inflammation, radiation/treatment, sampling site.","validation":"Quantify epithelial atrophy in benign cervix matched by site and inflammation.","literature":[{"short_citation":"Singer, 1975","citation":"Singer A. The uterine cervix from adolescence to the menopause. British Journal of Obstetrics and Gynaecology. 1975","pmid":"1125147","doi":"10.1111/j.1471-0528.1975.tb02204.x","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Squamous metaplasia and transformation-zone architecture can encode age.","mechanism":"Transformation-zone remodeling changes squamous/glandular proportions and metaplastic epithelium.","features":"Squamous metaplasia, reserve cells, gland involvement, SCJ architecture.","confounders":"CIN, HPV, inflammation, procedure type.","validation":"Match CIN/HPV context and compare benign transformation-zone morphology by age.","literature":[{"short_citation":"Singer, 1975","citation":"Singer A. The uterine cervix from adolescence to the menopause. British Journal of Obstetrics and Gynaecology. 1975","pmid":"1125147","doi":"10.1111/j.1471-0528.1975.tb02204.x","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Residual model signal may reflect tissue-composition rather than disease.","mechanism":"Different proportions of squamous, glandular, stromal, and transformation-zone tissue can persist after diagnosis matching.","features":"Squamous:gland ratio, stromal inflammation, endocervical gland density.","confounders":"Site, procedure, block selection, diagnosis.","validation":"Review attention maps for transformation-zone and atrophic epithelium after diagnosis matching.","literature":[{"short_citation":"Singer, 1975","citation":"Singer A. The uterine cervix from adolescence to the menopause. British Journal of Obstetrics and Gynaecology. 1975","pmid":"1125147","doi":"10.1111/j.1471-0528.1975.tb02204.x","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Chronic inflammation can amplify age- and menopause-associated morphology.","mechanism":"Atrophic mucosa and altered microbiome/inflammation may change stromal and epithelial appearance.","features":"Chronic cervicitis, lymphoplasmacytic inflammation, epithelial thinning, reactive atypia.","confounders":"Infection, HPV, atrophy, treatment, biopsy site.","validation":"Score inflammation separately from atrophy and CIN before assigning residual age mechanism.","literature":[{"short_citation":"Singer, 1975","citation":"Singer A. The uterine cervix from adolescence to the menopause. British Journal of Obstetrics and Gynaecology. 1975","pmid":"1125147","doi":"10.1111/j.1471-0528.1975.tb02204.x","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["Best review target: transformation-zone location, squamous metaplasia, and atrophic squamous epithelium.","Main shortcut risk: CIN/HPV grade, screening indication, and biopsy/excision procedure.","Needs stronger modern cervical histology sources before final manuscript claims."],"references":[{"n":1,"raw":"Singer A. The uterine cervix from adolescence to the menopause. British Journal of Obstetrics and Gynaecology. 1975. PMID: 1125147. DOI: 10.1111/j.1471-0528.1975.tb02204.x.","citation":"Singer A. The uterine cervix from adolescence to the menopause. British Journal of Obstetrics and Gynaecology. 1975","year":"1975","pmid":"1125147","doi":"10.1111/j.1471-0528.1975.tb02204.x"}],"filename":"cervix__age.yaml"},{"combo":"colon_rectum__age","organ_slug":"colon_rectum","organ":"Colon/Rectum","demographic":"age","demographic_label":"Age","summary":"Colon/rectum age signal is context-sensitive. The literature-supported mechanisms are age-dependent CRC/adenoma incidence, right-sided and serrated/sporadic pathways, early-onset CRC differences, hereditary context in younger patients, and age-related mucosal/molecular changes. Direct benign mucosal H&E aging signal is less certain.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Older patients are enriched for sporadic CRC, adenomas, and right-sided/serrated pathway lesions.","mechanism":"Age changes disease and precursor mix.","features":"Adenoma type, serrated lesions, CRC, right/left site, dysplasia.","confounders":"Diagnosis, subsite, procedure, screening, MSI/MMR.","validation":"Match diagnosis and subsite; test residual signal in benign mucosa.","literature":[{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"},{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Younger patients may be enriched for early-onset/hereditary or inflammatory contexts.","mechanism":"Early-onset CRC, IBD, and hereditary pathways can shift morphology and immune context.","features":"Tumor grade, lymphocytes, mucin, IBD changes, adenoma burden.","confounders":"Age group, hereditary syndrome, IBD, subsite, stage.","validation":"Stratify early-onset versus older CRC and match site/stage.","literature":[{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Screening and surveillance intensity can produce age-associated specimen mix.","mechanism":"Older cohorts may have more screening/surveillance polypectomies and cancer resections; younger cohorts more symptom/IBD workups.","features":"Normal biopsies, adenomas, serrated polyps, colectomy tissue, IBD surveillance biopsies.","confounders":"Screening status, procedure type, diagnosis, site.","validation":"Match screening/procedure categories and compare within benign polyp-only groups.","literature":[{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"},{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Diverticular, ischemic, and chronic injury contexts may enrich older cases.","mechanism":"Non-neoplastic age-related colorectal diagnoses can add fibrosis, inflammation, and mucosal injury.","features":"Ischemic change, diverticular-associated colitis, fibrosis, ulceration, active inflammation.","confounders":"Diagnosis, site, vascular disease, procedure, inflammation.","validation":"Separate neoplastic, inflammatory, ischemic/diverticular, and normal categories.","literature":[{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Age-linked molecular pathways may alter visible tumor morphology.","mechanism":"MSI, serrated, mucinous, and immune-rich tumors may vary with age and site.","features":"TILs, Crohn-like lymphoid reaction, mucin, serrated architecture.","confounders":"MSI/MMR, site, stage, grade, treatment.","validation":"Compare age signal after matching MSI/MMR and site.","literature":[{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"},{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Benign mucosal age morphology is plausible but not strongly established.","mechanism":"Aging may affect immune tone, epithelial renewal, and stromal background, but routine H&E evidence needs strengthening.","features":"Lamina propria inflammation, lymphoid aggregates, mucosal architecture.","confounders":"Diagnosis, prep/biopsy site, inflammation, IBD.","validation":"Inspect normal/benign mucosa after excluding neoplasia and inflammatory disease.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Serrated and adenomatous precursor architecture may be a visible age carrier.","mechanism":"Age-related polyp burden changes the mix of tubular/villous adenomas and serrated lesions.","features":"Tubular/villous architecture, dysplasia, serrated crypts, mucin cap.","confounders":"Polyp type, site, screening, age, molecular markers.","validation":"Match polyp subtype and site before interpreting age signal.","literature":[{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"},{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Stromal/inflammatory injury patterns may reflect non-neoplastic age context.","mechanism":"Ischemia, diverticular disease, and chronic injury can add fibrosis and inflammation.","features":"Fibrosis, muscularization, ulceration, active inflammation, vascular change.","confounders":"Diagnosis, site, vascular disease, IBD, diverticular disease.","validation":"Audit non-neoplastic older-case clusters for ischemic/diverticular labels.","literature":[{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"}],"key_takeaways":["Best review target: site, serrated lesions, mucin, MSI-like lymphocytes, adenoma/CRC subtype.","Main shortcut risk: age-skewed disease and subsite distribution.","Needs stronger benign mucosal aging sources for intrinsic morphology claims."],"references":[{"n":1,"raw":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020.","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","year":"2020"},{"n":2,"raw":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025. PMCID: PMC12347225.","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","year":"2025","pmcid":"PMC12347225"}],"filename":"colon_rectum__age.yaml"},{"combo":"colon_rectum__race_self_reported_ancestry","organ_slug":"colon_rectum","organ":"Colon/Rectum","demographic":"race_self_reported_ancestry","demographic_label":"Race / Self-Reported Ancestry","summary":"Colon/rectum race/self-reported ancestry appears in the top 15 because of high specimen availability and residual signal, but it is a context-sensitive candidate. The likely carriers are early-onset CRC, sidedness, screening/access, stage, molecular pathway, mucinous/serrated/MSI-like morphology, microbiome/exposure context, and institution/workflow. Direct intrinsic race-specific colorectal H&E morphology is not established.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"CRC incidence, early-onset CRC, stage, and screening access differ across racial groups.","mechanism":"Race/self-report may proxy structural determinants, screening, geography, and stage at presentation.","features":"Cancer vs benign, stage surrogates, resection vs biopsy, obstruction/perforation context.","confounders":"Diagnosis, stage, procedure, institution, screening history, age.","validation":"Match diagnosis/stage/procedure and audit institution/site distribution.","literature":[{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"},{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Tumor sidedness and molecular-pathway distributions may differ by group.","mechanism":"Right/left location, MSI, serrated pathway, and molecular subtype alter H&E morphology.","features":"Right vs left site, serrated lesions, mucinous features, TILs, lymphoid aggregates.","confounders":"Anatomic subsite, MSI/MMR, serrated pathway, age.","validation":"Match anatomic subsite and available molecular/pathology markers.","literature":[{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"},{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Screening colonoscopy and biopsy indication can create race-associated workflow signal.","mechanism":"Screening access and surveillance intervals alter proportions of normal biopsies, polyps, cancer, and resections.","features":"Normal mucosa, adenoma, serrated polyp, invasive cancer, biopsy vs colectomy.","confounders":"Screening status, procedure type, site, institution, age.","validation":"Compare within procedure/diagnosis groups and inspect normal-biopsy fraction.","literature":[{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Inflammation and IBD-related colorectal specimens may be unevenly represented.","mechanism":"Structural determinants and disease phenotype can alter chronic colitis, dysplasia surveillance, and resection mix.","features":"Chronic active colitis, architectural distortion, dysplasia, colectomy specimens.","confounders":"IBD diagnosis, medication, site, procedure, duration.","validation":"Exclude IBD or analyze IBD-only cases separately.","literature":[{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Residual signal may be mediated by mucinous, MSI-like, or serrated-pathway morphology.","mechanism":"Molecular pathway and anatomic-location differences create visible tumor and precursor patterns.","features":"Mucin, tumor-infiltrating lymphocytes, Crohn-like lymphoid reaction, serrated architecture.","confounders":"Tumor site, MSI/MMR, grade, stage, age.","validation":"Compare residual race signal after site, grade, and MSI/MMR matching where available.","literature":[{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"},{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Direct intrinsic race morphology is unsupported.","mechanism":"Persistent signal is more likely unmeasured context: site, stage, screening, exposure, microbiome, or institution.","features":"Background mucosa, inflammation, tumor microenvironment.","confounders":"Institution, geography, stain/scanner, comorbidities.","validation":"Treat residual signal as context until matched clinical/molecular audit is complete.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Serrated and right-sided precursor morphology may carry context signal.","mechanism":"Serrated lesions and right-sided tumors have distinctive architecture and may differ by screening and molecular pathway.","features":"Sessile serrated lesion architecture, crypt dilation, mucin cap, right-sided location.","confounders":"Site, polyp type, MSI/MMR, age, screening.","validation":"Match polyp subtype and location before interpreting race signal.","literature":[{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"},{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Tumor microenvironment features may be secondary to subtype, site, and stage.","mechanism":"Immune infiltrates and stromal reaction vary with MSI, tumor side, and treatment context.","features":"TILs, lymphoid aggregates, desmoplasia, necrosis, mucin.","confounders":"MSI/MMR, stage, site, treatment, grade.","validation":"Review only after site/stage/molecular matching; require added references for direct race/TME claims.","literature":[{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"},{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"}],"key_takeaways":["Best review target: right/left location, mucinous morphology, serrated lesions, MSI-like lymphocytes.","Main shortcut risk: stage, screening, subsite, and institution/access context.","This is a disease-distribution/context queue item, not a direct biology claim."],"references":[{"n":1,"raw":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020.","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","year":"2020"},{"n":2,"raw":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025. PMCID: PMC12347225.","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","year":"2025","pmcid":"PMC12347225"}],"filename":"colon_rectum__race_self_reported_ancestry.yaml"},{"combo":"colon_rectum__sex","organ_slug":"colon_rectum","organ":"Colon/Rectum","demographic":"sex","demographic_label":"Sex","summary":"Colon/rectum sex signal is context-sensitive with a large Drop %. It is best treated as a disease-distribution and subtype-mechanism candidate. Literature supports sex differences in CRC incidence, sidedness, screening/presentation, molecular pathways, immune context, sex hormone signaling, and gut microbiome interactions.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Men have higher overall CRC incidence, while women have different sidedness and presentation patterns.","mechanism":"Sex-skewed incidence and location can create diagnosis/subsite shortcuts.","features":"Right vs left colon, rectum, cancer vs benign, resection vs biopsy.","confounders":"Subsite, diagnosis, procedure, age, screening status.","validation":"Match subsite and diagnosis; compare residual sex signal within benign and CRC-only strata.","literature":[{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"},{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Sex differences in screening and molecular subtype can alter observed morphology.","mechanism":"MSI/serrated/right-sided patterns and screening detection may differ by sex.","features":"Serrated lesions, mucinous tumors, TILs, lymphoid aggregates, grade.","confounders":"MSI/MMR, serrated pathway, site, age.","validation":"Audit MSI/MMR and serrated-pathway markers where available.","literature":[{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"},{"short_citation":"Wu et al., 2024","citation":"Wu Z, et al. Sex differences in colorectal cancer with a focus on the sex hormone-gut microbiome axis. 2024","pmcid":"PMC10921775","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Procedure mix may differ by sex through screening and symptom pathways.","mechanism":"Colonoscopy biopsies, polypectomies, colectomies, and rectal cancer resections have different tissue composition.","features":"Biopsy vs polypectomy vs colectomy, adenoma/serrated lesion, cancer resection.","confounders":"Procedure type, site, diagnosis, screening vs symptom indication.","validation":"Match procedure and anatomic site; audit whether sex signal follows specimen type.","literature":[{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"},{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Inflammatory bowel disease and diverticular/inflammatory contexts may contribute.","mechanism":"Non-neoplastic colorectal specimens can differ by inflammatory diagnosis and site, creating non-tumor sex signal.","features":"Chronic colitis, diverticular disease, lymphoid aggregates, active inflammation.","confounders":"IBD, diverticulitis, site, age, medication.","validation":"Analyze neoplastic, inflammatory, and normal categories separately.","literature":[{"short_citation":"Wu et al., 2024","citation":"Wu Z, et al. Sex differences in colorectal cancer with a focus on the sex hormone-gut microbiome axis. 2024","pmcid":"PMC10921775","evidence_status":"source metadata incomplete"},{"short_citation":"Lattanzi et al., 2024","citation":"Lattanzi G, et al. Estrogen-related differences in antitumor immunity and gut microbiome contribute to sexual dimorphism of colorectal cancer. 2024","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Sex hormone, immune, and microbiome biology may shape CRC morphology indirectly.","mechanism":"Hormone-gut microbiome-immune interactions can affect tumor microenvironment and pathway.","features":"TILs, stromal immune state, mucin, serrated architecture.","confounders":"Tumor site, MSI/MMR, age, microbiome/exposure, treatment.","validation":"Compare residual signal after site and molecular-pathway matching.","literature":[{"short_citation":"Wu et al., 2024","citation":"Wu Z, et al. Sex differences in colorectal cancer with a focus on the sex hormone-gut microbiome axis. 2024","pmcid":"PMC10921775","evidence_status":"source metadata incomplete"},{"short_citation":"Lattanzi et al., 2024","citation":"Lattanzi G, et al. Estrogen-related differences in antitumor immunity and gut microbiome contribute to sexual dimorphism of colorectal cancer. 2024","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Large S3 drop suggests much sex signal is diagnosis/subsite/context mediated.","mechanism":"Diagnosis/context control removes a substantial part of the signal.","features":"Subsite, tumor morphology, adenoma/serrated lesions, inflammatory context.","confounders":"S3 cluster quality, diagnosis granularity, site labels.","validation":"Use Drop % leaderboard as disease-distribution investigation queue.","literature":[{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"},{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Serrated/MSI-like morphology may be an H&E-visible sex-associated pathway.","mechanism":"Right-sided serrated/MSI-rich tumors can show mucin, lymphocytes, and distinctive precursor architecture.","features":"Serrated crypts, mucinous histology, TILs, lymphoid aggregates.","confounders":"Site, MSI/MMR, polyp subtype, age.","validation":"Match site and molecular/precursor pathway before interpreting residual sex signal.","literature":[{"short_citation":"Tsokkou et al., 2025","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","pmcid":"PMC12347225","evidence_status":"source metadata incomplete"},{"short_citation":"Abancens et al., 2020","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Benign mucosal sex morphology remains lower confidence.","mechanism":"Persistent signal in normal mucosa may reflect microbiome, inflammation, preparation, or site imbalance rather than direct sex biology.","features":"Lamina propria cellularity, lymphoid aggregates, mucosal architecture, goblet cells.","confounders":"Site, inflammation, prep, diagnosis, age.","validation":"Treat benign residual signal as exploratory and add DOI-backed reviewer references before prioritizing.","literature":[{"short_citation":"Wu et al., 2024","citation":"Wu Z, et al. Sex differences in colorectal cancer with a focus on the sex hormone-gut microbiome axis. 2024","pmcid":"PMC10921775","evidence_status":"source metadata incomplete"},{"short_citation":"Lattanzi et al., 2024","citation":"Lattanzi G, et al. Estrogen-related differences in antitumor immunity and gut microbiome contribute to sexual dimorphism of colorectal cancer. 2024","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"}],"key_takeaways":["Best review target: subsite, serrated/MSI-like morphology, TILs, mucinous features.","Main shortcut risk: subsite and disease distribution.","This is a priority for disease-distribution explanation, not the strongest stable histology candidate."],"references":[{"n":1,"raw":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020.","citation":"Abancens M, Bustos V, Harvey H, McBryan J, Harvey BJ. Sexual Dimorphism in Colon Cancer. Frontiers in Oncology. 2020","year":"2020"},{"n":2,"raw":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025. PMCID: PMC12347225.","citation":"Tsokkou S, et al. Sex Differences in Colorectal Cancer: Epidemiology, Risk, Screening, and Molecular Mechanisms. 2025","year":"2025","pmcid":"PMC12347225"},{"n":3,"raw":"Wu Z, et al. Sex differences in colorectal cancer with a focus on the sex hormone-gut microbiome axis. 2024. PMCID: PMC10921775.","citation":"Wu Z, et al. Sex differences in colorectal cancer with a focus on the sex hormone-gut microbiome axis. 2024","year":"2024","pmcid":"PMC10921775"},{"n":4,"raw":"Lattanzi G, et al. Estrogen-related differences in antitumor immunity and gut microbiome contribute to sexual dimorphism of colorectal cancer. 2024.","citation":"Lattanzi G, et al. Estrogen-related differences in antitumor immunity and gut microbiome contribute to sexual dimorphism of colorectal cancer. 2024","year":"2024"}],"filename":"colon_rectum__sex.yaml"},{"combo":"esophagus__age","organ_slug":"esophagus","organ":"Esophagus","demographic":"age","demographic_label":"Age","summary":"Age signal in esophageal histology is likely a mixture of clinical-context shortcuts and cumulative mucosal injury. Older patients are more likely to have Barrett esophagus, dysplasia, adenocarcinoma, and chronic reflux-related sampling, while younger patients may be relatively enriched for eosinophilic esophagitis or uncomplicated reflux biopsies. A residual signal after diagnosis balancing should be interpreted as chronic injury/metaplasia/remodeling until benign, non-Barrett squamous mucosa is reviewed separately.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Older patients may be enriched for Barrett esophagus and Barrett surveillance biopsies.","mechanism":"Barrett prevalence is associated with older age and GERD-related risk factors, increasing intestinal metaplasia and surveillance sampling in older cohorts.","features":"Columnar mucosa, goblet cells, intestinal metaplasia, GE-junction biopsies, multi-level surveillance jars.","confounders":"Barrett status, GERD, biopsy site, surveillance vs diagnostic biopsy, sex, smoking.","validation":"Compare age prediction after excluding Barrett biopsies, then within Barrett-only and non-Barrett-only strata.","literature":[{"short_citation":"van Blankenstein et al., 2005","citation":"van Blankenstein M, Looman CWN, Johnston BJ, Caygill CPJ. Age and sex distribution of the prevalence of Barrett's esophagus found in a primary referral endoscopy center. American Journal of Gastroenterology. 2005","pmid":"15743353","url":"https://pubmed.ncbi.nlm.nih.gov/15743353/","evidence_status":"needs claim-level validation"},{"short_citation":"Ward et al., 2006","citation":"Ward EM, Wolfsen HC, Achem SR, et al. Barrett's esophagus is common in older men and women undergoing screening colonoscopy regardless of reflux symptoms. American Journal of Gastroenterology. 2006","pmid":"16405528","url":"https://pubmed.ncbi.nlm.nih.gov/16405528/","evidence_status":"needs claim-level validation"},{"short_citation":"Sharma, 2022","citation":"Sharma P. Barrett Esophagus: A Review. JAMA. 2022;328(7):663-671","doi":"10.1001/jama.2022.13298","url":"https://jamanetwork.com/journals/jama/article-abstract/2795263","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Older patients may be enriched for dysplasia and carcinoma pathways.","mechanism":"Barrett-associated dysplasia/adenocarcinoma and esophageal carcinoma workups increase visible neoplasia and procedure differences.","features":"Low/high-grade dysplasia, adenocarcinoma, squamous cell carcinoma, necrosis, invasion, EMR/resection tissue.","confounders":"Diagnosis, tumor histology, stage, procedure type, prior treatment.","validation":"Exclude carcinoma/dysplasia or match dysplasia/tumor category before interpreting residual age signal.","literature":[{"short_citation":"Sharma, 2022","citation":"Sharma P. Barrett Esophagus: A Review. JAMA. 2022;328(7):663-671","doi":"10.1001/jama.2022.13298","url":"https://jamanetwork.com/journals/jama/article-abstract/2795263","evidence_status":"needs claim-level validation"},{"short_citation":"Odze, 2009","citation":"Odze RD. Barrett esophagus: histology and pathology for the clinician. Nature Reviews Gastroenterology & Hepatology. 2009;6(8):478-490","pmid":"19581906","doi":"10.1038/nrgastro.2009.103","url":"https://pubmed.ncbi.nlm.nih.gov/19581906/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Younger patients may be enriched for eosinophilic esophagitis or inflammatory symptom workups.","mechanism":"Age-skewed workup pathways can separate eosinophil-rich squamous biopsies from Barrett/cancer pathways.","features":"Eosinophil density, eosinophilic microabscesses, basal-zone hyperplasia, papillary elongation, lamina propria fibrosis.","confounders":"EoE diagnosis, atopy, reflux diagnosis, steroid/PPI treatment, biopsy level.","validation":"Stratify reflux/EoE/Barrett categories and test whether age signal follows diagnostic mix.","literature":[{"short_citation":"Mastracci et al., 2020","citation":"Mastracci L, Grillo F, Parente P, et al. Gastro-esophageal reflux disease and Barrett's esophagus: an overview with a histologic diagnostic approach. Pathologica. 2020","doi":"10.32074/1591-951X-162","url":"https://old.pathologica.it/article/view/162","evidence_status":"needs claim-level validation"},{"short_citation":"Odze, 2009","citation":"Odze RD. Barrett esophagus: histology and pathology for the clinician. Nature Reviews Gastroenterology & Hepatology. 2009;6(8):478-490","pmid":"19581906","doi":"10.1038/nrgastro.2009.103","url":"https://pubmed.ncbi.nlm.nih.gov/19581906/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Procedure and anatomic sampling pattern may encode age.","mechanism":"Older cohorts may have more GE-junction, Barrett surveillance, EMR, and tumor resections; younger cohorts may have limited mucosal biopsies.","features":"Biopsy vs EMR/resection, GEJ vs mid/proximal esophagus, number of tissue fragments, ulcer/treatment effect.","confounders":"Procedure type, anatomic level, indication, institution.","validation":"Match specimen type and esophageal level; audit whether model attention localizes to sampling context.","literature":[{"short_citation":"Bellizzi & Odze, 2010","citation":"Bellizzi AM, Odze RD. Histopathology of Barrett's esophagus: A review for the practicing gastroenterologist. Techniques in Gastrointestinal Endoscopy. 2010;12(2):69-81","doi":"10.1016/j.tgie.2010.02.008","evidence_status":"needs claim-level validation"},{"short_citation":"Sharma, 2022","citation":"Sharma P. Barrett Esophagus: A Review. JAMA. 2022;328(7):663-671","doi":"10.1001/jama.2022.13298","url":"https://jamanetwork.com/journals/jama/article-abstract/2795263","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Cumulative reflux injury may encode age in squamous mucosa.","mechanism":"Longer cumulative exposure to reflux and injury can produce basal-zone hyperplasia, papillary elongation, inflammation, and erosive change.","features":"Basal-zone thickness, papillary elongation, spongiosis, neutrophils/eosinophils, erosions.","confounders":"GERD diagnosis, PPI use, EoE, infection, biopsy level.","validation":"Restrict to non-Barrett squamous biopsies and score reflux-pattern injury by age.","literature":[{"short_citation":"Mastracci et al., 2020","citation":"Mastracci L, Grillo F, Parente P, et al. Gastro-esophageal reflux disease and Barrett's esophagus: an overview with a histologic diagnostic approach. Pathologica. 2020","doi":"10.32074/1591-951X-162","url":"https://old.pathologica.it/article/view/162","evidence_status":"needs claim-level validation"},{"short_citation":"Odze, 2009","citation":"Odze RD. Barrett esophagus: histology and pathology for the clinician. Nature Reviews Gastroenterology & Hepatology. 2009;6(8):478-490","pmid":"19581906","doi":"10.1038/nrgastro.2009.103","url":"https://pubmed.ncbi.nlm.nih.gov/19581906/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Barrett metaplasia creates a strong age-associated morphology.","mechanism":"Replacement of squamous mucosa by columnar epithelium with goblet cells is directly visible on H&E.","features":"Goblet cells, columnar mucosa, cardia-type mucosa, dysplasia, glandular architecture.","confounders":"Barrett diagnosis, GEJ biopsy, surveillance status, sex.","validation":"Run a Barrett-excluded analysis and a Barrett-only residual age analysis.","literature":[{"short_citation":"Sharma, 2022","citation":"Sharma P. Barrett Esophagus: A Review. JAMA. 2022;328(7):663-671","doi":"10.1001/jama.2022.13298","url":"https://jamanetwork.com/journals/jama/article-abstract/2795263","evidence_status":"needs claim-level validation"},{"short_citation":"Bellizzi & Odze, 2010","citation":"Bellizzi AM, Odze RD. Histopathology of Barrett's esophagus: A review for the practicing gastroenterologist. Techniques in Gastrointestinal Endoscopy. 2010;12(2):69-81","doi":"10.1016/j.tgie.2010.02.008","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Chronic injury may remodel lamina propria and stromal architecture.","mechanism":"Reflux/EoE/chronic inflammation can produce fibrosis, vascularity, and reactive epithelial change.","features":"Lamina propria fibrosis, vascular congestion, ulcer bed, reactive epithelial atypia.","confounders":"Ulceration, EoE, reflux severity, procedure depth, treatment.","validation":"Quantify stromal fibrosis and reactive change within diagnosis-matched squamous mucosa.","literature":[{"short_citation":"Mastracci et al., 2020","citation":"Mastracci L, Grillo F, Parente P, et al. Gastro-esophageal reflux disease and Barrett's esophagus: an overview with a histologic diagnostic approach. Pathologica. 2020","doi":"10.32074/1591-951X-162","url":"https://old.pathologica.it/article/view/162","evidence_status":"needs claim-level validation"},{"short_citation":"Odze, 2009","citation":"Odze RD. Barrett esophagus: histology and pathology for the clinician. Nature Reviews Gastroenterology & Hepatology. 2009;6(8):478-490","pmid":"19581906","doi":"10.1038/nrgastro.2009.103","url":"https://pubmed.ncbi.nlm.nih.gov/19581906/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Residual age signal in tumor slides may reflect histologic subtype or treatment context.","mechanism":"Age can shift the proportion of adenocarcinoma, squamous carcinoma, dysplasia, and post-treatment specimens.","features":"Tumor subtype, gland formation, keratinization, necrosis, treatment effect, desmoplasia.","confounders":"Tumor histology, stage, treatment status, sampling type.","validation":"Perform tumor-only analysis matched by subtype/stage and separate background mucosa from tumor regions.","literature":[{"short_citation":"Sharma, 2022","citation":"Sharma P. Barrett Esophagus: A Review. JAMA. 2022;328(7):663-671","doi":"10.1001/jama.2022.13298","url":"https://jamanetwork.com/journals/jama/article-abstract/2795263","evidence_status":"needs claim-level validation"},{"short_citation":"Odze, 2009","citation":"Odze RD. Barrett esophagus: histology and pathology for the clinician. Nature Reviews Gastroenterology & Hepatology. 2009;6(8):478-490","pmid":"19581906","doi":"10.1038/nrgastro.2009.103","url":"https://pubmed.ncbi.nlm.nih.gov/19581906/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The highest-risk shortcut is Barrett/GEJ surveillance and carcinoma/dysplasia case mix.","The most plausible residual tissue signal is cumulative squamous injury and stromal remodeling, but this must be tested after excluding Barrett and tumor cases.","Priority review should first label Barrett, dysplasia/cancer, EoE, reflux injury, and biopsy site."],"references":[{"n":1,"raw":"van Blankenstein M, Looman CWN, Johnston BJ, Caygill CPJ. Age and sex distribution of the prevalence of Barrett's esophagus found in a primary referral endoscopy center. American Journal of Gastroenterology. 2005. PMID: 15743353. https://pubmed.ncbi.nlm.nih.gov/15743353/","citation":"van Blankenstein M, Looman CWN, Johnston BJ, Caygill CPJ. Age and sex distribution of the prevalence of Barrett's esophagus found in a primary referral endoscopy center. American Journal of Gastroenterology. 2005","year":"2005","pmid":"15743353","url":"https://pubmed.ncbi.nlm.nih.gov/15743353/"},{"n":2,"raw":"Ward EM, Wolfsen HC, Achem SR, et al. Barrett's esophagus is common in older men and women undergoing screening colonoscopy regardless of reflux symptoms. American Journal of Gastroenterology. 2006. PMID: 16405528. https://pubmed.ncbi.nlm.nih.gov/16405528/","citation":"Ward EM, Wolfsen HC, Achem SR, et al. Barrett's esophagus is common in older men and women undergoing screening colonoscopy regardless of reflux symptoms. American Journal of Gastroenterology. 2006","year":"2006","pmid":"16405528","url":"https://pubmed.ncbi.nlm.nih.gov/16405528/"},{"n":3,"raw":"Sharma P. Barrett Esophagus: A Review. JAMA. 2022;328(7):663-671. DOI: 10.1001/jama.2022.13298. https://jamanetwork.com/journals/jama/article-abstract/2795263","citation":"Sharma P. Barrett Esophagus: A Review. JAMA. 2022;328(7):663-671","year":"2022","doi":"10.1001/jama.2022.13298","url":"https://jamanetwork.com/journals/jama/article-abstract/2795263"},{"n":4,"raw":"Odze RD. Barrett esophagus: histology and pathology for the clinician. Nature Reviews Gastroenterology & Hepatology. 2009;6(8):478-490. PMID: 19581906. DOI: 10.1038/nrgastro.2009.103. https://pubmed.ncbi.nlm.nih.gov/19581906/","citation":"Odze RD. Barrett esophagus: histology and pathology for the clinician. Nature Reviews Gastroenterology & Hepatology. 2009;6(8):478-490","year":"2009","pmid":"19581906","doi":"10.1038/nrgastro.2009.103","url":"https://pubmed.ncbi.nlm.nih.gov/19581906/"},{"n":5,"raw":"Bellizzi AM, Odze RD. Histopathology of Barrett's esophagus: A review for the practicing gastroenterologist. Techniques in Gastrointestinal Endoscopy. 2010;12(2):69-81. DOI: 10.1016/j.tgie.2010.02.008.","citation":"Bellizzi AM, Odze RD. Histopathology of Barrett's esophagus: A review for the practicing gastroenterologist. Techniques in Gastrointestinal Endoscopy. 2010;12(2):69-81","year":"2010","doi":"10.1016/j.tgie.2010.02.008"},{"n":6,"raw":"Mastracci L, Grillo F, Parente P, et al. Gastro-esophageal reflux disease and Barrett's esophagus: an overview with a histologic diagnostic approach. Pathologica. 2020. DOI: 10.32074/1591-951X-162. https://old.pathologica.it/article/view/162","citation":"Mastracci L, Grillo F, Parente P, et al. Gastro-esophageal reflux disease and Barrett's esophagus: an overview with a histologic diagnostic approach. Pathologica. 2020","year":"2020","doi":"10.32074/1591-951X-162","url":"https://old.pathologica.it/article/view/162"}],"filename":"esophagus__age.yaml"},{"combo":"esophagus__sex","organ_slug":"esophagus","organ":"Esophagus","demographic":"sex","demographic_label":"Sex","summary":"Esophagus sex signal is a moderate residual candidate. The strongest literature-supported shortcut is male enrichment for Barrett esophagus and esophageal adenocarcinoma pathways. Residual H&E signal may reflect Barrett/glandular metaplasia, dysplasia, reflux injury, or subtype/site context rather than direct sex-specific esophageal morphology.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Men are overrepresented in Barrett esophagus and esophageal adenocarcinoma pathways.","mechanism":"Sex-skewed Barrett/metaplasia/cancer prevalence can create diagnosis and subtype shortcuts.","features":"Barrett intestinal metaplasia, dysplasia, adenocarcinoma, glandular mucosa.","confounders":"Barrett diagnosis, cancer status, anatomic site, age, reflux/obesity context.","validation":"Match Barrett/cancer status and compare residual sex signal in squamous-only biopsies.","literature":[{"short_citation":"van Blankenstein et al., 2005","citation":"van Blankenstein M, Looman CWN, Johnston BJ, Caygill CPJ. Age and sex distribution of the prevalence of Barrett's esophagus found in a primary referral endoscopy center. American Journal of Gastroenterology. 2005","pmid":"15743353","evidence_status":"needs claim-level validation"},{"short_citation":"Ward et al., 2006","citation":"Ward EM, et al. Barrett's esophagus is common in older men and women undergoing screening colonoscopy regardless of reflux symptoms. American Journal of Gastroenterology. 2006","pmid":"16405528","evidence_status":"needs claim-level validation"},{"short_citation":"Stabellini et al., 2022","citation":"Stabellini N, et al. Sex differences in esophageal cancer overall and by histological subtype. Scientific Reports. 2022","doi":"10.1038/s41598-022-09193-x","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Histologic subtype distribution differs by sex in esophageal cancer.","mechanism":"Adenocarcinoma and squamous carcinoma have distinct H&E patterns and sex distributions.","features":"SCC vs adenocarcinoma, keratinization, gland formation, tumor site.","confounders":"Histologic subtype, stage, site, smoking/alcohol/GERD context.","validation":"Match SCC/adenocarcinoma and tumor site before interpreting residual sex signal.","literature":[{"short_citation":"Stabellini et al., 2022","citation":"Stabellini N, et al. Sex differences in esophageal cancer overall and by histological subtype. Scientific Reports. 2022","doi":"10.1038/s41598-022-09193-x","evidence_status":"needs claim-level validation"},{"short_citation":"Sanford et al., 2019","citation":"Sanford NN, Mahal BA, Royce TJ, Pike LRG, Hwang WL. Sex Disparity and Copy Number Alterations in Esophageal Squamous Cell Carcinoma. Clinical Gastroenterology and Hepatology. 2019","pmid":"30120994","doi":"10.1016/j.cgh.2018.08.026","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Reflux, obesity, and GE-junction sampling may mediate male-enriched Barrett pathways.","mechanism":"Clinical risk factors shift sampling toward distal esophagus/GEJ and columnar metaplasia.","features":"GEJ biopsies, cardia-type mucosa, erosive injury, Barrett surveillance fragments.","confounders":"BMI/obesity proxy, reflux diagnosis, biopsy site, age, smoking.","validation":"Match distal/GEJ site and Barrett status; test squamous-only residual sex signal.","literature":[{"short_citation":"van Blankenstein et al., 2005","citation":"van Blankenstein M, Looman CWN, Johnston BJ, Caygill CPJ. Age and sex distribution of the prevalence of Barrett's esophagus found in a primary referral endoscopy center. American Journal of Gastroenterology. 2005","pmid":"15743353","evidence_status":"needs claim-level validation"},{"short_citation":"Ward et al., 2006","citation":"Ward EM, et al. Barrett's esophagus is common in older men and women undergoing screening colonoscopy regardless of reflux symptoms. American Journal of Gastroenterology. 2006","pmid":"16405528","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Treatment and procedure type may encode sex in cancer cohorts.","mechanism":"EMR/resection, ablation surveillance, and tumor resections differ from routine biopsies and may be imbalanced.","features":"EMR fragments, cautery, tumor invasion, treatment effect, surveillance biopsies.","confounders":"Procedure type, cancer status, treatment, site, institution.","validation":"Exclude treated/resection cases or match procedure type before morphology review.","literature":[{"short_citation":"Stabellini et al., 2022","citation":"Stabellini N, et al. Sex differences in esophageal cancer overall and by histological subtype. Scientific Reports. 2022","doi":"10.1038/s41598-022-09193-x","evidence_status":"needs claim-level validation"},{"short_citation":"Odze, 2009","citation":"Odze, 2009","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Barrett/glandular metaplasia is the most likely H&E-visible sex carrier.","mechanism":"Male enrichment for Barrett/EAC pathways can produce residual glandular metaplasia/dysplasia signal.","features":"Intestinal metaplasia, goblet cells, dysplasia, glandular mucosa.","confounders":"Barrett diagnosis, biopsy site, age, reflux, obesity.","validation":"Exclude Barrett and glandular mucosa; test sex signal in squamous-only biopsies.","literature":[{"short_citation":"van Blankenstein et al., 2005","citation":"van Blankenstein M, Looman CWN, Johnston BJ, Caygill CPJ. Age and sex distribution of the prevalence of Barrett's esophagus found in a primary referral endoscopy center. American Journal of Gastroenterology. 2005","pmid":"15743353","evidence_status":"needs claim-level validation"},{"short_citation":"Ward et al., 2006","citation":"Ward EM, et al. Barrett's esophagus is common in older men and women undergoing screening colonoscopy regardless of reflux symptoms. American Journal of Gastroenterology. 2006","pmid":"16405528","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Direct sex morphology in normal esophageal mucosa is uncertain.","mechanism":"Hormonal/adiposity/reflux-related biology is plausible but not directly proven as routine H&E sex morphology.","features":"Basal hyperplasia, papillary elongation, chronic inflammation, eosinophils.","confounders":"Reflux, eosinophilic esophagitis, site, diagnosis.","validation":"Review benign squamous mucosa after reflux/EoE/Barrett matching.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Squamous versus glandular tissue composition may be enough to drive sex classification.","mechanism":"The model may separate columnar/Barrett/GEJ tissue from squamous biopsies if these are sex imbalanced.","features":"Squamous mucosa, glandular mucosa, goblet cells, cardia-type glands.","confounders":"Biopsy site, Barrett status, GEJ sampling, procedure type.","validation":"Run a tissue-compartment audit before assigning biological mechanism.","literature":[{"short_citation":"Odze, 2009","citation":"Odze, 2009","evidence_status":"source metadata incomplete"},{"short_citation":"van Blankenstein et al., 2005","citation":"van Blankenstein M, Looman CWN, Johnston BJ, Caygill CPJ. Age and sex distribution of the prevalence of Barrett's esophagus found in a primary referral endoscopy center. American Journal of Gastroenterology. 2005","pmid":"15743353","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Cancer subtype morphology can masquerade as sex signal.","mechanism":"SCC and adenocarcinoma differ strongly on H&E and have sex-skewed incidence patterns.","features":"Keratinization, gland formation, mucin, desmoplasia, necrosis.","confounders":"Histologic subtype, site, stage, treatment.","validation":"Evaluate tumor-only slides with subtype/stage matched; report remaining signal separately.","literature":[{"short_citation":"Stabellini et al., 2022","citation":"Stabellini N, et al. Sex differences in esophageal cancer overall and by histological subtype. Scientific Reports. 2022","doi":"10.1038/s41598-022-09193-x","evidence_status":"needs claim-level validation"},{"short_citation":"Sanford et al., 2019","citation":"Sanford NN, Mahal BA, Royce TJ, Pike LRG, Hwang WL. Sex Disparity and Copy Number Alterations in Esophageal Squamous Cell Carcinoma. Clinical Gastroenterology and Hepatology. 2019","pmid":"30120994","doi":"10.1016/j.cgh.2018.08.026","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["Best review target: Barrett metaplasia, dysplasia, adenocarcinoma versus squamous histology.","Main shortcut risk: histologic subtype, site, reflux/Barrett workup, and age.","Residual sex signal should be interpreted cautiously unless present in matched squamous mucosa."],"references":[{"n":1,"raw":"Stabellini N, et al. Sex differences in esophageal cancer overall and by histological subtype. Scientific Reports. 2022. DOI: 10.1038/s41598-022-09193-x.","citation":"Stabellini N, et al. Sex differences in esophageal cancer overall and by histological subtype. Scientific Reports. 2022","year":"2022","doi":"10.1038/s41598-022-09193-x"},{"n":2,"raw":"Sanford NN, Mahal BA, Royce TJ, Pike LRG, Hwang WL. Sex Disparity and Copy Number Alterations in Esophageal Squamous Cell Carcinoma. Clinical Gastroenterology and Hepatology. 2019. PMID: 30120994. DOI: 10.1016/j.cgh.2018.08.026.","citation":"Sanford NN, Mahal BA, Royce TJ, Pike LRG, Hwang WL. Sex Disparity and Copy Number Alterations in Esophageal Squamous Cell Carcinoma. Clinical Gastroenterology and Hepatology. 2019","year":"2019","pmid":"30120994","doi":"10.1016/j.cgh.2018.08.026"},{"n":3,"raw":"van Blankenstein M, Looman CWN, Johnston BJ, Caygill CPJ. Age and sex distribution of the prevalence of Barrett's esophagus found in a primary referral endoscopy center. American Journal of Gastroenterology. 2005. PMID: 15743353.","citation":"van Blankenstein M, Looman CWN, Johnston BJ, Caygill CPJ. Age and sex distribution of the prevalence of Barrett's esophagus found in a primary referral endoscopy center. American Journal of Gastroenterology. 2005","year":"2005","pmid":"15743353"},{"n":4,"raw":"Ward EM, et al. Barrett's esophagus is common in older men and women undergoing screening colonoscopy regardless of reflux symptoms. American Journal of Gastroenterology. 2006. PMID: 16405528.","citation":"Ward EM, et al. Barrett's esophagus is common in older men and women undergoing screening colonoscopy regardless of reflux symptoms. American Journal of Gastroenterology. 2006","year":"2006","pmid":"16405528"}],"filename":"esophagus__sex.yaml"},{"combo":"gall_bladder__sex","organ_slug":"gall_bladder","organ":"Gall Bladder","demographic":"sex","demographic_label":"Sex","summary":"Gall bladder sex signal is a moderate residual candidate. The likely carrier is strongly clinical-contextual: gallstone disease and cholecystitis risk are sex-skewed through reproductive, metabolic, obesity, and hormonal factors. H&E signal may reflect chronic cholecystitis, gallstone injury, cholesterolosis, fibrosis, metaplasia, dysplasia, and carcinoma context rather than intrinsic sex-specific gallbladder wall morphology.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Gallstone disease has sex-skewed risk factors.","mechanism":"Female sex, reproductive factors, obesity/metabolic context, and hormones can increase cholelithiasis/cholecystectomy pathways.","features":"Chronic cholecystitis, gallstone-related injury, cholesterolosis, Rokitansky-Aschoff sinuses.","confounders":"Diagnosis, gallstones, age, BMI/metabolic disease, pregnancy/parity if available.","validation":"Match cholecystitis/gallstones and age; retest residual sex signal.","literature":[{"short_citation":"Stinton & Shaffer, 2012","citation":"Stinton LM, Shaffer EA. Epidemiology of Gallbladder Disease: Cholelithiasis and Cancer. Gut and Liver. 2012","pmcid":"PMC3343155","evidence_status":"source metadata incomplete"},{"short_citation":"Figueiredo et al., 2017","citation":"Figueiredo JC, et al. Sex and ethnic/racial-specific risk factors for gallbladder disease. 2017","pmcid":"PMC5723039","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Gallbladder carcinoma and chronic injury context may differ by sex and risk background.","mechanism":"Chronic gallstone injury can lead to metaplasia/dysplasia/carcinoma with H&E-visible features.","features":"Pyloric/intestinal metaplasia, dysplasia, carcinoma, fibrosis, xanthogranulomatous inflammation.","confounders":"Cancer status, chronic cholecystitis severity, ethnicity/race, age.","validation":"Exclude carcinoma/dysplasia and compare chronic cholecystitis-only specimens.","literature":[{"short_citation":"Stinton & Shaffer, 2012","citation":"Stinton LM, Shaffer EA. Epidemiology of Gallbladder Disease: Cholelithiasis and Cancer. Gut and Liver. 2012","pmcid":"PMC3343155","evidence_status":"source metadata incomplete"},{"short_citation":"Figueiredo et al., 2017","citation":"Figueiredo JC, et al. Sex and ethnic/racial-specific risk factors for gallbladder disease. 2017","pmcid":"PMC5723039","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Cholecystectomy indication and acute/chronic inflammation mix may differ by sex.","mechanism":"Gallstone risk affects elective chronic cholecystitis versus acute/emergency pathways.","features":"Acute cholecystitis, chronic cholecystitis, empyema, wall edema, necrosis.","confounders":"Acute vs chronic diagnosis, gallstones, age, BMI/metabolic risk, pregnancy context.","validation":"Match acute/chronic cholecystitis severity and exclude carcinoma before reviewing sex signal.","literature":[{"short_citation":"Stinton & Shaffer, 2012","citation":"Stinton LM, Shaffer EA. Epidemiology of Gallbladder Disease: Cholelithiasis and Cancer. Gut and Liver. 2012","pmcid":"PMC3343155","evidence_status":"source metadata incomplete"},{"short_citation":"Figueiredo et al., 2017","citation":"Figueiredo JC, et al. Sex and ethnic/racial-specific risk factors for gallbladder disease. 2017","pmcid":"PMC5723039","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Metabolic and reproductive risk factors may be hidden mediators.","mechanism":"Obesity, parity, hormones, diabetes, and lipid metabolism affect gallstone formation and chronic injury.","features":"Cholesterolosis, gallstones, chronic inflammation, fibrosis, mucosal hyperplasia.","confounders":"BMI, diabetes, parity/pregnancy, age, ethnicity/race.","validation":"Use available metadata proxies and treat residual as risk-factor mediated unless matched.","literature":[{"short_citation":"Figueiredo et al., 2017","citation":"Figueiredo JC, et al. Sex and ethnic/racial-specific risk factors for gallbladder disease. 2017","pmcid":"PMC5723039","evidence_status":"source metadata incomplete"},{"short_citation":"Stinton & Shaffer, 2012","citation":"Stinton LM, Shaffer EA. Epidemiology of Gallbladder Disease: Cholelithiasis and Cancer. Gut and Liver. 2012","pmcid":"PMC3343155","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Sex signal likely reflects gallstone/chronic injury morphology.","mechanism":"Sex-skewed lithogenic risk creates H&E-visible chronic inflammation and remodeling.","features":"Chronic inflammation, fibrosis, Rokitansky-Aschoff sinuses, cholesterolosis.","confounders":"Gallstone status, age, metabolic risk, procedure indication.","validation":"Review only chronic cholecystitis cases matched for severity and age.","literature":[{"short_citation":"Stinton & Shaffer, 2012","citation":"Stinton LM, Shaffer EA. Epidemiology of Gallbladder Disease: Cholelithiasis and Cancer. Gut and Liver. 2012","pmcid":"PMC3343155","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Direct intrinsic sex morphology of gallbladder wall is not established.","mechanism":"Persistent signal after matching may reflect unmeasured metabolic/reproductive context or incomplete diagnosis control.","features":"Background mucosa and muscular wall after excluding stones/cancer.","confounders":"Stone status, inflammation, BMI, parity, ethnicity, institution.","validation":"Treat residual sex signal cautiously unless gallstone/injury context is controlled.","literature":[{"short_citation":"Figueiredo et al., 2017","citation":"Figueiredo JC, et al. Sex and ethnic/racial-specific risk factors for gallbladder disease. 2017","pmcid":"PMC5723039","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Rokitansky-Aschoff sinuses and mural fibrosis may carry chronic injury signal.","mechanism":"Longstanding cholelithiasis/cholecystitis remodels mucosa and wall architecture.","features":"Rokitansky-Aschoff sinuses, muscular hypertrophy, fibrosis, chronic inflammation.","confounders":"Gallstones, chronicity, age, acute inflammation, procedure indication.","validation":"Score chronic cholecystitis severity within sex-balanced groups.","literature":[{"short_citation":"Stinton & Shaffer, 2012","citation":"Stinton LM, Shaffer EA. Epidemiology of Gallbladder Disease: Cholelithiasis and Cancer. Gut and Liver. 2012","pmcid":"PMC3343155","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Cholesterolosis and metaplasia/dysplasia patterns should be interpreted as disease context.","mechanism":"Lipid/metabolic injury and chronic inflammation produce visible mucosal changes that may be sex-skewed.","features":"Cholesterolosis, pyloric/intestinal metaplasia, dysplasia, xanthogranulomatous inflammation.","confounders":"Metabolic risk, stones, cancer status, age, ethnicity/race.","validation":"Separate benign chronic cholecystitis, metaplasia/dysplasia, and carcinoma categories.","literature":[{"short_citation":"Figueiredo et al., 2017","citation":"Figueiredo JC, et al. Sex and ethnic/racial-specific risk factors for gallbladder disease. 2017","pmcid":"PMC5723039","evidence_status":"source metadata incomplete"},{"short_citation":"Stinton & Shaffer, 2012","citation":"Stinton LM, Shaffer EA. Epidemiology of Gallbladder Disease: Cholelithiasis and Cancer. Gut and Liver. 2012","pmcid":"PMC3343155","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"}],"key_takeaways":["Best review target: chronic cholecystitis severity, cholesterolosis, fibrosis, metaplasia/dysplasia, and gallstone proxies.","Main shortcut risk: gallstone disease and cholecystectomy indication.","Direct intrinsic sex morphology evidence is weak; this is likely a clinical-context signal."],"references":[{"n":1,"raw":"Stinton LM, Shaffer EA. Epidemiology of Gallbladder Disease: Cholelithiasis and Cancer. Gut and Liver. 2012. PMCID: PMC3343155.","citation":"Stinton LM, Shaffer EA. Epidemiology of Gallbladder Disease: Cholelithiasis and Cancer. Gut and Liver. 2012","year":"2012","pmcid":"PMC3343155"},{"n":2,"raw":"Figueiredo JC, et al. Sex and ethnic/racial-specific risk factors for gallbladder disease. 2017. PMCID: PMC5723039.","citation":"Figueiredo JC, et al. Sex and ethnic/racial-specific risk factors for gallbladder disease. 2017","year":"2017","pmcid":"PMC5723039"}],"filename":"gall_bladder__sex.yaml"},{"combo":"gastric_stomach__age","organ_slug":"gastric_stomach","organ":"Gastric / Stomach","demographic":"age","demographic_label":"Age","summary":"Age signal in gastric histology has strong literature support but remains highly confounded by Helicobacter pylori, autoimmune gastritis, medication exposure, and cumulative injury. Older patients are enriched for chronic gastritis, atrophic gastritis, intestinal metaplasia, dysplasia, and gastric cancer workups. Residual age signal after S3 control may still persist in background mucosa through gland loss, metaplasia, chronic inflammation, endocrine-cell change, and stromal remodeling.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Older patients may be enriched for chronic atrophic gastritis and intestinal metaplasia.","mechanism":"Decades of H. pylori, autoimmune, chemical, or cumulative injury increase gland loss and metaplastic change.","features":"Oxyntic/antral atrophy, intestinal metaplasia, chronic gastritis, gland loss.","confounders":"H. pylori, autoimmune gastritis, biopsy site, PPI use, ethnicity/geography.","validation":"Match atrophy/metaplasia diagnosis and gastric site; retest residual age signal in non-atrophic mucosa.","literature":[{"short_citation":"Vara-Luiz et al., 2025","citation":"Vara-Luiz F, et al. Clinical, Endoscopic and Histologic Differences in Gastric Mucosa Between Younger and Older Adults: An Observational Study on the Aging Stomach. Medical Sciences. 2025","pmid":"41133506","pmcid":"PMC12550935","doi":"10.3390/medsci13040224","url":"https://pubmed.ncbi.nlm.nih.gov/41133506/","evidence_status":"needs claim-level validation"},{"short_citation":"Sonnenberg & Genta, 2015","citation":"Sonnenberg A, Genta RM. Changes in the Gastric Mucosa With Aging. Clinical Gastroenterology and Hepatology. 2015","pmid":"25724703","doi":"10.1016/j.cgh.2015.02.020","url":"https://pubmed.ncbi.nlm.nih.gov/25724703/","evidence_status":"needs claim-level validation"},{"short_citation":"Fedeli et al., 1990","citation":"Fedeli G, Cannizzaro O, Gambassi G, et al. Increased prevalence of intestinal metaplasia in the gastric mucosa of the elderly: clinical implications. Annali Italiani di Medicina Interna. 1990","pmid":"2206765","url":"https://pubmed.ncbi.nlm.nih.gov/2206765/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Older patients may be enriched for dysplasia and gastric adenocarcinoma workups.","mechanism":"Atrophy-metaplasia-dysplasia-carcinoma pathways and surveillance increase neoplastic samples in older patients.","features":"Dysplasia, adenocarcinoma, intestinal vs diffuse type, ulceration, desmoplasia, resection tissue.","confounders":"Cancer status, dysplasia grade, H. pylori, treatment, procedure type.","validation":"Exclude dysplasia/cancer or match neoplastic category before reviewing intrinsic age morphology.","literature":[{"short_citation":"Raza & Bhatt, 2023","citation":"Raza M, Bhatt H. Atrophic Gastritis. StatPearls. Updated 2023","url":"https://www.ncbi.nlm.nih.gov/books/NBK563275/","evidence_status":"source metadata incomplete"},{"short_citation":"Sonnenberg & Genta, 2015","citation":"Sonnenberg A, Genta RM. Changes in the Gastric Mucosa With Aging. Clinical Gastroenterology and Hepatology. 2015","pmid":"25724703","doi":"10.1016/j.cgh.2015.02.020","url":"https://pubmed.ncbi.nlm.nih.gov/25724703/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Biopsy site and endoscopy indication can encode age.","mechanism":"Older patients may undergo more extensive mapping biopsies, ulcer follow-up, or metaplasia surveillance.","features":"Antrum vs corpus, incisura, mapping fragments, polyp/ulcer biopsies, normal vs abnormal mucosa.","confounders":"Site, indication, number of fragments, institution, endoscopist pattern.","validation":"Add site/procedure matching and analyze antrum-only/corpus-only subsets.","literature":[{"short_citation":"Vara-Luiz et al., 2025","citation":"Vara-Luiz F, et al. Clinical, Endoscopic and Histologic Differences in Gastric Mucosa Between Younger and Older Adults: An Observational Study on the Aging Stomach. Medical Sciences. 2025","pmid":"41133506","pmcid":"PMC12550935","doi":"10.3390/medsci13040224","url":"https://pubmed.ncbi.nlm.nih.gov/41133506/","evidence_status":"needs claim-level validation"},{"short_citation":"Raza & Bhatt, 2023","citation":"Raza M, Bhatt H. Atrophic Gastritis. StatPearls. Updated 2023","url":"https://www.ncbi.nlm.nih.gov/books/NBK563275/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"H. pylori and post-eradication status may mediate age signal.","mechanism":"Age correlates with cumulative infection duration and incomplete reversal of atrophy/metaplasia.","features":"Active chronic gastritis, lymphoid aggregates, organisms, atrophy, intestinal metaplasia.","confounders":"H. pylori status, eradication history, geography, PPI/antibiotic exposure.","validation":"Stratify by H. pylori status and atrophy/metaplasia stage.","literature":[{"short_citation":"Sonnenberg & Genta, 2015","citation":"Sonnenberg A, Genta RM. Changes in the Gastric Mucosa With Aging. Clinical Gastroenterology and Hepatology. 2015","pmid":"25724703","doi":"10.1016/j.cgh.2015.02.020","url":"https://pubmed.ncbi.nlm.nih.gov/25724703/","evidence_status":"needs claim-level validation"},{"short_citation":"Kodama et al., 2023","citation":"Kodama M, et al. Comparison of the improvement in gastric mucosal tissue after Helicobacter pylori eradication between young and elderly people. 2023","pmid":"36720666","url":"https://pubmed.ncbi.nlm.nih.gov/36720666/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Gastric gland loss and mucosal atrophy encode age.","mechanism":"Chronic injury and aging-associated mucosal change reduce gland density and alter mucosal architecture.","features":"Gland density, mucosal thickness, oxyntic gland loss, pseudopyloric/metaplastic glands.","confounders":"H. pylori, autoimmune gastritis, site, biopsy orientation.","validation":"Quantify gland density within site-matched non-neoplastic biopsies.","literature":[{"short_citation":"Vara-Luiz et al., 2025","citation":"Vara-Luiz F, et al. Clinical, Endoscopic and Histologic Differences in Gastric Mucosa Between Younger and Older Adults: An Observational Study on the Aging Stomach. Medical Sciences. 2025","pmid":"41133506","pmcid":"PMC12550935","doi":"10.3390/medsci13040224","url":"https://pubmed.ncbi.nlm.nih.gov/41133506/","evidence_status":"needs claim-level validation"},{"short_citation":"Sonnenberg & Genta, 2015","citation":"Sonnenberg A, Genta RM. Changes in the Gastric Mucosa With Aging. Clinical Gastroenterology and Hepatology. 2015","pmid":"25724703","doi":"10.1016/j.cgh.2015.02.020","url":"https://pubmed.ncbi.nlm.nih.gov/25724703/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Intestinal metaplasia creates a strong visible age-associated feature.","mechanism":"Metaplastic goblet/intestinal epithelium accumulates with chronic injury and older age.","features":"Goblet cells, intestinal-type epithelium, complete/incomplete metaplasia, Paneth cells.","confounders":"H. pylori, autoimmune gastritis, site, ethnicity/geography.","validation":"Separate metaplasia-positive and metaplasia-negative cohorts; quantify residual signal.","literature":[{"short_citation":"Fedeli et al., 1990","citation":"Fedeli G, Cannizzaro O, Gambassi G, et al. Increased prevalence of intestinal metaplasia in the gastric mucosa of the elderly: clinical implications. Annali Italiani di Medicina Interna. 1990","pmid":"2206765","url":"https://pubmed.ncbi.nlm.nih.gov/2206765/","evidence_status":"needs claim-level validation"},{"short_citation":"Raza & Bhatt, 2023","citation":"Raza M, Bhatt H. Atrophic Gastritis. StatPearls. Updated 2023","url":"https://www.ncbi.nlm.nih.gov/books/NBK563275/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Chronic inflammatory background may encode cumulative gastric injury.","mechanism":"Persistent gastritis produces lymphoplasmacytic inflammation, lymphoid aggregates, and reactive epithelial change.","features":"Chronic inflammation, activity, lymphoid aggregates, foveolar hyperplasia, erosions.","confounders":"H. pylori, NSAIDs, bile reflux, autoimmune gastritis, PPI use.","validation":"Score Sydney-system features and test age prediction after adjusting for inflammation.","literature":[{"short_citation":"Sonnenberg & Genta, 2015","citation":"Sonnenberg A, Genta RM. Changes in the Gastric Mucosa With Aging. Clinical Gastroenterology and Hepatology. 2015","pmid":"25724703","doi":"10.1016/j.cgh.2015.02.020","url":"https://pubmed.ncbi.nlm.nih.gov/25724703/","evidence_status":"needs claim-level validation"},{"short_citation":"Vara-Luiz et al., 2025","citation":"Vara-Luiz F, et al. Clinical, Endoscopic and Histologic Differences in Gastric Mucosa Between Younger and Older Adults: An Observational Study on the Aging Stomach. Medical Sciences. 2025","pmid":"41133506","pmcid":"PMC12550935","doi":"10.3390/medsci13040224","url":"https://pubmed.ncbi.nlm.nih.gov/41133506/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Stromal/smooth-muscle proliferative atrophy may contribute to residual morphology.","mechanism":"Atrophic lesions can include smooth-muscle fiber proliferation and remodeling of lamina propria.","features":"Smooth muscle fibers in lamina propria, fibrosis, gland distortion, stromal texture.","confounders":"Atrophy stage, site, chronic injury, orientation.","validation":"Review atrophy-stage patterns in age-matched and H. pylori-matched samples.","literature":[{"short_citation":"Zhang et al., 2023","citation":"Zhang J, et al. The occurrence, progression and development of four types of gastric mucosal atrophic lesions and their histopathological characteristics. 2023","pmcid":"PMC10361864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10361864/","evidence_status":"source metadata incomplete"},{"short_citation":"Li et al., 2024","citation":"Li Y, et al. Histopathological staging of atrophic lesions of gastric mucosa. 2024","pmcid":"PMC10979135","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10979135/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M5","section":"histomorphology","status":"active","hypothesis":"Endocrine-cell and autoimmune-gastritis context may create an older-age shortcut.","mechanism":"Autoimmune/oxyntic atrophy and hypergastrinemia can alter endocrine-cell patterns and corpus mucosa.","features":"Corpus atrophy, ECL-cell change if stained, intestinal/pseudopyloric metaplasia, neuroendocrine lesions.","confounders":"Autoimmune gastritis, corpus site, pernicious anemia, stains unavailable on H&E.","validation":"Identify corpus-predominant atrophy and autoimmune gastritis diagnoses; review separately.","literature":[{"short_citation":"Raza & Bhatt, 2023","citation":"Raza M, Bhatt H. Atrophic Gastritis. StatPearls. Updated 2023","url":"https://www.ncbi.nlm.nih.gov/books/NBK563275/","evidence_status":"source metadata incomplete"},{"short_citation":"Sonnenberg & Genta, 2015","citation":"Sonnenberg A, Genta RM. Changes in the Gastric Mucosa With Aging. Clinical Gastroenterology and Hepatology. 2015","pmid":"25724703","doi":"10.1016/j.cgh.2015.02.020","url":"https://pubmed.ncbi.nlm.nih.gov/25724703/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["Gastric age is one of the better-supported non-ENT top-20 hypotheses.","The strongest features are atrophy, intestinal metaplasia, chronic gastritis, and site/procedure context.","The most important validation is H. pylori/autoimmune status, biopsy site, and neoplasia exclusion or matching."],"references":[{"n":1,"raw":"Vara-Luiz F, et al. Clinical, Endoscopic and Histologic Differences in Gastric Mucosa Between Younger and Older Adults: An Observational Study on the Aging Stomach. Medical Sciences. 2025. PMID: 41133506; PMCID: PMC12550935; DOI: 10.3390/medsci13040224. https://pubmed.ncbi.nlm.nih.gov/41133506/","citation":"Vara-Luiz F, et al. Clinical, Endoscopic and Histologic Differences in Gastric Mucosa Between Younger and Older Adults: An Observational Study on the Aging Stomach. Medical Sciences. 2025","year":"2025","pmid":"41133506","pmcid":"PMC12550935","doi":"10.3390/medsci13040224","url":"https://pubmed.ncbi.nlm.nih.gov/41133506/"},{"n":2,"raw":"Sonnenberg A, Genta RM. Changes in the Gastric Mucosa With Aging. Clinical Gastroenterology and Hepatology. 2015. PMID: 25724703; DOI: 10.1016/j.cgh.2015.02.020. https://pubmed.ncbi.nlm.nih.gov/25724703/","citation":"Sonnenberg A, Genta RM. Changes in the Gastric Mucosa With Aging. Clinical Gastroenterology and Hepatology. 2015","year":"2015","pmid":"25724703","doi":"10.1016/j.cgh.2015.02.020","url":"https://pubmed.ncbi.nlm.nih.gov/25724703/"},{"n":3,"raw":"Fedeli G, Cannizzaro O, Gambassi G, et al. Increased prevalence of intestinal metaplasia in the gastric mucosa of the elderly: clinical implications. Annali Italiani di Medicina Interna. 1990. PMID: 2206765. https://pubmed.ncbi.nlm.nih.gov/2206765/","citation":"Fedeli G, Cannizzaro O, Gambassi G, et al. Increased prevalence of intestinal metaplasia in the gastric mucosa of the elderly: clinical implications. Annali Italiani di Medicina Interna. 1990","year":"1990","pmid":"2206765","url":"https://pubmed.ncbi.nlm.nih.gov/2206765/"},{"n":4,"raw":"Raza M, Bhatt H. Atrophic Gastritis. StatPearls. Updated 2023. https://www.ncbi.nlm.nih.gov/books/NBK563275/","citation":"Raza M, Bhatt H. Atrophic Gastritis. StatPearls. Updated 2023","year":"2023","url":"https://www.ncbi.nlm.nih.gov/books/NBK563275/"},{"n":5,"raw":"Kodama M, et al. Comparison of the improvement in gastric mucosal tissue after Helicobacter pylori eradication between young and elderly people. 2023. PMID: 36720666. https://pubmed.ncbi.nlm.nih.gov/36720666/","citation":"Kodama M, et al. Comparison of the improvement in gastric mucosal tissue after Helicobacter pylori eradication between young and elderly people. 2023","year":"2023","pmid":"36720666","url":"https://pubmed.ncbi.nlm.nih.gov/36720666/"},{"n":6,"raw":"Zhang J, et al. The occurrence, progression and development of four types of gastric mucosal atrophic lesions and their histopathological characteristics. 2023. PMCID: PMC10361864. https://pmc.ncbi.nlm.nih.gov/articles/PMC10361864/","citation":"Zhang J, et al. The occurrence, progression and development of four types of gastric mucosal atrophic lesions and their histopathological characteristics. 2023","year":"2023","pmcid":"PMC10361864","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10361864/"},{"n":7,"raw":"Li Y, et al. Histopathological staging of atrophic lesions of gastric mucosa. 2024. PMCID: PMC10979135. https://pmc.ncbi.nlm.nih.gov/articles/PMC10979135/","citation":"Li Y, et al. Histopathological staging of atrophic lesions of gastric mucosa. 2024","year":"2024","pmcid":"PMC10979135","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10979135/"}],"filename":"gastric_stomach__age.yaml"},{"combo":"gastric_stomach__race_self_reported_ancestry","organ_slug":"gastric_stomach","organ":"Gastric (Stomach)","demographic":"race_self_reported_ancestry","demographic_label":"Race / Self-Reported Ancestry","summary":"Gastric race/self-reported ancestry signal is a high residual candidate. The best-supported carrier is gastric intestinal metaplasia (GIM), H. pylori-associated gastritis, atrophy, and chronic inflammation in multiethnic biopsy cohorts. Interpret this as ancestry/geography/exposure/access and infection-context signal, not intrinsic race biology.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"GIM prevalence differs across racial/ethnic groups in a multiethnic US biopsy cohort.","mechanism":"Race/ethnicity may proxy H. pylori exposure, geography, diet, access, and biopsy indication.","features":"Intestinal metaplasia, atrophy, chronic gastritis, acute activity.","confounders":"H. pylori, age, sex, site, biopsy indication, institution.","validation":"Match H. pylori/gastritis/metaplasia status; test residual signal in normal/non-metaplastic biopsies.","literature":[{"short_citation":"Nguyen et al., 2021","citation":"Nguyen TH, Tan MC, Liu Y, et al. Prevalence of Gastric Intestinal Metaplasia in a Multiethnic US Veterans Population. Clinical Gastroenterology and Hepatology. 2021","pmid":"32184184","pmcid":"PMC7890574","doi":"10.1016/j.cgh.2020.03.015","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"H. pylori and gastritis mediate part of race/ethnicity-associated gastric pathology.","mechanism":"Infection and chronic inflammation create H&E-visible patterns that can drive demographic prediction.","features":"H. pylori organisms if visible, active chronic gastritis, lymphoid follicles, atrophy.","confounders":"H. pylori testing, gastric site, medication, age, SES/geography.","validation":"Include H. pylori and gastritis severity in matched analysis.","literature":[{"short_citation":"Nguyen et al., 2021","citation":"Nguyen TH, Tan MC, Liu Y, et al. Prevalence of Gastric Intestinal Metaplasia in a Multiethnic US Veterans Population. Clinical Gastroenterology and Hepatology. 2021","pmid":"32184184","pmcid":"PMC7890574","doi":"10.1016/j.cgh.2020.03.015","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Gastric cancer risk and surveillance pathways may differ by ethnicity and geography.","mechanism":"Race/ethnicity can proxy migration, endemic exposure, family history, and endoscopic surveillance thresholds.","features":"Dysplasia, adenocarcinoma, intestinal metaplasia mapping biopsies, antrum/corpus site.","confounders":"Cancer status, site, H. pylori, family history, geography, indication.","validation":"Exclude dysplasia/cancer and separately analyze metaplasia-surveillance biopsies.","literature":[{"short_citation":"Nguyen et al., 2021","citation":"Nguyen TH, Tan MC, Liu Y, et al. Prevalence of Gastric Intestinal Metaplasia in a Multiethnic US Veterans Population. Clinical Gastroenterology and Hepatology. 2021","pmid":"32184184","pmcid":"PMC7890574","doi":"10.1016/j.cgh.2020.03.015","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Biopsy-site distribution may encode race-associated clinical workflow.","mechanism":"Antrum, corpus, incisura, and mapping protocols differ across gastritis/metaplasia workups.","features":"Antral vs corpus mucosa, oxyntic atrophy, incisura fragments, mapping biopsies.","confounders":"Site label, endoscopy indication, institution, H. pylori, age.","validation":"Require site-matched analysis before interpreting residual gastric race signal.","literature":[{"short_citation":"Nguyen et al., 2021","citation":"Nguyen TH, Tan MC, Liu Y, et al. Prevalence of Gastric Intestinal Metaplasia in a Multiethnic US Veterans Population. Clinical Gastroenterology and Hepatology. 2021","pmid":"32184184","pmcid":"PMC7890574","doi":"10.1016/j.cgh.2020.03.015","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Race-associated signal may localize to metaplasia/atrophy rather than normal mucosa.","mechanism":"GIM and atrophic gastritis have strong H&E morphology and may be imbalanced by group.","features":"Goblet cells, intestinalized glands, gland loss, endocrine cell change, inflammation.","confounders":"Diagnosis, H. pylori, biopsy site, age.","validation":"Exclude GIM/atrophy and retest; separately review metaplastic regions.","literature":[{"short_citation":"Nguyen et al., 2021","citation":"Nguyen TH, Tan MC, Liu Y, et al. Prevalence of Gastric Intestinal Metaplasia in a Multiethnic US Veterans Population. Clinical Gastroenterology and Hepatology. 2021","pmid":"32184184","pmcid":"PMC7890574","doi":"10.1016/j.cgh.2020.03.015","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Direct intrinsic gastric mucosa differences by race are not established.","mechanism":"Observed signal likely reflects infection, exposure, care, and diagnosis context.","features":"Background mucosa after excluding gastritis/metaplasia.","confounders":"Site, stain/scanner, institution, geography.","validation":"Interpret residual signal cautiously unless it persists after infection/site/diagnosis matching.","literature":[{"short_citation":"Nguyen et al., 2021","citation":"Nguyen TH, Tan MC, Liu Y, et al. Prevalence of Gastric Intestinal Metaplasia in a Multiethnic US Veterans Population. Clinical Gastroenterology and Hepatology. 2021","pmid":"32184184","pmcid":"PMC7890574","doi":"10.1016/j.cgh.2020.03.015","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Active chronic gastritis may be an indirect H&E carrier.","mechanism":"H. pylori and related injury produce neutrophilic activity, lymphoplasmacytic inflammation, and lymphoid follicles.","features":"Activity, chronic inflammation, lymphoid aggregates, organisms, foveolar reaction.","confounders":"H. pylori status, site, treatment, PPI/antibiotics, age.","validation":"Score gastritis severity and compare race signal in H. pylori-negative/non-inflamed biopsies.","literature":[{"short_citation":"Nguyen et al., 2021","citation":"Nguyen TH, Tan MC, Liu Y, et al. Prevalence of Gastric Intestinal Metaplasia in a Multiethnic US Veterans Population. Clinical Gastroenterology and Hepatology. 2021","pmid":"32184184","pmcid":"PMC7890574","doi":"10.1016/j.cgh.2020.03.015","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Metaplasia-stage and atrophy-stage morphology should be separated from ancestry claims.","mechanism":"Atrophy and GIM are disease/injury states with visible glandular remodeling.","features":"Gland loss, goblet cells, pseudopyloric change, endocrine-cell context.","confounders":"Site, H. pylori, autoimmune gastritis, age, geography.","validation":"Promote only disease-context hypotheses unless residual persists in normal site-matched mucosa.","literature":[{"short_citation":"Nguyen et al., 2021","citation":"Nguyen TH, Tan MC, Liu Y, et al. Prevalence of Gastric Intestinal Metaplasia in a Multiethnic US Veterans Population. Clinical Gastroenterology and Hepatology. 2021","pmid":"32184184","pmcid":"PMC7890574","doi":"10.1016/j.cgh.2020.03.015","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["Best review target: intestinal metaplasia, chronic active gastritis, atrophy, and lymphoid follicles.","Main shortcut risk: H. pylori, gastric site, biopsy indication, and metaplasia status.","Frame as exposure/infection/context signal rather than intrinsic race biology."],"references":[{"n":1,"raw":"Nguyen TH, Tan MC, Liu Y, et al. Prevalence of Gastric Intestinal Metaplasia in a Multiethnic US Veterans Population. Clinical Gastroenterology and Hepatology. 2021. PMID: 32184184. PMCID: PMC7890574. DOI: 10.1016/j.cgh.2020.03.015.","citation":"Nguyen TH, Tan MC, Liu Y, et al. Prevalence of Gastric Intestinal Metaplasia in a Multiethnic US Veterans Population. Clinical Gastroenterology and Hepatology. 2021","year":"2021","pmid":"32184184","pmcid":"PMC7890574","doi":"10.1016/j.cgh.2020.03.015"}],"filename":"gastric_stomach__race_self_reported_ancestry.yaml"},{"combo":"gastric_stomach__sex","organ_slug":"gastric_stomach","organ":"Gastric (Stomach)","demographic":"sex","demographic_label":"Sex","summary":"Gastric sex signal is a stable residual candidate with high S3_CC performance. The likely mechanisms are mixed: sex differences in gastric cancer subtype/age distribution, diffuse/signet-ring patterns in some cohorts, and possible hormonal or inflammatory context. Direct H&E sex morphology outside subtype and diagnosis remains uncertain.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Gastric cancer subtype and age distribution may differ by sex.","mechanism":"Sex-skewed cancer subtype and presentation can create diagnosis/subtype shortcuts.","features":"Adenocarcinoma subtype, intestinal vs diffuse, signet-ring cells, grade, stage.","confounders":"Cancer status, Lauren subtype, grade, stage, age, procedure.","validation":"Match cancer subtype and stage; compare residual sex signal in non-neoplastic gastric biopsies.","literature":[{"short_citation":"Li et al., 2016","citation":"Li C, Kim S, Lai JF, et al. The characteristics and prognostic value of signet ring cell histology in gastric cancer: A retrospective cohort study of 2199 consecutive patients. Medicine. 2016","pmid":"27399088","doi":"10.1097/MD.0000000000004052","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Diffuse/signet-ring gastric cancer context may contribute to female-enriched morphology in some cohorts.","mechanism":"Signet-ring/diffuse histology is a distinct H&E-visible subtype that can drive sex prediction if imbalanced.","features":"Signet-ring cells, mucin, diffuse infiltration, desmoplastic stroma.","confounders":"Subtype, age, tumor location, stage, treatment.","validation":"Exclude or match signet-ring/diffuse carcinoma and retest.","literature":[{"short_citation":"Li et al., 2016","citation":"Li C, Kim S, Lai JF, et al. The characteristics and prognostic value of signet ring cell histology in gastric cancer: A retrospective cohort study of 2199 consecutive patients. Medicine. 2016","pmid":"27399088","doi":"10.1097/MD.0000000000004052","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Non-neoplastic gastritis/metaplasia prevalence may differ by sex and age mix.","mechanism":"Sex differences in H. pylori exposure, autoimmune gastritis, or cancer surveillance could alter background biopsy diagnoses.","features":"Chronic gastritis, atrophy, intestinal metaplasia, lymphoid follicles, H. pylori organisms.","confounders":"Age, H. pylori, site, race/ethnicity, autoimmune gastritis, indication.","validation":"Test sex signal in non-neoplastic biopsies matched for site, gastritis, and metaplasia.","literature":[{"short_citation":"Li et al., 2016","citation":"Li C, Kim S, Lai JF, et al. The characteristics and prognostic value of signet ring cell histology in gastric cancer: A retrospective cohort study of 2199 consecutive patients. Medicine. 2016","pmid":"27399088","doi":"10.1097/MD.0000000000004052","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Procedure and tumor-location mix may encode sex.","mechanism":"Gastrectomy vs biopsy, antrum/corpus/cardia site, and tumor location can be sex-skewed in cancer cohorts.","features":"Biopsy vs resection, tumor site, adjacent mucosa, ulcer, treatment effect.","confounders":"Procedure type, anatomic site, stage, treatment, institution.","validation":"Match procedure and gastric site before interpreting residual sex signal.","literature":[{"short_citation":"Li et al., 2016","citation":"Li C, Kim S, Lai JF, et al. The characteristics and prognostic value of signet ring cell histology in gastric cancer: A retrospective cohort study of 2199 consecutive patients. Medicine. 2016","pmid":"27399088","doi":"10.1097/MD.0000000000004052","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Residual sex signal may be subtype-mediated rather than intrinsic gastric mucosa biology.","mechanism":"H&E-visible diffuse/signet-ring and intestinal-type patterns could persist if S3 clusters do not fully balance subtype.","features":"Tumor cell cohesion, mucin, signet-ring morphology, intestinal glands.","confounders":"Lauren subtype, tumor site, stage, age.","validation":"Audit S3 clusters for detailed histologic subtype balance.","literature":[{"short_citation":"Li et al., 2016","citation":"Li C, Kim S, Lai JF, et al. The characteristics and prognostic value of signet ring cell histology in gastric cancer: A retrospective cohort study of 2199 consecutive patients. Medicine. 2016","pmid":"27399088","doi":"10.1097/MD.0000000000004052","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Non-neoplastic gastric mucosa sex morphology is uncertain.","mechanism":"Hormonal or inflammatory differences are plausible but not directly supported by strong H&E sex-specific gastric mucosa evidence.","features":"Chronic gastritis, atrophy, intestinal metaplasia, lymphoid follicles.","confounders":"H. pylori, age, race/ethnicity, medication, biopsy indication.","validation":"Test sex signal in non-neoplastic gastric biopsies matched for gastritis/metaplasia/H. pylori.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Signet-ring and mucin-rich patterns are a visible tumor-mediated carrier.","mechanism":"Diffuse/signet-ring carcinoma has highly distinctive single-cell/mucin morphology.","features":"Signet-ring cells, mucin vacuoles, discohesive infiltration, stromal desmoplasia.","confounders":"Histologic subtype, site, stage, treatment, age.","validation":"Compare model signal within subtype-matched tumor cohorts.","literature":[{"short_citation":"Li et al., 2016","citation":"Li C, Kim S, Lai JF, et al. The characteristics and prognostic value of signet ring cell histology in gastric cancer: A retrospective cohort study of 2199 consecutive patients. Medicine. 2016","pmid":"27399088","doi":"10.1097/MD.0000000000004052","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Inflammation/metaplasia should be treated as confounded until sex-specific mucosal evidence is added.","mechanism":"If signal localizes to background mucosa, it may reflect H. pylori/metaplasia imbalance rather than intrinsic sex biology.","features":"Activity, chronic inflammation, gland atrophy, intestinal metaplasia.","confounders":"H. pylori, site, age, autoimmune gastritis, indication.","validation":"Require reviewer-added DOI-backed references before promoting to testable biological claim.","literature":[],"evidence_status":"source metadata incomplete"}],"key_takeaways":["Best review target: diffuse/signet-ring carcinoma and subtype balance.","Main shortcut risk: cancer subtype, age, stage, and procedure.","If residual signal remains in non-neoplastic matched biopsies, further literature search is needed."],"references":[{"n":1,"raw":"Li C, Kim S, Lai JF, et al. The characteristics and prognostic value of signet ring cell histology in gastric cancer: A retrospective cohort study of 2199 consecutive patients. Medicine. 2016. PMID: 27399088. DOI: 10.1097/MD.0000000000004052.","citation":"Li C, Kim S, Lai JF, et al. The characteristics and prognostic value of signet ring cell histology in gastric cancer: A retrospective cohort study of 2199 consecutive patients. Medicine. 2016","year":"2016","pmid":"27399088","doi":"10.1097/MD.0000000000004052"}],"filename":"gastric_stomach__sex.yaml"},{"combo":"lymph_node__sex","organ_slug":"lymph_node","organ":"Lymph Node","demographic":"sex","demographic_label":"Sex","summary":"Lymph node sex signal ranks highly because residual S3_CC performance is strong. Current literature support is weaker than the performance signal: sex-related lymph-node morphology is most plausibly mediated by immune dimorphism, autoimmune/inflammatory context, lymphoma/metastasis case mix, and possibly stromal/immune-cell composition. This page should be treated as a high-priority literature-search target.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Sex differences in immune disease, infection, and malignancy workup may alter lymph-node sampling mix.","mechanism":"Female-biased autoimmune disease and sex-skewed cancer types can change reactive, metastatic, and lymphoma contexts.","features":"Reactive follicular hyperplasia, granulomas, metastatic carcinoma type, lymphoma subtype, excisional vs core biopsy.","confounders":"Diagnosis, primary tumor type, lymphoma subtype, sampling procedure, age.","validation":"Stratify lymph nodes by reactive, lymphoma, and metastatic categories; match primary tumor type.","literature":[{"short_citation":"Klein & Flanagan, 2016","citation":"Klein SL, Flanagan KL. Sex differences in immune responses. Nature Reviews Immunology. 2016","pmid":"26819318","doi":"10.1038/nri.2016.90","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Sex-skewed cancer staging can create metastatic lymph-node shortcuts.","mechanism":"Breast, gynecologic, prostate, head/neck, lung, and GI primaries have different sex distributions and nodal sampling pathways.","features":"Metastatic carcinoma morphology, nodal dissection context, extranodal extension, treatment effect.","confounders":"Primary cancer site, staging procedure, nodal basin, treatment status.","validation":"Exclude metastatic nodes or match primary tumor site before interpreting residual sex signal.","literature":[{"short_citation":"Klein & Flanagan, 2016","citation":"Klein SL, Flanagan KL. Sex differences in immune responses. Nature Reviews Immunology. 2016","pmid":"26819318","doi":"10.1038/nri.2016.90","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Reactive lymphadenopathy indications may differ by sex.","mechanism":"Autoimmune, infectious, vaccine/reactive, and inflammatory indications can be sex-skewed and alter benign node morphology.","features":"Follicular hyperplasia, paracortical expansion, plasma cells, sinus histiocytosis, granulomas.","confounders":"Reactive diagnosis, autoimmune disease, infection, vaccine/treatment history, age.","validation":"Compare sex signal within reactive-only nodes and after excluding lymphoma/metastasis.","literature":[{"short_citation":"Klein & Flanagan, 2016","citation":"Klein SL, Flanagan KL. Sex differences in immune responses. Nature Reviews Immunology. 2016","pmid":"26819318","doi":"10.1038/nri.2016.90","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Procedure type and nodal basin may create hidden sex shortcuts.","mechanism":"Sentinel nodes, neck dissections, pelvic nodes, and excisional biopsies can be tied to sex-skewed primary diseases.","features":"Sentinel node protocol, nodal station, fat content, metastatic deposit type, biopsy vs dissection.","confounders":"Nodal basin, primary tumor site, procedure type, institution, treatment.","validation":"Audit nodal basin and procedure distributions in S3 clusters.","literature":[{"short_citation":"Klein & Flanagan, 2016","citation":"Klein SL, Flanagan KL. Sex differences in immune responses. Nature Reviews Immunology. 2016","pmid":"26819318","doi":"10.1038/nri.2016.90","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Sex-based immune dimorphism may alter reactive lymphoid architecture.","mechanism":"Sex hormones and X-linked immune regulation can influence adaptive/innate immune responses.","features":"Follicle density, germinal centers, paracortical expansion, plasma cells, sinus histiocytosis.","confounders":"Age, infection, autoimmune disease, vaccine/reactive context, lymphoma.","validation":"Quantify reactive patterns in benign/reactive nodes after diagnosis and age matching.","literature":[{"short_citation":"Klein & Flanagan, 2016","citation":"Klein SL, Flanagan KL. Sex differences in immune responses. Nature Reviews Immunology. 2016","pmid":"26819318","doi":"10.1038/nri.2016.90","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Residual sex signal may reflect unmeasured diagnosis or primary-site context rather than intrinsic nodal morphology.","mechanism":"S3 diagnosis matching may not fully balance nodal basin, primary tumor, or inflammatory indication.","features":"Nodal basin, metastatic histology, tissue adequacy, fibrosis/necrosis.","confounders":"Primary site, nodal station, institution, procedure type.","validation":"Audit S3 clusters for primary tumor site and nodal basin balance.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Germinal-center and paracortical architecture may be indirect immune carriers.","mechanism":"Sex-dimorphic immune responses may alter adaptive immune activation patterns in reactive nodes.","features":"Germinal center size, follicle density, mantle zones, paracortical expansion.","confounders":"Reactive etiology, age, infection, autoimmune disease, lymphoma exclusion.","validation":"Quantify architecture only in benign/reactive nodes matched by indication.","literature":[{"short_citation":"Klein & Flanagan, 2016","citation":"Klein SL, Flanagan KL. Sex differences in immune responses. Nature Reviews Immunology. 2016","pmid":"26819318","doi":"10.1038/nri.2016.90","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Sinus and macrophage-rich patterns may reflect metastatic or inflammatory context.","mechanism":"Primary tumor type and immune activation can alter sinus histiocytosis, fibrosis, and necrosis.","features":"Sinus histiocytosis, macrophages, necrosis, fibrosis, extranodal extension.","confounders":"Metastatic status, primary site, treatment, nodal basin.","validation":"Separate metastatic, lymphoma, and reactive nodes before calling intrinsic sex morphology.","literature":[{"short_citation":"Klein & Flanagan, 2016","citation":"Klein SL, Flanagan KL. Sex differences in immune responses. Nature Reviews Immunology. 2016","pmid":"26819318","doi":"10.1038/nri.2016.90","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["Best immediate validation: separate reactive, lymphoma, and metastatic lymph nodes.","Best literature task: replace E42/preprint support with peer-reviewed human lymph-node sex-difference pathology or immune-architecture sources.","Interpret high residual performance cautiously until primary tumor site and nodal basin are checked."],"references":[{"n":1,"raw":"Klein SL, Flanagan KL. Sex differences in immune responses. Nature Reviews Immunology. 2016. PMID: 26819318. DOI: 10.1038/nri.2016.90.","citation":"Klein SL, Flanagan KL. Sex differences in immune responses. Nature Reviews Immunology. 2016","year":"2016","pmid":"26819318","doi":"10.1038/nri.2016.90"},{"n":2,"raw":"Lymph node sex differences / aging source from current notes. BioRxiv preprint. E42 in master evidence registry. Needs peer-reviewed replacement before manuscript use.","citation":"Lymph node sex differences / aging source from current notes. BioRxiv preprint. E42 in master evidence registry. Needs peer-reviewed replacement before manuscript use","year":""}],"filename":"lymph_node__sex.yaml"},{"combo":"mouth_oral_cavity__age","organ_slug":"mouth_oral_cavity","organ":"Mouth / Oral Cavity","demographic":"age","demographic_label":"Age Group","summary":"Age signal in oral cavity histology is likely mixed. Clinical-context signal may come from age-skewed enrichment for oral squamous cell carcinoma, dysplasia, chronic mucosal injury, denture/prosthetic trauma, salivary dysfunction, and procedure differences. Morphology signal may also persist in benign/background tissue through epithelial atrophy, rete ridge flattening, stromal collagen remodeling, vascular change, chronic inflammation, and minor salivary gland atrophy.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Older patients are enriched for oral squamous cell carcinoma.","mechanism":"Oral cancer incidence and cancer-directed resections increase with age, creating diagnosis and specimen-type shortcuts.","features":"SCC vs benign mucosa, invasive carcinoma, keratinization, necrosis, perineural invasion, resection vs biopsy.","confounders":"Diagnosis, tumor stage, oral subsite, specimen type, treatment status.","validation":"Match benign/malignant status and SCC stage/subsite; test residual age signal within SCC-only and benign-only subsets.","literature":[{"short_citation":"Lenoci et al., 2024","citation":"Lenoci D, Moresco E, Cavalieri S, et al. Oral cancer in young adults: incidence, risk factors, prognosis, and molecular biomarkers. Frontiers in Oncology. 2024","doi":"10.3389/fonc.2024.1452909","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11484398/","evidence_status":"needs claim-level validation"},{"short_citation":"Majchrzak et al., 2014","citation":"Majchrzak E, Szybiak B, Wegner A, et al. Oral cavity and oropharyngeal squamous cell carcinoma in young adults: a review of the literature. 2014","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3908841/","evidence_status":"source metadata incomplete"},{"short_citation":"Brizuela & Winters, 2023","citation":"Brizuela M, Winters R. Histology, Oral Mucosa. StatPearls. Updated 2023","pmid":"34033326","url":"https://www.ncbi.nlm.nih.gov/books/NBK572115/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Older patients are enriched for epithelial dysplasia and field-change biopsies.","mechanism":"Cumulative tobacco/alcohol, dental irritation, and chronic mucosal injury can increase dysplasia workups in older patients.","features":"Dysplasia grade, keratinizing atypia, hyperkeratosis, lichenoid/interface inflammation, margin status.","confounders":"Dysplasia grade, risk exposure, subsite, biopsy indication.","validation":"Match dysplasia grade and oral subsite; compare age prediction within dysplasia-only cases.","literature":[{"short_citation":"Porto et al., 2024","citation":"Porto UN, Laureano NK, dos Santos NS, et al. Leukoplakia and erythroplakia in youngers versus older individuals: a clinicopathological retrospective study. 2024","doi":"10.4317/medoral.26659","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11365051/","evidence_status":"needs claim-level validation"},{"short_citation":"Alnuaimi et al., 2020","citation":"Alnuaimi AD, Wiesenfeld D, O'Brien-Simpson NM, Reynolds EC, McCullough MJ. Long-term follow-up of oral epithelial dysplasia: A hospital based cross-sectional study. 2020","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7770253/","evidence_status":"source metadata incomplete"},{"short_citation":"Wetzel & Wollenberg, 2020","citation":"Wetzel SL, Wollenberg J. Oral Potentially Malignant Disorders. Dental Clinics of North America. 2020","pmid":"31735231","doi":"10.1016/j.cden.2019.08.004","url":"https://pubmed.ncbi.nlm.nih.gov/31735231/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Older patients may have more prosthetic/dental trauma and chronic ulcer/injury specimens.","mechanism":"Dentures, dental disease, medications, and comorbidity can shift biopsy mix toward chronic reactive lesions.","features":"Ulceration, granulation tissue, fibrosis/scar, pseudoepitheliomatous hyperplasia, chronic inflammation.","confounders":"Diagnosis, denture/prosthetic history, subsite, biopsy indication.","validation":"Use report diagnosis and subsite to identify traumatic/reactive lesions; test whether age signal attenuates when excluded.","literature":[{"short_citation":"Fitzpatrick et al., 2019","citation":"Fitzpatrick SG, Cohen DM, Clark AN. Ulcerated Lesions of the Oral Mucosa: Clinical and Histologic Review. Head and Neck Pathology. 2019","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6405793/","evidence_status":"source metadata incomplete"},{"short_citation":"Jovanovic et al., 2023","citation":"Jovanovic M, Jankovic S, Okicic N, et al. Factors affecting the healing of decubital lesions in patients wearing newly made dentures. 2023","pmid":"38303831","doi":"10.1016/j.jds.2023.03.019","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10829545/","evidence_status":"needs claim-level validation"},{"short_citation":"Qiu et al., 2026","citation":"Qiu C, Jie W, et al. Ageing of the Oral Mucosa: Mechanisms and Consequences. International Dental Journal. 2026","doi":"10.1016/j.identj.2026.109482","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13068552/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Older patients may be enriched for salivary dysfunction-related pathology.","mechanism":"Aging and medications can alter oral moisture and minor salivary gland context, affecting sampling and inflammation.","features":"Minor salivary gland tissue, acinar atrophy, duct dilation, chronic sialadenitis, fibrosis, fatty replacement.","confounders":"Salivary gland inclusion, Sjogren/autoimmune disease, medication history, biopsy site.","validation":"Stratify by presence of minor salivary gland tissue and salivary diagnoses.","literature":[{"short_citation":"Qiu et al., 2026","citation":"Qiu C, Jie W, et al. Ageing of the Oral Mucosa: Mechanisms and Consequences. International Dental Journal. 2026","doi":"10.1016/j.identj.2026.109482","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13068552/","evidence_status":"needs claim-level validation"},{"short_citation":"Brizuela & Winters, 2023","citation":"Brizuela M, Winters R. Histology, Oral Mucosa. StatPearls. Updated 2023","pmid":"34033326","url":"https://www.ncbi.nlm.nih.gov/books/NBK572115/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Oral epithelial thickness decreases with age.","mechanism":"Oral mucosal aging may cause epithelial thinning/atrophy and reduced proliferative capacity.","features":"Epithelial thickness, atrophy, basal/parabasal cellularity, keratin layer.","confounders":"Subsite, inflammation, dysplasia, ulceration, fixation/orientation.","validation":"Quantify epithelial thickness in benign non-ulcerated mucosa matched by subsite.","literature":[{"short_citation":"Shklar, 1966","citation":"Shklar G. The effects of aging upon oral mucosa. Journal of Investigative Dermatology. 1966","pmid":"5916125","doi":"10.1038/jid.1966.107","url":"https://pubmed.ncbi.nlm.nih.gov/5916125/","evidence_status":"needs claim-level validation"},{"short_citation":"Qiu et al., 2026","citation":"Qiu C, Jie W, et al. Ageing of the Oral Mucosa: Mechanisms and Consequences. International Dental Journal. 2026","doi":"10.1016/j.identj.2026.109482","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13068552/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Rete ridge architecture becomes flatter or less complex with age.","mechanism":"Aging may reduce epithelial-connective tissue interface complexity.","features":"Rete ridge height/density, epithelial-connective interface, papillary architecture.","confounders":"Subsite, frictional keratosis, dysplasia, section orientation.","validation":"Morphometric rete ridge analysis in benign mucosa after subsite matching.","literature":[{"short_citation":"Shklar, 1966","citation":"Shklar G. The effects of aging upon oral mucosa. Journal of Investigative Dermatology. 1966","pmid":"5916125","doi":"10.1038/jid.1966.107","url":"https://pubmed.ncbi.nlm.nih.gov/5916125/","evidence_status":"needs claim-level validation"},{"short_citation":"Qiu et al., 2026","citation":"Qiu C, Jie W, et al. Ageing of the Oral Mucosa: Mechanisms and Consequences. International Dental Journal. 2026","doi":"10.1016/j.identj.2026.109482","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13068552/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Lamina propria collagen and extracellular matrix remodel with age.","mechanism":"Aging fibroblasts and ECM turnover may alter collagen density, organization, and stromal stiffness.","features":"Collagen density, hyalinization, stromal cellularity, fibrosis, elastotic-like change.","confounders":"Scar, chronic inflammation, tumor desmoplasia, subsite.","validation":"Restrict to benign background lamina propria; quantify stromal texture/collagen density.","literature":[{"short_citation":"Gomi et al., 2020","citation":"Gomi T, Imamura T, et al. Comprehensive histological investigation of age-related changes in dermal extracellular matrix and muscle fibers in the upper lip vermilion. International Journal of Cosmetic Science. 2020","doi":"10.1111/ics.12622","url":"https://pubmed.ncbi.nlm.nih.gov/32712160/","evidence_status":"needs claim-level validation"},{"short_citation":"Qiu et al., 2026","citation":"Qiu C, Jie W, et al. Ageing of the Oral Mucosa: Mechanisms and Consequences. International Dental Journal. 2026","doi":"10.1016/j.identj.2026.109482","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13068552/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Oral mucosal immune background changes with age.","mechanism":"Immunosenescence/inflammaging may alter chronic inflammatory infiltrates.","features":"Lymphoplasmacytic infiltrate, lichenoid/interface inflammation, lymphoid aggregates.","confounders":"Diagnosis, infection, autoimmune disease, ulceration, treatment.","validation":"Test within benign/reactive diagnoses and adjust for inflammation-related diagnostic labels.","literature":[{"short_citation":"Qiu et al., 2026","citation":"Qiu C, Jie W, et al. Ageing of the Oral Mucosa: Mechanisms and Consequences. International Dental Journal. 2026","doi":"10.1016/j.identj.2026.109482","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13068552/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M5","section":"histomorphology","status":"active","hypothesis":"Minor salivary gland atrophy may encode age when glands are present.","mechanism":"Aging and xerostomia-related processes may reduce acini and increase fibrosis/fat.","features":"Acinar atrophy, duct dilation, periductal fibrosis, fatty replacement, chronic sialadenitis.","confounders":"Salivary gland sampling, Sjogren disease, radiation, medication history.","validation":"Analyze only slides containing minor salivary gland tissue; match salivary diagnosis.","literature":[{"short_citation":"Qiu et al., 2026","citation":"Qiu C, Jie W, et al. Ageing of the Oral Mucosa: Mechanisms and Consequences. International Dental Journal. 2026","doi":"10.1016/j.identj.2026.109482","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13068552/","evidence_status":"needs claim-level validation"},{"short_citation":"Brizuela & Winters, 2023","citation":"Brizuela M, Winters R. Histology, Oral Mucosa. StatPearls. Updated 2023","pmid":"34033326","url":"https://www.ncbi.nlm.nih.gov/books/NBK572115/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The most likely clinical-context signal is age-skewed diagnosis and specimen mix, especially SCC, dysplasia, chronic injury, and salivary dysfunction.","The most plausible morphology signal is benign mucosal aging: epithelial atrophy, flatter rete ridges, stromal collagen remodeling, and minor salivary gland atrophy.","The most important validation is diagnosis-, subsite-, and specimen-type matching, followed by benign/background mucosa analysis."],"references":[{"n":1,"raw":"Qiu C, Jie W, et al. Ageing of the Oral Mucosa: Mechanisms and Consequences. International Dental Journal. 2026. DOI: 10.1016/j.identj.2026.109482. https://pmc.ncbi.nlm.nih.gov/articles/PMC13068552/","citation":"Qiu C, Jie W, et al. Ageing of the Oral Mucosa: Mechanisms and Consequences. International Dental Journal. 2026","year":"2026","doi":"10.1016/j.identj.2026.109482","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13068552/"},{"n":2,"raw":"Gomi T, Imamura T, et al. Comprehensive histological investigation of age-related changes in dermal extracellular matrix and muscle fibers in the upper lip vermilion. International Journal of Cosmetic Science. 2020. DOI: 10.1111/ics.12622. https://pubmed.ncbi.nlm.nih.gov/32712160/","citation":"Gomi T, Imamura T, et al. Comprehensive histological investigation of age-related changes in dermal extracellular matrix and muscle fibers in the upper lip vermilion. International Journal of Cosmetic Science. 2020","year":"2020","doi":"10.1111/ics.12622","url":"https://pubmed.ncbi.nlm.nih.gov/32712160/"},{"n":3,"raw":"Shklar G. The effects of aging upon oral mucosa. Journal of Investigative Dermatology. 1966. PMID: 5916125. DOI: 10.1038/jid.1966.107. https://pubmed.ncbi.nlm.nih.gov/5916125/","citation":"Shklar G. The effects of aging upon oral mucosa. Journal of Investigative Dermatology. 1966","year":"1966","pmid":"5916125","doi":"10.1038/jid.1966.107","url":"https://pubmed.ncbi.nlm.nih.gov/5916125/"},{"n":4,"raw":"Brizuela M, Winters R. Histology, Oral Mucosa. StatPearls. Updated 2023. PMID: 34033326. https://www.ncbi.nlm.nih.gov/books/NBK572115/","citation":"Brizuela M, Winters R. Histology, Oral Mucosa. StatPearls. Updated 2023","year":"2023","pmid":"34033326","url":"https://www.ncbi.nlm.nih.gov/books/NBK572115/"},{"n":5,"raw":"Lenoci D, Moresco E, Cavalieri S, et al. Oral cancer in young adults: incidence, risk factors, prognosis, and molecular biomarkers. Frontiers in Oncology. 2024. DOI: 10.3389/fonc.2024.1452909. https://pmc.ncbi.nlm.nih.gov/articles/PMC11484398/","citation":"Lenoci D, Moresco E, Cavalieri S, et al. Oral cancer in young adults: incidence, risk factors, prognosis, and molecular biomarkers. Frontiers in Oncology. 2024","year":"2024","doi":"10.3389/fonc.2024.1452909","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11484398/"},{"n":6,"raw":"Majchrzak E, Szybiak B, Wegner A, et al. Oral cavity and oropharyngeal squamous cell carcinoma in young adults: a review of the literature. 2014. https://pmc.ncbi.nlm.nih.gov/articles/PMC3908841/","citation":"Majchrzak E, Szybiak B, Wegner A, et al. Oral cavity and oropharyngeal squamous cell carcinoma in young adults: a review of the literature. 2014","year":"2014","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3908841/"},{"n":7,"raw":"Alnuaimi AD, Wiesenfeld D, O'Brien-Simpson NM, Reynolds EC, McCullough MJ. Long-term follow-up of oral epithelial dysplasia: A hospital based cross-sectional study. 2020. https://pmc.ncbi.nlm.nih.gov/articles/PMC7770253/","citation":"Alnuaimi AD, Wiesenfeld D, O'Brien-Simpson NM, Reynolds EC, McCullough MJ. Long-term follow-up of oral epithelial dysplasia: A hospital based cross-sectional study. 2020","year":"2020","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7770253/"},{"n":8,"raw":"Porto UN, Laureano NK, dos Santos NS, et al. Leukoplakia and erythroplakia in youngers versus older individuals: a clinicopathological retrospective study. 2024. DOI: 10.4317/medoral.26659. https://pmc.ncbi.nlm.nih.gov/articles/PMC11365051/","citation":"Porto UN, Laureano NK, dos Santos NS, et al. Leukoplakia and erythroplakia in youngers versus older individuals: a clinicopathological retrospective study. 2024","year":"2024","doi":"10.4317/medoral.26659","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11365051/"},{"n":9,"raw":"Wetzel SL, Wollenberg J. Oral Potentially Malignant Disorders. Dental Clinics of North America. 2020. PMID: 31735231. DOI: 10.1016/j.cden.2019.08.004. https://pubmed.ncbi.nlm.nih.gov/31735231/","citation":"Wetzel SL, Wollenberg J. Oral Potentially Malignant Disorders. Dental Clinics of North America. 2020","year":"2020","pmid":"31735231","doi":"10.1016/j.cden.2019.08.004","url":"https://pubmed.ncbi.nlm.nih.gov/31735231/"},{"n":10,"raw":"Fitzpatrick SG, Cohen DM, Clark AN. Ulcerated Lesions of the Oral Mucosa: Clinical and Histologic Review. Head and Neck Pathology. 2019. https://pmc.ncbi.nlm.nih.gov/articles/PMC6405793/","citation":"Fitzpatrick SG, Cohen DM, Clark AN. Ulcerated Lesions of the Oral Mucosa: Clinical and Histologic Review. Head and Neck Pathology. 2019","year":"2019","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6405793/"},{"n":11,"raw":"Jovanovic M, Jankovic S, Okicic N, et al. Factors affecting the healing of decubital lesions in patients wearing newly made dentures. 2023. DOI: 10.1016/j.jds.2023.03.019. PMID: 38303831. https://pmc.ncbi.nlm.nih.gov/articles/PMC10829545/","citation":"Jovanovic M, Jankovic S, Okicic N, et al. Factors affecting the healing of decubital lesions in patients wearing newly made dentures. 2023","year":"2023","pmid":"38303831","doi":"10.1016/j.jds.2023.03.019","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10829545/"}],"filename":"mouth_oral_cavity__age.yaml"},{"combo":"mouth_oral_cavity__race_self_reported_ancestry","organ_slug":"mouth_oral_cavity","organ":"Mouth / Oral Cavity","demographic":"race_self_reported_ancestry","demographic_label":"Race / Self-Reported Ancestry","summary":"Race/self-reported ancestry signal in oral cavity histology should be treated as a clinical-context, access, exposure, and workflow signal rather than intrinsic tissue biology. The strongest candidate carriers are oral cavity squamous cell carcinoma stage/severity, treatment access and timing, insurance/social vulnerability, tumor subsite and HPV/p16 mixing, oral potentially malignant disorder or dysplasia case mix, and dental-care-associated inflammatory or reactive lesions. Direct race-specific benign oral mucosal morphology is not established; any residual signal after strict matching should be interpreted as residual context or unmeasured confounding until externally replicated.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Race/self-reported ancestry signal may reflect oral cavity cancer stage at presentation.","mechanism":"Structural access, diagnostic delay, insurance, and referral patterns can shift tumor stage/severity across groups.","features":"Tumor size/depth proxies, invasion, necrosis, perineural invasion, lymphovascular invasion, bone/muscle invasion, margin specimens.","confounders":"Stage, tumor size/depth, subsite, grade, treatment status, institution, insurance/SES.","validation":"Match or adjust for stage/depth/subsite/grade; test residual race signal within stage-matched SCC and untreated primary-tumor subsets.","literature":[{"short_citation":"Yu et al., 2019","citation":"Yu AJ, Choi JS, Swanson MS, et al. Association of Race/Ethnicity, Stage, and Survival in Oral Cavity Squamous Cell Carcinoma: A SEER Study. OTO Open. 2019","pmid":"31840132","doi":"10.1177/2473974X19891126","url":"https://journals.sagepub.com/doi/10.1177/2473974X19891126","evidence_status":"needs claim-level validation"},{"short_citation":"Tortolero et al., 2026","citation":"Tortolero G, Wang K, Elting LS, et al. The Intersection of Social Vulnerability and Oral Cavity Cancer: Racial Disparities and Stage at Diagnosis. JAMA Otolaryngology-Head & Neck Surgery. 2025/2026","doi":"10.1001/jamaoto.2025.3916","url":"https://digitalcommons.library.tmc.edu/uthsph_docs/1293/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Treatment initiation and care access may create workflow/specimen shortcuts.","mechanism":"Race/ethnicity, rurality, social vulnerability, and insurance can influence time to diagnosis or treatment, changing biopsy versus resection composition and treated versus untreated tissue.","features":"Biopsy vs resection, margin specimens, treatment effect, scar/radiation change, necrosis, advanced resection complexity.","confounders":"Institution, insurance, rurality, treatment status, procedure type, calendar year.","validation":"Stratify by procedure type and pre-treatment status; include institution and insurance/social vulnerability controls where available.","literature":[{"short_citation":"Semprini et al., 2023","citation":"Semprini J, et al. Community socioeconomic status and rural/racial disparities in treatment initiation delays for head and neck cancers. Cancer Epidemiology, Biomarkers & Prevention. 2023","pmid":"36791786","doi":"10.1158/1055-9965.EPI-22-0997","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10038787/","evidence_status":"needs claim-level validation"},{"short_citation":"Yu et al., 2019","citation":"Yu AJ, Choi JS, Swanson MS, et al. Association of Race/Ethnicity, Stage, and Survival in Oral Cavity Squamous Cell Carcinoma: A SEER Study. OTO Open. 2019","pmid":"31840132","doi":"10.1177/2473974X19891126","url":"https://journals.sagepub.com/doi/10.1177/2473974X19891126","evidence_status":"needs claim-level validation"},{"short_citation":"Kaur et al., 2020","citation":"Kaur R, Dufour LR, Giurgescu C, et al. Disparities in Access to Oral Health Care. Annual Review of Public Health. 2020","pmid":"31900100","doi":"10.1146/annurev-publhealth-040119-094318","url":"https://pubmed.ncbi.nlm.nih.gov/31900100/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"HPV-related versus HPV-negative head-and-neck disease context may differ by racial/ethnic group if oral and oropharyngeal tissue are mixed.","mechanism":"HPV prevalence differs across racial-ethnic subgroups in head-and-neck cancer cohorts and HPV-related SCC has distinctive morphology, especially in oropharyngeal/tonsillar tissue that may be misclassified or co-sampled.","features":"Basaloid/non-keratinizing SCC, p16/HPV status, lymphoid-rich background, keratinizing SCC, oropharyngeal/tonsillar subsite labels.","confounders":"True oral cavity versus oropharynx, HPV/p16 status, smoking, tumor subtype, subsite.","validation":"Restrict to true oral cavity; separately analyze or exclude oropharyngeal/tonsillar cases; match HPV/p16 where available.","literature":[{"short_citation":"Ragin et al., 2016","citation":"Ragin C, Langevin SM, Marzouk M, Grandis J, Taioli E. Prevalence of HPV infection in racial-ethnic subgroups of head and neck cancer patients. Carcinogenesis. 2016","pmid":"27206972","doi":"10.1093/carcin/bgw055","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7191086/","evidence_status":"needs claim-level validation"},{"short_citation":"Chernock et al., 2011","citation":"Chernock RD, et al. Human papillomavirus-related squamous cell carcinoma of the oropharynx: a comparative study in whites and African Americans. Archives of Otolaryngology-Head & Neck Surgery. 2011","pmid":"21690474","doi":"10.1001/archoto.2011.91","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3863596/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Oral potentially malignant disorder and dysplasia case mix may differ through exposure and access pathways.","mechanism":"Tobacco/alcohol, dental care access, screening, and referral patterns can alter the sampled mix of leukoplakia, erythroplakia, dysplasia, and field-change biopsies.","features":"Dysplasia grade, hyperkeratosis, keratinizing atypia, erythroplakia/leukoplakia context, margin status, candidiasis or ulceration.","confounders":"Smoking/alcohol, subsite, clinical lesion type, dysplasia grade, biopsy indication, institution.","validation":"Match dysplasia grade and lesion type; compare within OPMD-only and dysplasia-only subsets; test whether excluding high-grade dysplasia attenuates race signal.","literature":[{"short_citation":"Pires et al., 2020","citation":"Pires FR, Barreto ME, Nunes JG, Carneiro NS, Azevedo AB, dos Santos TCRB. Oral potentially malignant disorders: clinical-pathological study of 684 cases diagnosed in a Brazilian population. Medicina Oral, Patologia Oral y Cirugia Bucal. 2020","pmid":"32683380","doi":"10.4317/medoral.23883","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7530402/","evidence_status":"needs claim-level validation"},{"short_citation":"Wetzel & Wollenberg, 2020","citation":"Wetzel SL, Wollenberg J. Oral Potentially Malignant Disorders. Dental Clinics of North America. 2020","pmid":"31735231","doi":"10.1016/j.cden.2019.08.004","url":"https://pubmed.ncbi.nlm.nih.gov/31735231/","evidence_status":"needs claim-level validation"},{"short_citation":"Kaur et al., 2020","citation":"Kaur R, Dufour LR, Giurgescu C, et al. Disparities in Access to Oral Health Care. Annual Review of Public Health. 2020","pmid":"31900100","doi":"10.1146/annurev-publhealth-040119-094318","url":"https://pubmed.ncbi.nlm.nih.gov/31900100/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C5","section":"clinical_context","status":"active","hypothesis":"Dental-care access and oral-health disparities may shift inflammatory, infectious, or reactive biopsy composition.","mechanism":"Differential access to dental care can affect untreated dental disease, chronic trauma, candidiasis, ulceration, and reactive lesions that enter oral pathology workflows.","features":"Ulceration, granulation tissue, chronic inflammation, candidiasis, pseudoepitheliomatous hyperplasia, reactive fibrous hyperplasia, traumatic lesions.","confounders":"Dental care access, insurance, denture/prosthetic use, oral hygiene, diagnosis, subsite, institution.","validation":"Identify reactive/infectious/inflammatory diagnoses; test whether removing ulcer/infection/reactive cases attenuates race signal.","literature":[{"short_citation":"Kaur et al., 2020","citation":"Kaur R, Dufour LR, Giurgescu C, et al. Disparities in Access to Oral Health Care. Annual Review of Public Health. 2020","pmid":"31900100","doi":"10.1146/annurev-publhealth-040119-094318","url":"https://pubmed.ncbi.nlm.nih.gov/31900100/","evidence_status":"needs claim-level validation"},{"short_citation":"Fitzpatrick et al., 2019","citation":"Fitzpatrick SG, Cohen DM, Clark AN. Ulcerated Lesions of the Oral Mucosa: Clinical and Histologic Review. Head and Neck Pathology. 2019","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6405793/","evidence_status":"source metadata incomplete"},{"short_citation":"Semprini et al., 2023","citation":"Semprini J, et al. Community socioeconomic status and rural/racial disparities in treatment initiation delays for head and neck cancers. Cancer Epidemiology, Biomarkers & Prevention. 2023","pmid":"36791786","doi":"10.1158/1055-9965.EPI-22-0997","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10038787/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Apparent morphology signal may be advanced SCC morphology rather than race biology.","mechanism":"Stage, depth, invasion, and treatment pathway can produce H&E-visible differences correlated with access and presentation.","features":"Invasion depth, necrosis, perineural invasion, bone/muscle invasion, stromal desmoplasia, margin/treatment tissue.","confounders":"Stage, depth, grade, treatment status, procedure type, subsite.","validation":"Tumor-only analysis with matched stage/depth/grade; compare attention maps before and after excluding necrosis, margins, and treatment-effect regions.","literature":[{"short_citation":"Yu et al., 2019","citation":"Yu AJ, Choi JS, Swanson MS, et al. Association of Race/Ethnicity, Stage, and Survival in Oral Cavity Squamous Cell Carcinoma: A SEER Study. OTO Open. 2019","pmid":"31840132","doi":"10.1177/2473974X19891126","url":"https://journals.sagepub.com/doi/10.1177/2473974X19891126","evidence_status":"needs claim-level validation"},{"short_citation":"Tortolero et al., 2026","citation":"Tortolero G, Wang K, Elting LS, et al. The Intersection of Social Vulnerability and Oral Cavity Cancer: Racial Disparities and Stage at Diagnosis. JAMA Otolaryngology-Head & Neck Surgery. 2025/2026","doi":"10.1001/jamaoto.2025.3916","url":"https://digitalcommons.library.tmc.edu/uthsph_docs/1293/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Tumor subtype, HPV/p16 status, and keratinization may mediate apparent race signal.","mechanism":"HPV-related, keratinizing, non-keratinizing, and high-stage tumors have different H&E appearances and can vary by subsite and population context.","features":"Keratin pearls, basaloid/non-keratinizing pattern, lymphoid background, tumor immune infiltrate, necrosis, p16/HPV annotation.","confounders":"HPV/p16 status, true subsite, smoking, grade, stage.","validation":"Match SCC subtype and HPV/p16; run oral-cavity-only and oropharynx-excluded sensitivity analyses.","literature":[{"short_citation":"Ragin et al., 2016","citation":"Ragin C, Langevin SM, Marzouk M, Grandis J, Taioli E. Prevalence of HPV infection in racial-ethnic subgroups of head and neck cancer patients. Carcinogenesis. 2016","pmid":"27206972","doi":"10.1093/carcin/bgw055","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7191086/","evidence_status":"needs claim-level validation"},{"short_citation":"Chernock et al., 2011","citation":"Chernock RD, et al. Human papillomavirus-related squamous cell carcinoma of the oropharynx: a comparative study in whites and African Americans. Archives of Otolaryngology-Head & Neck Surgery. 2011","pmid":"21690474","doi":"10.1001/archoto.2011.91","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3863596/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Dysplasia and OPMD morphology may carry mediated race/access signal.","mechanism":"Different lesion types and dysplasia severity can change epithelial architecture and keratinization, but this reflects diagnostic mix and exposures rather than intrinsic ancestry morphology.","features":"Dysplasia grade, basal atypia, keratin layer, rete architecture, erythroplakia/leukoplakia context, lichenoid/interface inflammation.","confounders":"Lesion type, dysplasia grade, smoking/alcohol, subsite, clinical indication.","validation":"Restrict to OPMD/dysplasia cases; match grade and lesion type; quantify whether race signal persists in same-grade dysplasia.","literature":[{"short_citation":"Pires et al., 2020","citation":"Pires FR, Barreto ME, Nunes JG, Carneiro NS, Azevedo AB, dos Santos TCRB. Oral potentially malignant disorders: clinical-pathological study of 684 cases diagnosed in a Brazilian population. Medicina Oral, Patologia Oral y Cirugia Bucal. 2020","pmid":"32683380","doi":"10.4317/medoral.23883","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7530402/","evidence_status":"needs claim-level validation"},{"short_citation":"Wetzel & Wollenberg, 2020","citation":"Wetzel SL, Wollenberg J. Oral Potentially Malignant Disorders. Dental Clinics of North America. 2020","pmid":"31735231","doi":"10.1016/j.cden.2019.08.004","url":"https://pubmed.ncbi.nlm.nih.gov/31735231/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Chronic inflammation, infection, and reactive injury may mediate residual signal.","mechanism":"Dental-care access, untreated lesions, trauma, candidiasis, and ulceration can alter inflammatory and repair morphology.","features":"Lymphoplasmacytic inflammation, neutrophils, fungal organisms, ulceration, granulation tissue, fibrosis/scar, pseudoepitheliomatous hyperplasia.","confounders":"Diagnosis, infection, ulceration, denture/prosthetic context, subsite, institution.","validation":"Annotate inflammatory/infectious/reactive diagnoses; compare within benign non-ulcerated mucosa after excluding infection and trauma.","literature":[{"short_citation":"Kaur et al., 2020","citation":"Kaur R, Dufour LR, Giurgescu C, et al. Disparities in Access to Oral Health Care. Annual Review of Public Health. 2020","pmid":"31900100","doi":"10.1146/annurev-publhealth-040119-094318","url":"https://pubmed.ncbi.nlm.nih.gov/31900100/","evidence_status":"needs claim-level validation"},{"short_citation":"Fitzpatrick et al., 2019","citation":"Fitzpatrick SG, Cohen DM, Clark AN. Ulcerated Lesions of the Oral Mucosa: Clinical and Histologic Review. Head and Neck Pathology. 2019","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6405793/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"M5","section":"histomorphology","status":"active","hypothesis":"Direct intrinsic oral mucosal differences by race/self-reported ancestry are not well supported.","mechanism":"Race is not a direct biological tissue variable; residual H&E signal may reflect unmeasured context, exposure, access, or workflow.","features":"Benign epithelium, lamina propria, minor salivary glands after strict diagnosis/subsite/institution matching.","confounders":"Subsite, diagnosis, institution, scanner, stage, treatment, oral-health access, exposure.","validation":"Test only in benign/background tissue with strict matching and external replication; avoid biological interpretation unless independent ancestry/genetic or mechanistic evidence exists.","literature":[{"short_citation":"Yu et al., 2019","citation":"Yu AJ, Choi JS, Swanson MS, et al. Association of Race/Ethnicity, Stage, and Survival in Oral Cavity Squamous Cell Carcinoma: A SEER Study. OTO Open. 2019","pmid":"31840132","doi":"10.1177/2473974X19891126","url":"https://journals.sagepub.com/doi/10.1177/2473974X19891126","evidence_status":"needs claim-level validation"},{"short_citation":"Kaur et al., 2020","citation":"Kaur R, Dufour LR, Giurgescu C, et al. Disparities in Access to Oral Health Care. Annual Review of Public Health. 2020","pmid":"31900100","doi":"10.1146/annurev-publhealth-040119-094318","url":"https://pubmed.ncbi.nlm.nih.gov/31900100/","evidence_status":"needs claim-level validation"},{"short_citation":"Semprini et al., 2023","citation":"Semprini J, et al. Community socioeconomic status and rural/racial disparities in treatment initiation delays for head and neck cancers. Cancer Epidemiology, Biomarkers & Prevention. 2023","pmid":"36791786","doi":"10.1158/1055-9965.EPI-22-0997","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10038787/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The strongest race/self-reported ancestry hypotheses are mediated signals: stage/severity, access, treatment timing, insurance/social vulnerability, subsite/HPV mixing, dysplasia/OPMD mix, and dental-care-related inflammatory/reactive diagnoses.","H&E-visible morphology is plausible, but mainly as a downstream carrier of tumor stage/subtype, dysplasia severity, ulceration/infection, and workflow rather than intrinsic oral mucosa differences.","The most important validation is matching by diagnosis, stage/depth/grade, subsite, HPV/p16, specimen type, treatment status, institution, and available insurance/SES or oral-health access proxies."],"references":[{"n":1,"raw":"Yu AJ, Choi JS, Swanson MS, et al. Association of Race/Ethnicity, Stage, and Survival in Oral Cavity Squamous Cell Carcinoma: A SEER Study. OTO Open. 2019. PMID: 31840132. DOI: 10.1177/2473974X19891126. https://journals.sagepub.com/doi/10.1177/2473974X19891126","citation":"Yu AJ, Choi JS, Swanson MS, et al. Association of Race/Ethnicity, Stage, and Survival in Oral Cavity Squamous Cell Carcinoma: A SEER Study. OTO Open. 2019","year":"2019","pmid":"31840132","doi":"10.1177/2473974X19891126","url":"https://journals.sagepub.com/doi/10.1177/2473974X19891126"},{"n":2,"raw":"Tortolero G, Wang K, Elting LS, et al. The Intersection of Social Vulnerability and Oral Cavity Cancer: Racial Disparities and Stage at Diagnosis. JAMA Otolaryngology-Head & Neck Surgery. 2025/2026. DOI: 10.1001/jamaoto.2025.3916. https://digitalcommons.library.tmc.edu/uthsph_docs/1293/","citation":"Tortolero G, Wang K, Elting LS, et al. The Intersection of Social Vulnerability and Oral Cavity Cancer: Racial Disparities and Stage at Diagnosis. JAMA Otolaryngology-Head & Neck Surgery. 2025/2026","year":"2025","doi":"10.1001/jamaoto.2025.3916","url":"https://digitalcommons.library.tmc.edu/uthsph_docs/1293/"},{"n":3,"raw":"Semprini J, et al. Community socioeconomic status and rural/racial disparities in treatment initiation delays for head and neck cancers. Cancer Epidemiology, Biomarkers & Prevention. 2023. PMID: 36791786. DOI: 10.1158/1055-9965.EPI-22-0997. https://pmc.ncbi.nlm.nih.gov/articles/PMC10038787/","citation":"Semprini J, et al. Community socioeconomic status and rural/racial disparities in treatment initiation delays for head and neck cancers. Cancer Epidemiology, Biomarkers & Prevention. 2023","year":"2023","pmid":"36791786","doi":"10.1158/1055-9965.EPI-22-0997","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10038787/"},{"n":4,"raw":"Kaur R, Dufour LR, Giurgescu C, et al. Disparities in Access to Oral Health Care. Annual Review of Public Health. 2020. PMID: 31900100. DOI: 10.1146/annurev-publhealth-040119-094318. https://pubmed.ncbi.nlm.nih.gov/31900100/","citation":"Kaur R, Dufour LR, Giurgescu C, et al. Disparities in Access to Oral Health Care. Annual Review of Public Health. 2020","year":"2020","pmid":"31900100","doi":"10.1146/annurev-publhealth-040119-094318","url":"https://pubmed.ncbi.nlm.nih.gov/31900100/"},{"n":5,"raw":"Ragin C, Langevin SM, Marzouk M, Grandis J, Taioli E. Prevalence of HPV infection in racial-ethnic subgroups of head and neck cancer patients. Carcinogenesis. 2016. PMID: 27206972. DOI: 10.1093/carcin/bgw055. https://pmc.ncbi.nlm.nih.gov/articles/PMC7191086/","citation":"Ragin C, Langevin SM, Marzouk M, Grandis J, Taioli E. Prevalence of HPV infection in racial-ethnic subgroups of head and neck cancer patients. Carcinogenesis. 2016","year":"2016","pmid":"27206972","doi":"10.1093/carcin/bgw055","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7191086/"},{"n":6,"raw":"Chernock RD, et al. Human papillomavirus-related squamous cell carcinoma of the oropharynx: a comparative study in whites and African Americans. Archives of Otolaryngology-Head & Neck Surgery. 2011. PMID: 21690474. DOI: 10.1001/archoto.2011.91. https://pmc.ncbi.nlm.nih.gov/articles/PMC3863596/","citation":"Chernock RD, et al. Human papillomavirus-related squamous cell carcinoma of the oropharynx: a comparative study in whites and African Americans. Archives of Otolaryngology-Head & Neck Surgery. 2011","year":"2011","pmid":"21690474","doi":"10.1001/archoto.2011.91","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3863596/"},{"n":7,"raw":"Pires FR, Barreto ME, Nunes JG, Carneiro NS, Azevedo AB, dos Santos TCRB. Oral potentially malignant disorders: clinical-pathological study of 684 cases diagnosed in a Brazilian population. Medicina Oral, Patologia Oral y Cirugia Bucal. 2020. PMID: 32683380. DOI: 10.4317/medoral.23883. https://pmc.ncbi.nlm.nih.gov/articles/PMC7530402/","citation":"Pires FR, Barreto ME, Nunes JG, Carneiro NS, Azevedo AB, dos Santos TCRB. Oral potentially malignant disorders: clinical-pathological study of 684 cases diagnosed in a Brazilian population. Medicina Oral, Patologia Oral y Cirugia Bucal. 2020","year":"2020","pmid":"32683380","doi":"10.4317/medoral.23883","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7530402/"},{"n":8,"raw":"Wetzel SL, Wollenberg J. Oral Potentially Malignant Disorders. Dental Clinics of North America. 2020. PMID: 31735231. DOI: 10.1016/j.cden.2019.08.004. https://pubmed.ncbi.nlm.nih.gov/31735231/","citation":"Wetzel SL, Wollenberg J. Oral Potentially Malignant Disorders. Dental Clinics of North America. 2020","year":"2020","pmid":"31735231","doi":"10.1016/j.cden.2019.08.004","url":"https://pubmed.ncbi.nlm.nih.gov/31735231/"},{"n":9,"raw":"Fitzpatrick SG, Cohen DM, Clark AN. Ulcerated Lesions of the Oral Mucosa: Clinical and Histologic Review. Head and Neck Pathology. 2019. https://pmc.ncbi.nlm.nih.gov/articles/PMC6405793/","citation":"Fitzpatrick SG, Cohen DM, Clark AN. Ulcerated Lesions of the Oral Mucosa: Clinical and Histologic Review. Head and Neck Pathology. 2019","year":"2019","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6405793/"}],"filename":"mouth_oral_cavity__race_self_reported_ancestry.yaml"},{"combo":"mouth_oral_cavity__sex","organ_slug":"mouth_oral_cavity","organ":"Mouth / Oral Cavity","demographic":"sex","demographic_label":"Sex","summary":"Sex signal in oral cavity histology is expected to be dominated by clinical-context and exposure differences, with some direct disease-pattern support for specific oral mucosal diagnoses. Male patients are generally overrepresented in head-and-neck/oral cavity cancer cohorts and may differ in tobacco, alcohol, betel nut, subsite, stage, and procedure context. Female patients may be enriched for oral lichen planus/lichenoid inflammatory disease and Sjogren-related minor salivary gland biopsy context. Direct normal oral epithelial sex morphology is weakly established; any residual benign-mucosa signal should be interpreted cautiously.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Male patients are enriched for oral/head-and-neck cancer specimens.","mechanism":"Higher male head-and-neck cancer prevalence can create diagnosis and specimen-type shortcuts in mixed oral pathology cohorts.","features":"SCC vs benign mucosa, dysplasia, invasive carcinoma, resection vs biopsy, necrosis, perineural invasion.","confounders":"Diagnosis, stage, subsite, procedure type, age, institution.","validation":"Match benign/malignant status and SCC stage/subsite; test residual sex signal within SCC-only and benign-only subsets.","literature":[{"short_citation":"Park et al., 2022","citation":"Park JO, Nam IC, Kim CS, et al. Sex Differences in the Prevalence of Head and Neck Cancers: A 10-Year Follow-Up Study of 10 Million Healthy People. Cancers. 2022","pmid":"35626129","pmcid":"PMC9139445","doi":"10.3390/cancers14102521","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9139445/","evidence_status":"needs claim-level validation"},{"short_citation":"Kruse et al., 2011","citation":"Kruse AL, Bredell M, Gratz KW. Oral cancer in men and women: are there differences? Oral and Maxillofacial Surgery. 2011","pmid":"21052752","doi":"10.1007/s10006-010-0253-6","url":"https://pubmed.ncbi.nlm.nih.gov/21052752/","evidence_status":"needs claim-level validation"},{"short_citation":"Lee et al., 2021","citation":"Lee YC, Young CK, Chien HT, et al. Characteristics and outcome differences in male and female oral cavity cancer patients in Taiwan. Medicine. 2021","pmid":"34871246","doi":"10.1097/MD.0000000000027674","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8568378/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Sex signal may reflect tobacco/alcohol or betel-associated field change.","mechanism":"Exposure patterns can alter keratinizing dysplasia/SCC, chronic mucosal injury, and field cancerization.","features":"Hyperkeratosis, keratinizing dysplasia/SCC, field change, chronic inflammation, ulceration, candidiasis.","confounders":"Smoking, alcohol, betel nut, diagnosis, subsite, age, institution.","validation":"Use exposure metadata if available; otherwise match keratinizing lesion subtype, dysplasia grade, and subsite.","literature":[{"short_citation":"Kruse et al., 2011","citation":"Kruse AL, Bredell M, Gratz KW. Oral cancer in men and women: are there differences? Oral and Maxillofacial Surgery. 2011","pmid":"21052752","doi":"10.1007/s10006-010-0253-6","url":"https://pubmed.ncbi.nlm.nih.gov/21052752/","evidence_status":"needs claim-level validation"},{"short_citation":"Lee et al., 2021","citation":"Lee YC, Young CK, Chien HT, et al. Characteristics and outcome differences in male and female oral cavity cancer patients in Taiwan. Medicine. 2021","pmid":"34871246","doi":"10.1097/MD.0000000000027674","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8568378/","evidence_status":"needs claim-level validation"},{"short_citation":"Pires et al., 2020","citation":"Pires FR, Barreto ME, Nunes JG, Carneiro NS, Azevedo AB, dos Santos TCRB. Oral potentially malignant disorders: clinical-pathological study of 684 cases diagnosed in a Brazilian population. Medicina Oral, Patologia Oral y Cirugia Bucal. 2020","pmid":"32683380","doi":"10.4317/medoral.23883","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7530402/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Sex differences in oral cancer subsite, stage, and treatment pathway may create shortcuts.","mechanism":"Men and women may differ in tumor location, presentation, clinical management, and outcomes.","features":"Tongue/floor-of-mouth/gingiva labels, depth/invasion, nodal/stage proxies, margin status, treatment effect, specimen type.","confounders":"Subsite, stage, tumor size/depth, grade, treatment status, procedure type.","validation":"Match subsite and stage; compare performance before/after adjustment and within untreated primary SCC only.","literature":[{"short_citation":"Lee et al., 2021","citation":"Lee YC, Young CK, Chien HT, et al. Characteristics and outcome differences in male and female oral cavity cancer patients in Taiwan. Medicine. 2021","pmid":"34871246","doi":"10.1097/MD.0000000000027674","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8568378/","evidence_status":"needs claim-level validation"},{"short_citation":"Kruse et al., 2011","citation":"Kruse AL, Bredell M, Gratz KW. Oral cancer in men and women: are there differences? Oral and Maxillofacial Surgery. 2011","pmid":"21052752","doi":"10.1007/s10006-010-0253-6","url":"https://pubmed.ncbi.nlm.nih.gov/21052752/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Female enrichment for oral lichen planus/lichenoid disease may create inflammatory morphology signal.","mechanism":"Oral lichen planus and lichenoid mucositis often show female predominance and have characteristic H&E interface inflammation.","features":"Band-like lymphocytic infiltrate, basal-cell degeneration, Civatte bodies, saw-tooth rete, hyperkeratosis, ulceration.","confounders":"Diagnosis, medication/contact reaction, site, age, biopsy indication.","validation":"Stratify or exclude OLP/lichenoid mucositis; test whether sex signal attenuates after matching lichenoid diagnoses.","literature":[{"short_citation":"Li et al., 2020","citation":"Li C, Tang X, Zheng X, et al. Global Prevalence and Incidence Estimates of Oral Lichen Planus: A Systematic Review and Meta-analysis. JAMA Dermatology. 2020","pmid":"31895414","doi":"10.1001/jamadermatol.2019.3797","url":"https://pubmed.ncbi.nlm.nih.gov/31895414/","evidence_status":"needs claim-level validation"},{"short_citation":"Fernandez-Gonzalez et al., 2011","citation":"Fernandez-Gonzalez F, Vazquez-Alvarez R, Reboiras-Lopez D, Gandara-Vila P, Garcia-Garcia A, Gandara-Rey JM. Histopathological findings in oral lichen planus and their correlation with the clinical manifestations. Medicina Oral, Patologia Oral y Cirugia Bucal. 2011","pmid":"20711172","pmcid":"PMC3448209","doi":"10.4317/medoral.16.e641","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3448209/","evidence_status":"needs claim-level validation"},{"short_citation":"Eisen, 2002","citation":"Eisen D. The clinical features, malignant potential, and systemic associations of oral lichen planus: a study of 723 patients. Journal of the American Academy of Dermatology. 2002","pmid":"11807431","doi":"10.1067/mjd.2002.120452","url":"https://pubmed.ncbi.nlm.nih.gov/11807431/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C5","section":"clinical_context","status":"active","hypothesis":"Female enrichment for Sjogren/xerostomia-related workups may create minor salivary gland signal.","mechanism":"Sjogren disease and sicca symptoms are female-skewed and often evaluated with labial/minor salivary gland biopsy.","features":"Minor salivary gland tissue, lymphocytic foci/focus score, acinar atrophy, duct dilation, fibrosis, fatty replacement.","confounders":"Salivary gland inclusion, Sjogren diagnosis, autoimmune disease, medication/radiation history, biopsy site.","validation":"Analyze slides with minor salivary gland tissue separately; match or exclude Sjogren/sicca workups.","literature":[{"short_citation":"Zhu et al., 2014","citation":"Zhu J, Zhang F, Jin J, et al. Characteristics of 110 patients with minor salivary gland biopsies. SpringerPlus. 2014","pmcid":"PMC4254825","doi":"10.1186/2193-1801-3-570","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4254825/","evidence_status":"needs claim-level validation"},{"short_citation":"Brizuela & Winters, 2023","citation":"Brizuela M, Winters R. Histology, Oral Mucosa. StatPearls. Updated 2023","pmid":"34033326","url":"https://www.ncbi.nlm.nih.gov/books/NBK572115/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Tumor differentiation, keratinization, and invasion may mediate sex signal.","mechanism":"Exposure-linked and subsite-linked SCC can differ in keratinization, grade, invasion, and treatment pathway.","features":"Keratin pearls, tumor grade, basaloid/non-keratinizing pattern, necrosis, perineural invasion, desmoplasia.","confounders":"Tumor subtype, HPV/p16, smoking/alcohol/betel, subsite, stage, treatment status.","validation":"Restrict to SCC and match grade/subsite/stage/exposure; inspect whether attention localizes to tumor versus surrounding mucosa.","literature":[{"short_citation":"Park et al., 2022","citation":"Park JO, Nam IC, Kim CS, et al. Sex Differences in the Prevalence of Head and Neck Cancers: A 10-Year Follow-Up Study of 10 Million Healthy People. Cancers. 2022","pmid":"35626129","pmcid":"PMC9139445","doi":"10.3390/cancers14102521","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9139445/","evidence_status":"needs claim-level validation"},{"short_citation":"Kruse et al., 2011","citation":"Kruse AL, Bredell M, Gratz KW. Oral cancer in men and women: are there differences? Oral and Maxillofacial Surgery. 2011","pmid":"21052752","doi":"10.1007/s10006-010-0253-6","url":"https://pubmed.ncbi.nlm.nih.gov/21052752/","evidence_status":"needs claim-level validation"},{"short_citation":"Lee et al., 2021","citation":"Lee YC, Young CK, Chien HT, et al. Characteristics and outcome differences in male and female oral cavity cancer patients in Taiwan. Medicine. 2021","pmid":"34871246","doi":"10.1097/MD.0000000000027674","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8568378/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Lichenoid/interface inflammation may be a direct sex-associated diagnostic carrier.","mechanism":"Female-enriched OLP/lichenoid disease has stereotyped H&E morphology that can be learned if diagnosis mix is imbalanced.","features":"Band-like lymphocytes, basal vacuolar change, Civatte bodies, saw-tooth rete ridges, ulceration, hyperkeratosis.","confounders":"OLP/lichenoid diagnosis, medication/contact reaction, site, age.","validation":"Match OLP/lichenoid status; run sensitivity analysis excluding lichenoid biopsies; quantify lymphocytic/interface features.","literature":[{"short_citation":"Li et al., 2020","citation":"Li C, Tang X, Zheng X, et al. Global Prevalence and Incidence Estimates of Oral Lichen Planus: A Systematic Review and Meta-analysis. JAMA Dermatology. 2020","pmid":"31895414","doi":"10.1001/jamadermatol.2019.3797","url":"https://pubmed.ncbi.nlm.nih.gov/31895414/","evidence_status":"needs claim-level validation"},{"short_citation":"Fernandez-Gonzalez et al., 2011","citation":"Fernandez-Gonzalez F, Vazquez-Alvarez R, Reboiras-Lopez D, Gandara-Vila P, Garcia-Garcia A, Gandara-Rey JM. Histopathological findings in oral lichen planus and their correlation with the clinical manifestations. Medicina Oral, Patologia Oral y Cirugia Bucal. 2011","pmid":"20711172","pmcid":"PMC3448209","doi":"10.4317/medoral.16.e641","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3448209/","evidence_status":"needs claim-level validation"},{"short_citation":"Eisen, 2002","citation":"Eisen D. The clinical features, malignant potential, and systemic associations of oral lichen planus: a study of 723 patients. Journal of the American Academy of Dermatology. 2002","pmid":"11807431","doi":"10.1067/mjd.2002.120452","url":"https://pubmed.ncbi.nlm.nih.gov/11807431/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Minor salivary gland autoimmune/sicca morphology may carry indirect sex signal.","mechanism":"Female-skewed Sjogren/sicca workups can introduce labial salivary gland biopsies with lymphocytic sialadenitis and atrophy/fibrosis.","features":"Lymphocytic foci, focus score, acinar atrophy, duct ectasia, periductal fibrosis, fatty replacement.","confounders":"Sjogren/sicca diagnosis, salivary gland sampling, age, medications, radiation.","validation":"Separate salivary-containing slides; match Sjogren/sicca diagnosis; test benign oral mucosa without glands independently.","literature":[{"short_citation":"Zhu et al., 2014","citation":"Zhu J, Zhang F, Jin J, et al. Characteristics of 110 patients with minor salivary gland biopsies. SpringerPlus. 2014","pmcid":"PMC4254825","doi":"10.1186/2193-1801-3-570","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4254825/","evidence_status":"needs claim-level validation"},{"short_citation":"Brizuela & Winters, 2023","citation":"Brizuela M, Winters R. Histology, Oral Mucosa. StatPearls. Updated 2023","pmid":"34033326","url":"https://www.ncbi.nlm.nih.gov/books/NBK572115/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Chronic inflammation, ulceration, and reactive injury may mediate residual sex signal.","mechanism":"Exposure, autoimmune/lichenoid disease, denture trauma, and oral-health context can alter inflammatory and repair morphology.","features":"Ulceration, granulation tissue, neutrophils, lymphoplasmacytic inflammation, candidiasis, fibrosis/scar.","confounders":"Diagnosis, ulceration, infection, exposure, denture/prosthetic context, subsite.","validation":"Annotate inflammatory/reactive diagnoses; test whether excluding ulcer/infection/OLP cases attenuates sex prediction.","literature":[{"short_citation":"Fitzpatrick et al., 2019","citation":"Fitzpatrick SG, Cohen DM, Clark AN. Ulcerated Lesions of the Oral Mucosa: Clinical and Histologic Review. Head and Neck Pathology. 2019","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6405793/","evidence_status":"source metadata incomplete"},{"short_citation":"Pires et al., 2020","citation":"Pires FR, Barreto ME, Nunes JG, Carneiro NS, Azevedo AB, dos Santos TCRB. Oral potentially malignant disorders: clinical-pathological study of 684 cases diagnosed in a Brazilian population. Medicina Oral, Patologia Oral y Cirugia Bucal. 2020","pmid":"32683380","doi":"10.4317/medoral.23883","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7530402/","evidence_status":"needs claim-level validation"},{"short_citation":"Li et al., 2020","citation":"Li C, Tang X, Zheng X, et al. Global Prevalence and Incidence Estimates of Oral Lichen Planus: A Systematic Review and Meta-analysis. JAMA Dermatology. 2020","pmid":"31895414","doi":"10.1001/jamadermatol.2019.3797","url":"https://pubmed.ncbi.nlm.nih.gov/31895414/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M5","section":"histomorphology","status":"active","hypothesis":"Direct benign oral epithelial sex morphology is not well established.","mechanism":"Sex hormones and immune dimorphism may have subtle mucosal effects, but current H&E support is much weaker than disease-context support.","features":"Epithelial thickness, keratinization, lamina propria collagen, vascularity, basal/parabasal cellularity.","confounders":"Subsite, age, inflammation, diagnosis, salivary tissue, exposure.","validation":"Test benign non-inflamed, subsite-matched mucosa only; require independent cohort replication before biological interpretation.","literature":[{"short_citation":"Brizuela & Winters, 2023","citation":"Brizuela M, Winters R. Histology, Oral Mucosa. StatPearls. Updated 2023","pmid":"34033326","url":"https://www.ncbi.nlm.nih.gov/books/NBK572115/","evidence_status":"needs claim-level validation"},{"short_citation":"Park et al., 2022","citation":"Park JO, Nam IC, Kim CS, et al. Sex Differences in the Prevalence of Head and Neck Cancers: A 10-Year Follow-Up Study of 10 Million Healthy People. Cancers. 2022","pmid":"35626129","pmcid":"PMC9139445","doi":"10.3390/cancers14102521","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9139445/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The strongest sex hypotheses are clinical-context signals: male enrichment for cancer, exposure-linked dysplasia/SCC, subsite/stage/procedure differences, female-enriched lichenoid disease, and female-enriched Sjogren/sicca minor salivary gland workups.","Unlike race, sex has some diagnosis-specific H&E morphology carriers with clearer literature support, especially OLP/lichenoid interface mucositis and minor salivary gland biopsy context. These remain mediated by diagnosis mix rather than normal-mucosa sex dimorphism.","The most important validation is matching by diagnosis, subsite, stage/grade, exposure proxy, procedure type, treatment status, lichenoid/OLP diagnosis, and salivary gland/Sjogren context."],"references":[{"n":1,"raw":"Park JO, Nam IC, Kim CS, et al. Sex Differences in the Prevalence of Head and Neck Cancers: A 10-Year Follow-Up Study of 10 Million Healthy People. Cancers. 2022. PMID: 35626129. PMCID: PMC9139445. DOI: 10.3390/cancers14102521. https://pmc.ncbi.nlm.nih.gov/articles/PMC9139445/","citation":"Park JO, Nam IC, Kim CS, et al. Sex Differences in the Prevalence of Head and Neck Cancers: A 10-Year Follow-Up Study of 10 Million Healthy People. Cancers. 2022","year":"2022","pmid":"35626129","pmcid":"PMC9139445","doi":"10.3390/cancers14102521","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9139445/"},{"n":2,"raw":"Kruse AL, Bredell M, Gratz KW. Oral cancer in men and women: are there differences? Oral and Maxillofacial Surgery. 2011. PMID: 21052752. DOI: 10.1007/s10006-010-0253-6. https://pubmed.ncbi.nlm.nih.gov/21052752/","citation":"Kruse AL, Bredell M, Gratz KW. Oral cancer in men and women: are there differences? Oral and Maxillofacial Surgery. 2011","year":"2011","pmid":"21052752","doi":"10.1007/s10006-010-0253-6","url":"https://pubmed.ncbi.nlm.nih.gov/21052752/"},{"n":3,"raw":"Lee YC, Young CK, Chien HT, et al. Characteristics and outcome differences in male and female oral cavity cancer patients in Taiwan. Medicine. 2021. PMID: 34871246. DOI: 10.1097/MD.0000000000027674. https://pmc.ncbi.nlm.nih.gov/articles/PMC8568378/","citation":"Lee YC, Young CK, Chien HT, et al. Characteristics and outcome differences in male and female oral cavity cancer patients in Taiwan. Medicine. 2021","year":"2021","pmid":"34871246","doi":"10.1097/MD.0000000000027674","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8568378/"},{"n":4,"raw":"Pires FR, Barreto ME, Nunes JG, Carneiro NS, Azevedo AB, dos Santos TCRB. Oral potentially malignant disorders: clinical-pathological study of 684 cases diagnosed in a Brazilian population. Medicina Oral, Patologia Oral y Cirugia Bucal. 2020. PMID: 32683380. DOI: 10.4317/medoral.23883. https://pmc.ncbi.nlm.nih.gov/articles/PMC7530402/","citation":"Pires FR, Barreto ME, Nunes JG, Carneiro NS, Azevedo AB, dos Santos TCRB. Oral potentially malignant disorders: clinical-pathological study of 684 cases diagnosed in a Brazilian population. Medicina Oral, Patologia Oral y Cirugia Bucal. 2020","year":"2020","pmid":"32683380","doi":"10.4317/medoral.23883","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7530402/"},{"n":5,"raw":"Li C, Tang X, Zheng X, et al. Global Prevalence and Incidence Estimates of Oral Lichen Planus: A Systematic Review and Meta-analysis. JAMA Dermatology. 2020. PMID: 31895414. DOI: 10.1001/jamadermatol.2019.3797. https://pubmed.ncbi.nlm.nih.gov/31895414/","citation":"Li C, Tang X, Zheng X, et al. Global Prevalence and Incidence Estimates of Oral Lichen Planus: A Systematic Review and Meta-analysis. JAMA Dermatology. 2020","year":"2020","pmid":"31895414","doi":"10.1001/jamadermatol.2019.3797","url":"https://pubmed.ncbi.nlm.nih.gov/31895414/"},{"n":6,"raw":"Fernandez-Gonzalez F, Vazquez-Alvarez R, Reboiras-Lopez D, Gandara-Vila P, Garcia-Garcia A, Gandara-Rey JM. Histopathological findings in oral lichen planus and their correlation with the clinical manifestations. Medicina Oral, Patologia Oral y Cirugia Bucal. 2011. PMID: 20711172. PMCID: PMC3448209. DOI: 10.4317/medoral.16.e641. https://pmc.ncbi.nlm.nih.gov/articles/PMC3448209/","citation":"Fernandez-Gonzalez F, Vazquez-Alvarez R, Reboiras-Lopez D, Gandara-Vila P, Garcia-Garcia A, Gandara-Rey JM. Histopathological findings in oral lichen planus and their correlation with the clinical manifestations. Medicina Oral, Patologia Oral y Cirugia Bucal. 2011","year":"2011","pmid":"20711172","pmcid":"PMC3448209","doi":"10.4317/medoral.16.e641","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3448209/"},{"n":7,"raw":"Eisen D. The clinical features, malignant potential, and systemic associations of oral lichen planus: a study of 723 patients. Journal of the American Academy of Dermatology. 2002. PMID: 11807431. DOI: 10.1067/mjd.2002.120452. https://pubmed.ncbi.nlm.nih.gov/11807431/","citation":"Eisen D. The clinical features, malignant potential, and systemic associations of oral lichen planus: a study of 723 patients. Journal of the American Academy of Dermatology. 2002","year":"2002","pmid":"11807431","doi":"10.1067/mjd.2002.120452","url":"https://pubmed.ncbi.nlm.nih.gov/11807431/"},{"n":8,"raw":"Zhu J, Zhang F, Jin J, et al. Characteristics of 110 patients with minor salivary gland biopsies. SpringerPlus. 2014. PMCID: PMC4254825. DOI: 10.1186/2193-1801-3-570. https://pmc.ncbi.nlm.nih.gov/articles/PMC4254825/","citation":"Zhu J, Zhang F, Jin J, et al. Characteristics of 110 patients with minor salivary gland biopsies. SpringerPlus. 2014","year":"2014","pmcid":"PMC4254825","doi":"10.1186/2193-1801-3-570","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4254825/"},{"n":9,"raw":"Brizuela M, Winters R. Histology, Oral Mucosa. StatPearls. Updated 2023. PMID: 34033326. https://www.ncbi.nlm.nih.gov/books/NBK572115/","citation":"Brizuela M, Winters R. Histology, Oral Mucosa. StatPearls. Updated 2023","year":"2023","pmid":"34033326","url":"https://www.ncbi.nlm.nih.gov/books/NBK572115/"},{"n":10,"raw":"Fitzpatrick SG, Cohen DM, Clark AN. Ulcerated Lesions of the Oral Mucosa: Clinical and Histologic Review. Head and Neck Pathology. 2019. https://pmc.ncbi.nlm.nih.gov/articles/PMC6405793/","citation":"Fitzpatrick SG, Cohen DM, Clark AN. Ulcerated Lesions of the Oral Mucosa: Clinical and Histologic Review. Head and Neck Pathology. 2019","year":"2019","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6405793/"}],"filename":"mouth_oral_cavity__sex.yaml"},{"combo":"ovary__age","organ_slug":"ovary","organ":"Ovary","demographic":"age","demographic_label":"Age","summary":"Ovary age signal is a stable residual candidate but data-limited by specimen group. The most plausible morphology carriers are follicle depletion, corpora albicantia, stromal fibrosis, collagen accumulation, cortical remodeling, vascular changes, and age-skewed tumor/cyst/procedure indications.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Ovarian disease and procedure indications vary by age.","mechanism":"Younger patients may be enriched for cysts/endometriosis/fertility-related procedures; older patients for neoplasia and prophylactic or postmenopausal surgery.","features":"Benign cysts, endometriosis, epithelial tumors, metastatic disease, oophorectomy indication.","confounders":"Diagnosis, procedure, tumor histotype, laterality, BRCA/prophylaxis.","validation":"Match tumor/benign category and procedure; test residual age signal in benign ovarian cortex.","literature":[{"short_citation":"Shen et al., 2023","citation":"Shen L, Liu J, Luo A, Wang S. The stromal microenvironment and ovarian aging: mechanisms and therapeutic opportunities. Journal of Ovarian Research. 2023","pmid":"38093329","pmcid":"PMC10717903","doi":"10.1186/s13048-023-01300-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Tumor histotype and malignancy context can create age shortcuts.","mechanism":"High-grade serous carcinoma and other neoplasms have age distributions and strong H&E patterns.","features":"Tumor histotype, grade, necrosis, stromal invasion, treatment effect.","confounders":"Histotype, grade, stage, treatment, tissue sampling.","validation":"Exclude neoplastic cases or match histotype/stage before morphology interpretation.","literature":[{"short_citation":"Shen et al., 2023","citation":"Shen L, Liu J, Luo A, Wang S. The stromal microenvironment and ovarian aging: mechanisms and therapeutic opportunities. Journal of Ovarian Research. 2023","pmid":"38093329","pmcid":"PMC10717903","doi":"10.1186/s13048-023-01300-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Endometriosis and functional cyst indications may enrich younger cases.","mechanism":"Reproductive-age disease mix changes benign ovarian morphology and procedure pathways.","features":"Endometriosis, hemorrhagic cyst, corpus luteum, follicular cyst, adhesions.","confounders":"Diagnosis, cycle/reproductive status, procedure type, hormonal therapy.","validation":"Stratify benign cyst/endometriosis cases separately from tumor/prophylactic cases.","literature":[{"short_citation":"Shen et al., 2023","citation":"Shen L, Liu J, Luo A, Wang S. The stromal microenvironment and ovarian aging: mechanisms and therapeutic opportunities. Journal of Ovarian Research. 2023","pmid":"38093329","pmcid":"PMC10717903","doi":"10.1186/s13048-023-01300-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Prophylactic oophorectomy and postmenopausal adnexal mass workups may enrich older cases.","mechanism":"Risk-reduction surgery and malignancy exclusion alter amount of benign cortex, tube/ovary, and tumor tissue sampled.","features":"Benign cortex, inclusion cysts, serous tubal intraepithelial carcinoma if present, epithelial tumor.","confounders":"BRCA/prophylaxis, menopause, tube inclusion, procedure type.","validation":"Match indication and procedure type before reviewing age biology.","literature":[{"short_citation":"Shen et al., 2023","citation":"Shen L, Liu J, Luo A, Wang S. The stromal microenvironment and ovarian aging: mechanisms and therapeutic opportunities. Journal of Ovarian Research. 2023","pmid":"38093329","pmcid":"PMC10717903","doi":"10.1186/s13048-023-01300-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Ovarian aging is associated with stromal fibrosis and collagen remodeling.","mechanism":"Aging stromal microenvironment accumulates collagen/fibrosis and changes stiffness.","features":"Cortical stromal fibrosis, collagen density, stromal cellularity, hyalinization.","confounders":"Tumor desmoplasia, endometriosis, inflammation, sampling site.","validation":"Quantify stromal collagen in benign cortex after diagnosis matching.","literature":[{"short_citation":"Briley et al., 2016","citation":"Briley SM, Jasti S, McCracken JM, et al. Reproductive age-associated fibrosis in the stroma of the mammalian ovary. Reproduction. 2016","pmid":"27491879","pmcid":"PMC4979755","doi":"10.1530/REP-16-0129","evidence_status":"needs claim-level validation"},{"short_citation":"Shen et al., 2023","citation":"Shen L, Liu J, Luo A, Wang S. The stromal microenvironment and ovarian aging: mechanisms and therapeutic opportunities. Journal of Ovarian Research. 2023","pmid":"38093329","pmcid":"PMC10717903","doi":"10.1186/s13048-023-01300-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Follicle depletion and corpora albicantia encode reproductive age.","mechanism":"Ovarian reserve declines with age, altering follicle density and cortical composition.","features":"Primordial/primary follicles, corpora albicantia, cortical thickness.","confounders":"Tissue sampling, cyst/tumor replacement, prior surgery, endocrine status.","validation":"Restrict to benign cortex-containing slides and quantify follicle/corpora features.","literature":[{"short_citation":"Shen et al., 2023","citation":"Shen L, Liu J, Luo A, Wang S. The stromal microenvironment and ovarian aging: mechanisms and therapeutic opportunities. Journal of Ovarian Research. 2023","pmid":"38093329","pmcid":"PMC10717903","doi":"10.1186/s13048-023-01300-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Vascular and immune microenvironment changes may contribute.","mechanism":"Aging ovary remodels stromal/vascular/immune niches.","features":"Vascular density/sclerosis, inflammatory cells, stromal edema/fibrosis.","confounders":"Tumor, endometriosis, inflammation, fixation.","validation":"Pathologist review of benign stromal regions matched by diagnosis.","literature":[{"short_citation":"Shen et al., 2023","citation":"Shen L, Liu J, Luo A, Wang S. The stromal microenvironment and ovarian aging: mechanisms and therapeutic opportunities. Journal of Ovarian Research. 2023","pmid":"38093329","pmcid":"PMC10717903","doi":"10.1186/s13048-023-01300-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Inclusion cysts and epithelial invaginations may act as age-associated background features.","mechanism":"Repeated ovulation and aging can alter ovarian surface/cortical epithelial structures.","features":"Inclusion cysts, surface epithelium, cortical invaginations, stromal scarring.","confounders":"Sampling site, tumor adjacency, endometriosis, prophylactic surgery.","validation":"Score benign cortex features after excluding tumors and endometriosis.","literature":[{"short_citation":"Shen et al., 2023","citation":"Shen L, Liu J, Luo A, Wang S. The stromal microenvironment and ovarian aging: mechanisms and therapeutic opportunities. Journal of Ovarian Research. 2023","pmid":"38093329","pmcid":"PMC10717903","doi":"10.1186/s13048-023-01300-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["Best review target: benign ovarian cortex, follicle density, corpora albicantia, and stromal collagen/fibrosis.","Main shortcut risk: neoplastic histotype and procedure indication.","Data-limited flag means pathologist review should check sample adequacy and benign cortex availability."],"references":[{"n":1,"raw":"Briley SM, Jasti S, McCracken JM, et al. Reproductive age-associated fibrosis in the stroma of the mammalian ovary. Reproduction. 2016. PMID: 27491879. PMCID: PMC4979755. DOI: 10.1530/REP-16-0129.","citation":"Briley SM, Jasti S, McCracken JM, et al. Reproductive age-associated fibrosis in the stroma of the mammalian ovary. Reproduction. 2016","year":"2016","pmid":"27491879","pmcid":"PMC4979755","doi":"10.1530/REP-16-0129"},{"n":2,"raw":"Shen L, Liu J, Luo A, Wang S. The stromal microenvironment and ovarian aging: mechanisms and therapeutic opportunities. Journal of Ovarian Research. 2023. PMID: 38093329. PMCID: PMC10717903. DOI: 10.1186/s13048-023-01300-4.","citation":"Shen L, Liu J, Luo A, Wang S. The stromal microenvironment and ovarian aging: mechanisms and therapeutic opportunities. Journal of Ovarian Research. 2023","year":"2023","pmid":"38093329","pmcid":"PMC10717903","doi":"10.1186/s13048-023-01300-4"}],"filename":"ovary__age.yaml"},{"combo":"sinus_sinonasal_tract__age","organ_slug":"sinus_sinonasal_tract","organ":"Sinus / Sinonasal Tract","demographic":"age","demographic_label":"Age Group","summary":"Age signal in sinonasal specimens is likely mixed but diagnosis-dependent. Clinical-context signal may come from age-associated distributions of CRS/nasal polyps, allergic/fungal disease, Schneiderian papilloma, and sinonasal malignancy. Morphology signal is more likely chronic inflammatory remodeling than generic normal-aging histology.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Age signal may reflect CRS/nasal polyp diagnosis mix.","mechanism":"CRS with/without nasal polyps varies by clinical phenotype and age distribution.","features":"Polypoid edema, respiratory mucosa, eosinophils/neutrophils, basement membrane thickening.","confounders":"CRS phenotype, polyp status, subsite, procedure type.","validation":"Match CRS phenotype and polyp status; test residual age signal within CRS-only cases.","literature":[{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Older patients may be enriched for sinonasal neoplasia.","mechanism":"Sinonasal malignancies and papillomas are more common in adult/older surgical specimens than pediatric inflammatory biopsies.","features":"SCC, adenocarcinoma, melanoma, Schneiderian papilloma, dysplasia, bone invasion, necrosis.","confounders":"Benign/malignant status, histologic subtype, stage, subsite.","validation":"Exclude tumors or match tumor histology/stage; test attenuation.","literature":[{"short_citation":"Smaadahl et al., 2024","citation":"Smaadahl N, Hool S, Reinhardt P, et al. Treatment and related morbidity of nasal cavity and paranasal sinus cancers. Frontiers in Oncology. 2024","doi":"10.3389/fonc.2024.1422892","url":"https://www.frontiersin.org/journals/oncology/articles/10.3389/fonc.2024.1422892/full","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Fungal/allergic disease distribution may contribute to age signal.","mechanism":"Allergic fungal rhinosinusitis or fungal disease can shift case mix by age and clinical setting.","features":"Allergic mucin, Charcot-Leyden crystals, fungal hyphae, eosinophils, necrosis.","confounders":"Diagnosis, immunosuppression, diabetes, subsite, institution.","validation":"Match fungal/allergic diagnoses and immune status if available.","literature":[{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Procedure type may encode age.","mechanism":"Pediatric/young adult biopsies, polypectomies, sinus surgeries, and cancer resections differ in tissue composition.","features":"Small biopsy vs functional endoscopic sinus surgery vs resection, bone/cartilage, margin/treatment tissue.","confounders":"Procedure type, subsite, diagnosis.","validation":"Stratify by procedure type and tissue source.","literature":[{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"},{"short_citation":"Smaadahl et al., 2024","citation":"Smaadahl N, Hool S, Reinhardt P, et al. Treatment and related morbidity of nasal cavity and paranasal sinus cancers. Frontiers in Oncology. 2024","doi":"10.3389/fonc.2024.1422892","url":"https://www.frontiersin.org/journals/oncology/articles/10.3389/fonc.2024.1422892/full","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Chronic epithelial remodeling may encode age within inflammatory disease.","mechanism":"Repeated inflammation can alter respiratory epithelium and repair state.","features":"Epithelial denudation, squamous metaplasia, goblet-cell change, basement membrane thickening.","confounders":"CRS phenotype, smoking/exposure, infection, treatment.","validation":"Quantify epithelial remodeling in CRS/polyp cases matched by endotype and subsite.","literature":[{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Stromal edema/fibrosis balance may vary by age or disease chronicity.","mechanism":"Chronic rhinosinusitis remodeling can produce edema, fibrosis, and glandular change.","features":"Stromal edema, fibrosis, submucosal gland hyperplasia, vascular congestion.","confounders":"Polyp status, CRS endotype, steroid treatment, subsite.","validation":"Compare stromal texture after CRS subtype and treatment matching.","literature":[{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Inflammatory cell composition may shift with age.","mechanism":"Age and inflammatory phenotype may alter eosinophilic vs neutrophilic patterns.","features":"Eosinophils, neutrophils, lymphoplasmacytic inflammation, lymphoid aggregates.","confounders":"CRS endotype, infection, allergy/asthma, steroid treatment.","validation":"Cell-count analysis within matched CRS endotypes; test whether inflammation explains age prediction.","literature":[{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"},{"short_citation":"Chiu et al., 2025","citation":"Chiu RG, et al. Biological Sex and Chronic Rhinosinusitis Diagnosis, Phenotype, and Inflammatory Profile. 2025","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12550736/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Direct normal sinonasal aging morphology is weakly established.","mechanism":"Residual age signal may reflect unmeasured disease chronicity rather than intrinsic aging.","features":"Benign respiratory mucosa, glands, vessels, stroma without overt CRS/tumor.","confounders":"Subsite, inflammation, procedure, exposure.","validation":"Test benign, non-polyp, non-tumor mucosa after strict matching; require cautious interpretation.","literature":[{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The strongest clinical-context hypotheses are CRS/polyp mix, neoplasia, fungal/allergic disease, and procedure type.","The most plausible morphology hypotheses involve inflammatory remodeling: epithelial change, stromal edema/fibrosis, and inflammatory cell composition.","The most important validation is matching by diagnosis, CRS endotype/polyp status, benign/malignant status, subsite, and procedure type."],"references":[{"n":1,"raw":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020. PMID: 32077450. DOI: 10.4193/Rhin20.600. https://pubmed.ncbi.nlm.nih.gov/32077450/","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","year":"2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/"},{"n":2,"raw":"Smaadahl N, Hool S, Reinhardt P, et al. Treatment and related morbidity of nasal cavity and paranasal sinus cancers. Frontiers in Oncology. 2024. DOI: 10.3389/fonc.2024.1422892. https://www.frontiersin.org/journals/oncology/articles/10.3389/fonc.2024.1422892/full","citation":"Smaadahl N, Hool S, Reinhardt P, et al. Treatment and related morbidity of nasal cavity and paranasal sinus cancers. Frontiers in Oncology. 2024","year":"2024","doi":"10.3389/fonc.2024.1422892","url":"https://www.frontiersin.org/journals/oncology/articles/10.3389/fonc.2024.1422892/full"},{"n":3,"raw":"Chiu RG, et al. Biological Sex and Chronic Rhinosinusitis Diagnosis, Phenotype, and Inflammatory Profile. 2025. https://pmc.ncbi.nlm.nih.gov/articles/PMC12550736/","citation":"Chiu RG, et al. Biological Sex and Chronic Rhinosinusitis Diagnosis, Phenotype, and Inflammatory Profile. 2025","year":"2025","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12550736/"}],"filename":"sinus_sinonasal_tract__age.yaml"},{"combo":"sinus_sinonasal_tract__race_self_reported_ancestry","organ_slug":"sinus_sinonasal_tract","organ":"Sinus / Sinonasal Tract","demographic":"race_self_reported_ancestry","demographic_label":"Race / Self-Reported Ancestry","summary":"Race/self-reported ancestry signal in sinonasal histology is expected to be mainly clinical-context, exposure, access, and workflow mediated. Candidate mechanisms include disparities in CRS care, environmental/occupational exposures, surgery access, cancer stage, and histologic subtype. Direct race-specific sinonasal tissue morphology is not established.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Race signal may reflect disparities in CRS diagnosis and surgical access.","mechanism":"Access and referral patterns can alter who reaches sinus surgery and what disease severity is sampled.","features":"CRS/polyp tissue, eosinophilic/neutrophilic inflammation, fibrosis, extent of surgery.","confounders":"Institution, insurance/SES, CRS phenotype, procedure type.","validation":"Use institution/procedure controls and CRS-specific cohorts if metadata exist.","literature":[{"short_citation":"Whitehead et al., 2025","citation":"Whitehead RA, et al. A Systematic Review of Health Disparities in Chronic Rhinosinusitis. Otolaryngology-Head and Neck Surgery. 2025","pmid":"40949889","url":"https://pubmed.ncbi.nlm.nih.gov/40949889/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Race signal may reflect sinonasal cancer stage and outcomes.","mechanism":"Racial/ethnic survival disparities can correlate with tumor characteristics and advanced presentation.","features":"Tumor subtype, necrosis, invasion, bone involvement, margin/treatment tissue.","confounders":"Stage, histologic subtype, subsite, treatment status, institution.","validation":"Match tumor subtype and stage; test residual signal in cancer-only subsets.","literature":[{"short_citation":"Smith et al., 2015","citation":"Smith SP, Russell JL, Chen NW, Kuo YF, Resto VA. Sinonasal Carcinoma: Racial and Ethnic Disparities in Survival-A Review of 4714 Patients. Otolaryngology-Head and Neck Surgery. 2015","pmid":"26163451","doi":"10.1177/0194599815593277","url":"https://journals.sagepub.com/doi/10.1177/0194599815593277","evidence_status":"needs claim-level validation"},{"short_citation":"Sharma et al., 2021","citation":"Sharma RK, et al. Racial and ethnic disparities in paranasal sinus malignancies. Laryngoscope. 2021","pmid":"34096200","doi":"10.1002/lary.29730","url":"https://pubmed.ncbi.nlm.nih.gov/34096200/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Environmental or occupational exposures may mediate subtype mix.","mechanism":"Exposures linked to sinonasal adenocarcinoma or SCC may vary by occupation/geography/access.","features":"Adenocarcinoma, SCC, dysplasia, respiratory epithelial injury, inflammatory background.","confounders":"Occupation, smoking, subsite, tumor histology, geography.","validation":"Use tumor histology and occupational proxy metadata if available; otherwise treat as residual confounding.","literature":[{"short_citation":"Sharma et al., 2021","citation":"Sharma RK, et al. Racial and ethnic disparities in paranasal sinus malignancies. Laryngoscope. 2021","pmid":"34096200","doi":"10.1002/lary.29730","url":"https://pubmed.ncbi.nlm.nih.gov/34096200/","evidence_status":"needs claim-level validation"},{"short_citation":"Smith et al., 2015","citation":"Smith SP, Russell JL, Chen NW, Kuo YF, Resto VA. Sinonasal Carcinoma: Racial and Ethnic Disparities in Survival-A Review of 4714 Patients. Otolaryngology-Head and Neck Surgery. 2015","pmid":"26163451","doi":"10.1177/0194599815593277","url":"https://journals.sagepub.com/doi/10.1177/0194599815593277","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Workflow/institution effects may encode race.","mechanism":"Referral center, scanner, processing, and surgery access can correlate with self-reported race.","features":"Tissue size, biopsy/resection type, cautery, decalcification, institution/scanner metadata.","confounders":"Institution, scanner, procedure type, year, block source.","validation":"Institution- and scanner-balanced evaluation; remove edge/artifact regions.","literature":[{"short_citation":"Whitehead et al., 2025","citation":"Whitehead RA, et al. A Systematic Review of Health Disparities in Chronic Rhinosinusitis. Otolaryngology-Head and Neck Surgery. 2025","pmid":"40949889","url":"https://pubmed.ncbi.nlm.nih.gov/40949889/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Inflammatory endotype may mediate apparent race signal.","mechanism":"CRS endotypes can differ by exposure, access, environment, or comorbidity.","features":"Eosinophils, neutrophils, edema, fibrosis, basement membrane thickening, glands.","confounders":"CRS phenotype, allergy/asthma, infection, steroid treatment, institution.","validation":"Match CRS endotype and comorbidities; quantify inflammatory cell composition.","literature":[{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"},{"short_citation":"Whitehead et al., 2025","citation":"Whitehead RA, et al. A Systematic Review of Health Disparities in Chronic Rhinosinusitis. Otolaryngology-Head and Neck Surgery. 2025","pmid":"40949889","url":"https://pubmed.ncbi.nlm.nih.gov/40949889/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Tumor morphology may mediate apparent race signal.","mechanism":"Histologic subtype and stage differences can produce visible tumor patterns.","features":"SCC vs adenocarcinoma vs melanoma, necrosis, invasion pattern, desmoplasia.","confounders":"Tumor histology, stage, subsite, treatment.","validation":"Tumor-subtype and stage-matched analysis.","literature":[{"short_citation":"Smith et al., 2015","citation":"Smith SP, Russell JL, Chen NW, Kuo YF, Resto VA. Sinonasal Carcinoma: Racial and Ethnic Disparities in Survival-A Review of 4714 Patients. Otolaryngology-Head and Neck Surgery. 2015","pmid":"26163451","doi":"10.1177/0194599815593277","url":"https://journals.sagepub.com/doi/10.1177/0194599815593277","evidence_status":"needs claim-level validation"},{"short_citation":"Sharma et al., 2021","citation":"Sharma RK, et al. Racial and ethnic disparities in paranasal sinus malignancies. Laryngoscope. 2021","pmid":"34096200","doi":"10.1002/lary.29730","url":"https://pubmed.ncbi.nlm.nih.gov/34096200/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Direct intrinsic sinonasal morphology by race is unsupported.","mechanism":"Race is not a direct biological tissue variable; residual signal likely reflects unmeasured context.","features":"Benign respiratory mucosa after strict matching.","confounders":"Subsite, diagnosis, institution, exposure, treatment.","validation":"Test matched benign mucosa; require external replication before interpretation.","literature":[{"short_citation":"Whitehead et al., 2025","citation":"Whitehead RA, et al. A Systematic Review of Health Disparities in Chronic Rhinosinusitis. Otolaryngology-Head and Neck Surgery. 2025","pmid":"40949889","url":"https://pubmed.ncbi.nlm.nih.gov/40949889/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The strongest hypotheses are CRS care/access, cancer stage/subtype, occupational/environmental exposure, and workflow.","Morphology hypotheses should be framed as endotype-, tumor-, exposure-, or access-mediated rather than direct race biology.","The most important validation is matching by diagnosis/endotype, tumor histology/stage, subsite, procedure type, institution, and scanner."],"references":[{"n":1,"raw":"Smith SP, Russell JL, Chen NW, Kuo YF, Resto VA. Sinonasal Carcinoma: Racial and Ethnic Disparities in Survival-A Review of 4714 Patients. Otolaryngology-Head and Neck Surgery. 2015. PMID: 26163451. DOI: 10.1177/0194599815593277. https://journals.sagepub.com/doi/10.1177/0194599815593277","citation":"Smith SP, Russell JL, Chen NW, Kuo YF, Resto VA. Sinonasal Carcinoma: Racial and Ethnic Disparities in Survival-A Review of 4714 Patients. Otolaryngology-Head and Neck Surgery. 2015","year":"2015","pmid":"26163451","doi":"10.1177/0194599815593277","url":"https://journals.sagepub.com/doi/10.1177/0194599815593277"},{"n":2,"raw":"Sharma RK, et al. Racial and ethnic disparities in paranasal sinus malignancies. Laryngoscope. 2021. PMID: 34096200. DOI: 10.1002/lary.29730. https://pubmed.ncbi.nlm.nih.gov/34096200/","citation":"Sharma RK, et al. Racial and ethnic disparities in paranasal sinus malignancies. Laryngoscope. 2021","year":"2021","pmid":"34096200","doi":"10.1002/lary.29730","url":"https://pubmed.ncbi.nlm.nih.gov/34096200/"},{"n":3,"raw":"Whitehead RA, et al. A Systematic Review of Health Disparities in Chronic Rhinosinusitis. Otolaryngology-Head and Neck Surgery. 2025. PMID: 40949889. https://pubmed.ncbi.nlm.nih.gov/40949889/","citation":"Whitehead RA, et al. A Systematic Review of Health Disparities in Chronic Rhinosinusitis. Otolaryngology-Head and Neck Surgery. 2025","year":"2025","pmid":"40949889","url":"https://pubmed.ncbi.nlm.nih.gov/40949889/"},{"n":4,"raw":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020. PMID: 32077450. DOI: 10.4193/Rhin20.600. https://pubmed.ncbi.nlm.nih.gov/32077450/","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","year":"2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/"}],"filename":"sinus_sinonasal_tract__race_self_reported_ancestry.yaml"},{"combo":"sinus_sinonasal_tract__sex","organ_slug":"sinus_sinonasal_tract","organ":"Sinus / Sinonasal Tract","demographic":"sex","demographic_label":"Sex","summary":"Sex signal in sinonasal histology is likely mixed but substantially clinical-context mediated. Male predominance in some sinonasal cancers may reflect occupational exposures, smoking, and histologic subtype. CRS phenotype and inflammatory profile may also vary by sex, potentially producing H&E-visible inflammatory and stromal remodeling differences.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Male patients may be enriched for sinonasal malignancy.","mechanism":"Sinonasal cancer incidence and exposure-linked cancers can show male predominance.","features":"SCC, adenocarcinoma, melanoma, necrosis, invasion, resection specimens.","confounders":"Benign/malignant status, histologic subtype, occupation, smoking, stage.","validation":"Match benign/malignant status and tumor histology/stage.","literature":[{"short_citation":"Binazzi et al., 2024","citation":"Binazzi A, di Marzio D, Mensi C, et al. Gender Differences in Sinonasal Cancer Incidence: Data from the Italian Registry. Cancers. 2024","doi":"10.3390/cancers16112053","url":"https://www.mdpi.com/2072-6694/16/11/2053","evidence_status":"needs claim-level validation"},{"short_citation":"Smaadahl et al., 2024","citation":"Smaadahl N, Hool S, Reinhardt P, et al. Treatment and related morbidity of nasal cavity and paranasal sinus cancers. Frontiers in Oncology. 2024","doi":"10.3389/fonc.2024.1422892","url":"https://www.frontiersin.org/journals/oncology/articles/10.3389/fonc.2024.1422892/full","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Occupational exposure may mediate sex signal.","mechanism":"Wood dust/industrial exposure patterns can affect sinonasal adenocarcinoma risk.","features":"Intestinal-type adenocarcinoma, dysplasia, respiratory epithelial injury.","confounders":"Occupation, tumor subtype, subsite, smoking.","validation":"Use occupational metadata if available; otherwise match tumor histology/subsite.","literature":[{"short_citation":"Binazzi et al., 2024","citation":"Binazzi A, di Marzio D, Mensi C, et al. Gender Differences in Sinonasal Cancer Incidence: Data from the Italian Registry. Cancers. 2024","doi":"10.3390/cancers16112053","url":"https://www.mdpi.com/2072-6694/16/11/2053","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"CRS diagnosis and phenotype may differ by sex.","mechanism":"Biological sex may associate with CRS diagnosis, phenotype, and inflammatory profile.","features":"CRS with/without polyps, eosinophils/neutrophils, edema, fibrosis.","confounders":"CRS phenotype, asthma/allergy, steroid treatment, subsite.","validation":"Match CRS phenotype/endotype and comorbid allergy/asthma.","literature":[{"short_citation":"Chiu et al., 2025","citation":"Chiu RG, et al. Biological Sex and Chronic Rhinosinusitis Diagnosis, Phenotype, and Inflammatory Profile. 2025","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12550736/","evidence_status":"source metadata incomplete"},{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Procedure type may differ by sex through tumor or CRS pathways.","mechanism":"Different case mix can affect biopsy/resection/polypectomy distribution.","features":"Biopsy vs sinus surgery vs tumor resection, margins, bone/cartilage, treatment effect.","confounders":"Diagnosis, procedure type, institution.","validation":"Stratify by procedure type and diagnosis category.","literature":[{"short_citation":"Smaadahl et al., 2024","citation":"Smaadahl N, Hool S, Reinhardt P, et al. Treatment and related morbidity of nasal cavity and paranasal sinus cancers. Frontiers in Oncology. 2024","doi":"10.3389/fonc.2024.1422892","url":"https://www.frontiersin.org/journals/oncology/articles/10.3389/fonc.2024.1422892/full","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Sex may influence eosinophilic versus neutrophilic CRS inflammation.","mechanism":"Sex-linked immune regulation may alter inflammatory profiles.","features":"Eosinophils, neutrophils, lymphoplasmacytic inflammation, allergic mucin.","confounders":"CRS endotype, allergy/asthma, infection, steroids.","validation":"Cell-count analysis within CRS/polyp matched subsets.","literature":[{"short_citation":"Chiu et al., 2025","citation":"Chiu RG, et al. Biological Sex and Chronic Rhinosinusitis Diagnosis, Phenotype, and Inflammatory Profile. 2025","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12550736/","evidence_status":"source metadata incomplete"},{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Sex may influence stromal remodeling in nasal polyps/CRS.","mechanism":"Inflammatory pathways can alter edema, fibrosis, glands, and basement membrane thickening.","features":"Edema, fibrosis, basement membrane thickening, glandular hyperplasia, epithelial remodeling.","confounders":"CRS phenotype, treatment, subsite, chronicity.","validation":"Quantify remodeling features after endotype and treatment matching.","literature":[{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"},{"short_citation":"Chiu et al., 2025","citation":"Chiu RG, et al. Biological Sex and Chronic Rhinosinusitis Diagnosis, Phenotype, and Inflammatory Profile. 2025","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12550736/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Tumor histology may mediate apparent sex morphology.","mechanism":"Sex-associated cancer subtype distribution produces visible morphology differences.","features":"SCC/adenocarcinoma/melanoma subtype, necrosis, invasion, desmoplasia.","confounders":"Tumor subtype, stage, exposure, treatment.","validation":"Tumor-only analysis matched by histology/stage.","literature":[{"short_citation":"Binazzi et al., 2024","citation":"Binazzi A, di Marzio D, Mensi C, et al. Gender Differences in Sinonasal Cancer Incidence: Data from the Italian Registry. Cancers. 2024","doi":"10.3390/cancers16112053","url":"https://www.mdpi.com/2072-6694/16/11/2053","evidence_status":"needs claim-level validation"},{"short_citation":"Smaadahl et al., 2024","citation":"Smaadahl N, Hool S, Reinhardt P, et al. Treatment and related morbidity of nasal cavity and paranasal sinus cancers. Frontiers in Oncology. 2024","doi":"10.3389/fonc.2024.1422892","url":"https://www.frontiersin.org/journals/oncology/articles/10.3389/fonc.2024.1422892/full","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Direct sex-specific benign sinonasal morphology remains uncertain.","mechanism":"Residual signal in benign mucosa may reflect unmeasured inflammatory/endotype context.","features":"Benign respiratory epithelium, glands, stroma, vessels.","confounders":"Subsite, inflammation, CRS endotype, treatment.","validation":"Test benign non-tumor, endotype-matched mucosa; interpret cautiously.","literature":[{"short_citation":"Fokkens et al., 2020","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The strongest clinical-context hypotheses are malignancy/subtype, occupational exposure, CRS phenotype, and procedure type.","The strongest morphology hypotheses are inflammatory cell composition and CRS remodeling, not generic sex-specific sinonasal anatomy.","The most important validation is matching by diagnosis, CRS endotype, tumor subtype/stage, subsite, exposure proxy, and procedure type."],"references":[{"n":1,"raw":"Binazzi A, di Marzio D, Mensi C, et al. Gender Differences in Sinonasal Cancer Incidence: Data from the Italian Registry. Cancers. 2024. DOI: 10.3390/cancers16112053. https://www.mdpi.com/2072-6694/16/11/2053","citation":"Binazzi A, di Marzio D, Mensi C, et al. Gender Differences in Sinonasal Cancer Incidence: Data from the Italian Registry. Cancers. 2024","year":"2024","doi":"10.3390/cancers16112053","url":"https://www.mdpi.com/2072-6694/16/11/2053"},{"n":2,"raw":"Smaadahl N, Hool S, Reinhardt P, et al. Treatment and related morbidity of nasal cavity and paranasal sinus cancers. Frontiers in Oncology. 2024. DOI: 10.3389/fonc.2024.1422892. https://www.frontiersin.org/journals/oncology/articles/10.3389/fonc.2024.1422892/full","citation":"Smaadahl N, Hool S, Reinhardt P, et al. Treatment and related morbidity of nasal cavity and paranasal sinus cancers. Frontiers in Oncology. 2024","year":"2024","doi":"10.3389/fonc.2024.1422892","url":"https://www.frontiersin.org/journals/oncology/articles/10.3389/fonc.2024.1422892/full"},{"n":3,"raw":"Chiu RG, et al. Biological Sex and Chronic Rhinosinusitis Diagnosis, Phenotype, and Inflammatory Profile. 2025. https://pmc.ncbi.nlm.nih.gov/articles/PMC12550736/","citation":"Chiu RG, et al. Biological Sex and Chronic Rhinosinusitis Diagnosis, Phenotype, and Inflammatory Profile. 2025","year":"2025","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12550736/"},{"n":4,"raw":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020. PMID: 32077450. DOI: 10.4193/Rhin20.600. https://pubmed.ncbi.nlm.nih.gov/32077450/","citation":"Fokkens WJ, Lund VJ, Hopkins C, et al. European Position Paper on Rhinosinusitis and Nasal Polyps 2020. Rhinology. 2020","year":"2020","pmid":"32077450","doi":"10.4193/Rhin20.600","url":"https://pubmed.ncbi.nlm.nih.gov/32077450/"}],"filename":"sinus_sinonasal_tract__sex.yaml"},{"combo":"skin__race_self_reported_ancestry","organ_slug":"skin","organ":"Skin","demographic":"race_self_reported_ancestry","demographic_label":"Race / Self-Reported Ancestry","summary":"Skin race/self-reported ancestry signal is a high-priority residual candidate, but it should be framed as pigmentation/phototype, anatomic site, exposure, diagnosis mix, and care-context signal rather than intrinsic race biology. H&E-visible carriers include basal/suprabasal melanin, pigment incontinence, melanophages, solar elastosis, and skin-of-color dermatopathology reaction patterns.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Dermatopathology diagnosis mix can differ by skin phototype and care/access patterns.","mechanism":"Pigmentation affects presentation and diagnosis of inflammatory, pigmentary, and UV-related dermatoses.","features":"Diagnosis labels, inflammatory reaction pattern, pigmentary disorders, actinic damage, biopsy site.","confounders":"Diagnosis, anatomic site, UV exposure, institution, stain/scanner.","validation":"Match diagnosis and site; test whether residual signal remains in normal/benign background epidermis.","literature":[{"short_citation":"Williams et al., 2023","citation":"Williams KA, Wondimu B, Ajayi AM, Sokumbi O. Skin of color in dermatopathology: does color matter? Human Pathology. 2023","pmid":"37146946","doi":"10.1016/j.humpath.2023.04.012","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"UV-related disease and photodamage may confound race/phototype signal.","mechanism":"Phototype and sun exposure influence actinic lesions and solar elastosis burden.","features":"Actinic keratosis/SCC/BCC, solar elastosis, dermal collagen/elastin.","confounders":"Age, sun-exposed site, diagnosis, geography, care access.","validation":"Match sun-exposed site and keratinocytic lesion diagnosis.","literature":[{"short_citation":"Williams et al., 2023","citation":"Williams KA, Wondimu B, Ajayi AM, Sokumbi O. Skin of color in dermatopathology: does color matter? Human Pathology. 2023","pmid":"37146946","doi":"10.1016/j.humpath.2023.04.012","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Pigmentary and interface-dermatitis diagnoses may be unevenly represented.","mechanism":"Post-inflammatory hyperpigmentation, lichen planus-like reactions, and pigmentary disorders can increase pigment/incontinence patterns.","features":"Lichenoid/interface dermatitis, pigment incontinence, melanophages, basal vacuolar change.","confounders":"Diagnosis, inflammation, site, treatment, prior injury.","validation":"Exclude pigmentary/interface diagnoses and retest race/ancestry signal.","literature":[{"short_citation":"Williams et al., 2023","citation":"Williams KA, Wondimu B, Ajayi AM, Sokumbi O. Skin of color in dermatopathology: does color matter? Human Pathology. 2023","pmid":"37146946","doi":"10.1016/j.humpath.2023.04.012","evidence_status":"needs claim-level validation"},{"short_citation":"Moreiras et al., 2021","citation":"Moreiras H, Seabra MC, Barral DC. Melanin Transfer in the Epidermis: The Pursuit of Skin Pigmentation Control Mechanisms. International Journal of Molecular Sciences. 2021","doi":"10.3390/ijms22094466","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Anatomic site and biopsy threshold may mediate signal.","mechanism":"Skin-of-color clinical workflows and lesion visibility can alter biopsy site, lesion duration, and specimen type.","features":"Acral sites, scalp/hair-bearing skin, keloid/scar, inflammatory vs neoplastic lesions.","confounders":"Site, diagnosis, institution/access, procedure type, age.","validation":"Match anatomic site and diagnosis; audit access/workflow proxies where possible.","literature":[{"short_citation":"Williams et al., 2023","citation":"Williams KA, Wondimu B, Ajayi AM, Sokumbi O. Skin of color in dermatopathology: does color matter? Human Pathology. 2023","pmid":"37146946","doi":"10.1016/j.humpath.2023.04.012","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Epidermal pigmentation can directly encode phototype.","mechanism":"Melanin amount, melanosome transfer, and keratinocyte handling shape visible pigment distribution.","features":"Basal melanin, suprabasal melanin, pigment caps, melanocyte/keratinocyte pigment pattern.","confounders":"Stain intensity, site, inflammation, sun exposure, lesion type.","validation":"Inspect attention along basal epidermis after diagnosis/site matching.","literature":[{"short_citation":"Moreiras et al., 2021","citation":"Moreiras H, Seabra MC, Barral DC. Melanin Transfer in the Epidermis: The Pursuit of Skin Pigmentation Control Mechanisms. International Journal of Molecular Sciences. 2021","doi":"10.3390/ijms22094466","evidence_status":"needs claim-level validation"},{"short_citation":"Dodia et al., 2023","citation":"Dodia P, Bhutta BS, Leslie SW, et al. Dermatopathology Epidermis Histology. StatPearls. 2023. NCBI Bookshelf","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Dermal pigment and interface/inflammatory changes may encode context.","mechanism":"Pigment incontinence and melanophages arise in pigmentary/interface disorders and post-inflammatory states.","features":"Melanophages, pigment incontinence, lichenoid/interface dermatitis.","confounders":"Diagnosis, inflammation, prior injury, treatment.","validation":"Test residual race signal after excluding pigmentary/interface diagnoses.","literature":[{"short_citation":"Williams et al., 2023","citation":"Williams KA, Wondimu B, Ajayi AM, Sokumbi O. Skin of color in dermatopathology: does color matter? Human Pathology. 2023","pmid":"37146946","doi":"10.1016/j.humpath.2023.04.012","evidence_status":"needs claim-level validation"},{"short_citation":"Moreiras et al., 2021","citation":"Moreiras H, Seabra MC, Barral DC. Melanin Transfer in the Epidermis: The Pursuit of Skin Pigmentation Control Mechanisms. International Journal of Molecular Sciences. 2021","doi":"10.3390/ijms22094466","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Race/self-reported ancestry should be interpreted as a proxy label, not direct biology.","mechanism":"Self-reported race can proxy pigmentation, exposure, geography, access, and workflow.","features":"Pigment, site, diagnosis mix, photodamage, biopsy thresholds.","confounders":"Institution, scanner/stain, access, site, diagnosis.","validation":"Report residual signal as pigmentation/context unless ancestry-specific mechanism is directly supported.","literature":[{"short_citation":"Williams et al., 2023","citation":"Williams KA, Wondimu B, Ajayi AM, Sokumbi O. Skin of color in dermatopathology: does color matter? Human Pathology. 2023","pmid":"37146946","doi":"10.1016/j.humpath.2023.04.012","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Dermal photodamage and elastosis may encode phototype plus exposure.","mechanism":"UV susceptibility and exposure patterns affect collagen/elastin degeneration in sun-exposed skin.","features":"Solar elastosis, dermal collagen basophilia, epidermal atrophy, actinic keratosis.","confounders":"Age, sun-exposed site, lesion type, geography, occupational exposure.","validation":"Analyze sun-exposed and non-sun-exposed sites separately.","literature":[{"short_citation":"Williams et al., 2023","citation":"Williams KA, Wondimu B, Ajayi AM, Sokumbi O. Skin of color in dermatopathology: does color matter? Human Pathology. 2023","pmid":"37146946","doi":"10.1016/j.humpath.2023.04.012","evidence_status":"needs claim-level validation"},{"short_citation":"Dodia et al., 2023","citation":"Dodia P, Bhutta BS, Leslie SW, et al. Dermatopathology Epidermis Histology. StatPearls. 2023. NCBI Bookshelf","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["Best review target: basal/suprabasal epidermal pigment and dermal melanophages after site/diagnosis matching.","Main shortcut risk: diagnosis mix, UV exposure, anatomic site, and access/workflow.","Use cautious language: pigmentation/phototype signal, not intrinsic race biology."],"references":[{"n":1,"raw":"Williams KA, Wondimu B, Ajayi AM, Sokumbi O. Skin of color in dermatopathology: does color matter? Human Pathology. 2023. PMID: 37146946. DOI: 10.1016/j.humpath.2023.04.012.","citation":"Williams KA, Wondimu B, Ajayi AM, Sokumbi O. Skin of color in dermatopathology: does color matter? Human Pathology. 2023","year":"2023","pmid":"37146946","doi":"10.1016/j.humpath.2023.04.012"},{"n":2,"raw":"Moreiras H, Seabra MC, Barral DC. Melanin Transfer in the Epidermis: The Pursuit of Skin Pigmentation Control Mechanisms. International Journal of Molecular Sciences. 2021. DOI: 10.3390/ijms22094466.","citation":"Moreiras H, Seabra MC, Barral DC. Melanin Transfer in the Epidermis: The Pursuit of Skin Pigmentation Control Mechanisms. International Journal of Molecular Sciences. 2021","year":"2021","doi":"10.3390/ijms22094466"},{"n":3,"raw":"Dodia P, Bhutta BS, Leslie SW, et al. Dermatopathology Epidermis Histology. StatPearls. 2023. NCBI Bookshelf.","citation":"Dodia P, Bhutta BS, Leslie SW, et al. Dermatopathology Epidermis Histology. StatPearls. 2023. NCBI Bookshelf","year":"2023"}],"filename":"skin__race_self_reported_ancestry.yaml"},{"combo":"skin__sex","organ_slug":"skin","organ":"Skin","demographic":"sex","demographic_label":"Sex","summary":"Skin sex signal is context-sensitive but remains high priority. Literature supports sex-linked skin thickness, collagen, elastic-fiber proportions, topography, scar/wound ECM, dermal white adipose context, and hormone-sensitive adnexal structures. Site, age, scar/wound status, cosmetic/dermatology utilization, and diagnosis mix are major confounders.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Sex differences in skin specimen site and dermatology utilization may create shortcuts.","mechanism":"Hair-bearing/cosmetic sites, melanoma/non-melanoma cancer patterns, and scar/procedure contexts can differ by sex.","features":"Anatomic site, lesion type, scar, hair follicles, sebaceous units, tumor subtype.","confounders":"Site, diagnosis, procedure, age, UV exposure.","validation":"Match anatomic site and diagnosis; audit scar/wound and cosmetic-procedure contexts.","literature":[{"short_citation":"Dąbrowska et al., 2018","citation":"Dąbrowska M, Mielcarek A, Nowak I. Evaluation of sex-related changes in skin topography and structure using innovative skin testing equipment. Skin Research and Technology. 2018","pmid":"29707820","doi":"10.1111/srt.12473","evidence_status":"needs claim-level validation"},{"short_citation":"Gawronska-Kozak et al., 2023","citation":"Gawronska-Kozak B, Kopcewicz M, Machcinska-Zielinska S, et al. Gender Differences in Post-Operative Human Skin. Biomedicines. 2023","pmid":"37893135","pmcid":"PMC10604277","doi":"10.3390/biomedicines11102653","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Scar/wound specimens can encode sex through post-operative ECM differences.","mechanism":"Wound healing and scar ECM composition may differ by sex.","features":"Scar collagen, alpha-SMA-rich stroma, elastin, dermal adipose, inflammation.","confounders":"Scar diagnosis, procedure timing, site, age.","validation":"Exclude scar/wound specimens or stratify them separately.","literature":[{"short_citation":"Gawronska-Kozak et al., 2023","citation":"Gawronska-Kozak B, Kopcewicz M, Machcinska-Zielinska S, et al. Gender Differences in Post-Operative Human Skin. Biomedicines. 2023","pmid":"37893135","pmcid":"PMC10604277","doi":"10.3390/biomedicines11102653","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Skin cancer subtype and site distributions may differ by sex.","mechanism":"UV exposure, behavior, hair-bearing sites, and screening can alter melanoma and keratinocytic lesion mix.","features":"Melanoma, SCC/BCC, actinic keratosis, solar elastosis, anatomic site.","confounders":"Diagnosis, sun-exposed site, age, geography, procedure type.","validation":"Match diagnosis and sun-exposed site before interpreting residual sex morphology.","literature":[{"short_citation":"Dąbrowska et al., 2018","citation":"Dąbrowska M, Mielcarek A, Nowak I. Evaluation of sex-related changes in skin topography and structure using innovative skin testing equipment. Skin Research and Technology. 2018","pmid":"29707820","doi":"10.1111/srt.12473","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Cosmetic/procedural and inflammatory biopsy patterns may mediate sex signal.","mechanism":"Dermatology utilization and procedure patterns can alter scars, nevi, alopecia, and inflammatory lesion mix.","features":"Scar, nevus, alopecia/scalp, inflammatory dermatoses, biopsy size/depth.","confounders":"Diagnosis, site, procedure, institution, age.","validation":"Audit diagnosis/site/procedure distributions within S3 clusters.","literature":[{"short_citation":"Dąbrowska et al., 2018","citation":"Dąbrowska M, Mielcarek A, Nowak I. Evaluation of sex-related changes in skin topography and structure using innovative skin testing equipment. Skin Research and Technology. 2018","pmid":"29707820","doi":"10.1111/srt.12473","evidence_status":"needs claim-level validation"},{"short_citation":"Gawronska-Kozak et al., 2023","citation":"Gawronska-Kozak B, Kopcewicz M, Machcinska-Zielinska S, et al. Gender Differences in Post-Operative Human Skin. Biomedicines. 2023","pmid":"37893135","pmcid":"PMC10604277","doi":"10.3390/biomedicines11102653","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Dermal thickness and collagen amount differ by sex.","mechanism":"Classic tissue studies report sex and age effects on skin thickness/collagen.","features":"Dermal thickness, collagen density, collagen bundle pattern.","confounders":"Age, body site, biopsy depth, scar, UV damage.","validation":"Quantify dermal thickness/collagen in site- and age-matched benign skin.","literature":[{"short_citation":"Shuster et al., 1975","citation":"Shuster S, Black MM, McVitie E. The influence of age and sex on skin thickness, skin collagen and density. British Journal of Dermatology. 1975","pmid":"1220811","doi":"10.1111/j.1365-2133.1975.tb05113.x","evidence_status":"needs claim-level validation"},{"short_citation":"Vitellaro-Zuccarello et al., 1994","citation":"Vitellaro-Zuccarello L, Cappelletti S, Dal Pozzo Rossi V, Sari-Gorla M. Stereological analysis of collagen and elastic fibers in the normal human dermis. Anatomical Record. 1994","pmid":"8154602","doi":"10.1002/ar.1092380202","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Collagen and elastic-fiber proportions vary with sex and body region.","mechanism":"Stereologic dermal fiber differences can create texture/architecture signal.","features":"Collagen/elastic fibers, papillary vs reticular dermis.","confounders":"Body region, age, solar elastosis, scar.","validation":"Review attention maps for dermal fiber-rich compartments.","literature":[{"short_citation":"Vitellaro-Zuccarello et al., 1994","citation":"Vitellaro-Zuccarello L, Cappelletti S, Dal Pozzo Rossi V, Sari-Gorla M. Stereological analysis of collagen and elastic fibers in the normal human dermis. Anatomical Record. 1994","pmid":"8154602","doi":"10.1002/ar.1092380202","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Post-operative skin shows sex-linked ECM and adipose-associated differences.","mechanism":"Sex-linked scar ECM, collagen I/III/VI, elastin, alpha-SMA, and adipogenic markers may alter H&E texture.","features":"Scar collagen, dWAT/adipose cones, stromal cells, elastin.","confounders":"Scar status, anatomic site, prior procedure.","validation":"Separate scar/wound from non-scar skin before interpreting residual signal.","literature":[{"short_citation":"Gawronska-Kozak et al., 2023","citation":"Gawronska-Kozak B, Kopcewicz M, Machcinska-Zielinska S, et al. Gender Differences in Post-Operative Human Skin. Biomedicines. 2023","pmid":"37893135","pmcid":"PMC10604277","doi":"10.3390/biomedicines11102653","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Adnexal density and hair-bearing site composition may be an indirect carrier.","mechanism":"Site imbalance can change follicles, sebaceous glands, sweat glands, and dermal thickness.","features":"Hair follicles, sebaceous units, eccrine glands, dermal/adipose depth.","confounders":"Anatomic site, sex-linked site sampling, diagnosis, biopsy depth.","validation":"Require site-matched benign skin review before calling direct sex morphology.","literature":[{"short_citation":"Dąbrowska et al., 2018","citation":"Dąbrowska M, Mielcarek A, Nowak I. Evaluation of sex-related changes in skin topography and structure using innovative skin testing equipment. Skin Research and Technology. 2018","pmid":"29707820","doi":"10.1111/srt.12473","evidence_status":"needs claim-level validation"},{"short_citation":"Shuster et al., 1975","citation":"Shuster S, Black MM, McVitie E. The influence of age and sex on skin thickness, skin collagen and density. British Journal of Dermatology. 1975","pmid":"1220811","doi":"10.1111/j.1365-2133.1975.tb05113.x","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["Best review target: dermal thickness/collagen, elastic fibers, adnexa, scar/wound ECM, and site distribution.","Main shortcut risk: anatomic site, scar/wound status, age, and diagnosis.","Strong morphology evidence exists, but site and age matching are essential."],"references":[{"n":1,"raw":"Shuster S, Black MM, McVitie E. The influence of age and sex on skin thickness, skin collagen and density. British Journal of Dermatology. 1975. PMID: 1220811. DOI: 10.1111/j.1365-2133.1975.tb05113.x.","citation":"Shuster S, Black MM, McVitie E. The influence of age and sex on skin thickness, skin collagen and density. British Journal of Dermatology. 1975","year":"1975","pmid":"1220811","doi":"10.1111/j.1365-2133.1975.tb05113.x"},{"n":2,"raw":"Vitellaro-Zuccarello L, Cappelletti S, Dal Pozzo Rossi V, Sari-Gorla M. Stereological analysis of collagen and elastic fibers in the normal human dermis. Anatomical Record. 1994. PMID: 8154602. DOI: 10.1002/ar.1092380202.","citation":"Vitellaro-Zuccarello L, Cappelletti S, Dal Pozzo Rossi V, Sari-Gorla M. Stereological analysis of collagen and elastic fibers in the normal human dermis. Anatomical Record. 1994","year":"1994","pmid":"8154602","doi":"10.1002/ar.1092380202"},{"n":3,"raw":"Dąbrowska M, Mielcarek A, Nowak I. Evaluation of sex-related changes in skin topography and structure using innovative skin testing equipment. Skin Research and Technology. 2018. PMID: 29707820. DOI: 10.1111/srt.12473.","citation":"Dąbrowska M, Mielcarek A, Nowak I. Evaluation of sex-related changes in skin topography and structure using innovative skin testing equipment. Skin Research and Technology. 2018","year":"2018","pmid":"29707820","doi":"10.1111/srt.12473"},{"n":4,"raw":"Gawronska-Kozak B, Kopcewicz M, Machcinska-Zielinska S, et al. Gender Differences in Post-Operative Human Skin. Biomedicines. 2023. PMID: 37893135. PMCID: PMC10604277. DOI: 10.3390/biomedicines11102653.","citation":"Gawronska-Kozak B, Kopcewicz M, Machcinska-Zielinska S, et al. Gender Differences in Post-Operative Human Skin. Biomedicines. 2023","year":"2023","pmid":"37893135","pmcid":"PMC10604277","doi":"10.3390/biomedicines11102653"}],"filename":"skin__sex.yaml"},{"combo":"small_bowel__race_self_reported_ancestry","organ_slug":"small_bowel","organ":"Small Bowel","demographic":"race_self_reported_ancestry","demographic_label":"Race / Self-Reported Ancestry","summary":"Small-bowel race or ancestry signal should be treated as a clinical-context and ascertainment hypothesis, not as intrinsic racial morphology. The strongest literature-supported carriers are celiac-workup patterns, ethnic variation in villous atrophy prevalence among biopsied patients, IBD/infectious differential diagnosis, diet/geography, and access-to-endoscopy differences. Any residual signal after diagnosis matching should be reviewed as a mixture of ancestry, environment, structural access, and biopsy indication.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Race/ethnicity may correlate with duodenal biopsy ascertainment for celiac disease.","mechanism":"Referral, symptom interpretation, access, and clinician testing thresholds can affect who receives duodenal biopsies.","features":"Number of duodenal fragments, normal biopsies, mild IEL increase, celiac-compatible injury.","confounders":"Indication, endoscopy setting, insurance/access proxies, age, sex.","validation":"Compare race signal within indication-matched duodenal biopsies and normal-biopsy subsets.","literature":[{"short_citation":"Lebwohl et al., 2012","citation":"Lebwohl B, Tennyson CA, Holub JL, et al. Sex and racial disparities in duodenal biopsy to evaluate for celiac disease. Gastrointestinal Endoscopy. 2012","pmid":"22732871","url":"https://pubmed.ncbi.nlm.nih.gov/22732871/","evidence_status":"needs claim-level validation"},{"short_citation":"Krigel et al., 2016","citation":"Krigel A, Turner KO, Makharia GK, et al. Ethnic Variations in Duodenal Villous Atrophy Consistent with Celiac Disease in the United States. Clinical Gastroenterology and Hepatology. 2016","pmcid":"PMC4955830","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4955830/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Villous atrophy prevalence differs across ethnicity groups among biopsied patients.","mechanism":"Celiac-associated HLA background, diet, geography, immigration, and ascertainment can alter prevalence of villous atrophy.","features":"Villous blunting, crypt hyperplasia, intraepithelial lymphocytes, Marsh-like injury.","confounders":"H. pylori, age, sex, indication, ethnicity assignment method, diet/geography.","validation":"Match celiac diagnosis and villous atrophy grade; test residual race signal within celiac-positive and celiac-negative groups.","literature":[{"short_citation":"Krigel et al., 2016","citation":"Krigel A, Turner KO, Makharia GK, et al. Ethnic Variations in Duodenal Villous Atrophy Consistent with Celiac Disease in the United States. Clinical Gastroenterology and Hepatology. 2016","pmcid":"PMC4955830","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4955830/","evidence_status":"source metadata incomplete"},{"short_citation":"Villanacci et al., 2020","citation":"Villanacci V, Ceppa P, Tavani E, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","pmcid":"PMC7931573","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7931573/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"IBD, infection, and medication-injury mix may differ by race/ethnicity and care pathway.","mechanism":"Access, geography, microbiome/exposure, and disease phenotype may change chronic active enteritis or infectious patterns.","features":"Chronic active enteritis, granulomas, ulcers, parasites, eosinophils, ischemic or medication injury.","confounders":"Diagnosis, Crohn disease, infection, NSAID/drug injury, anatomic site.","validation":"Stratify by diagnosis category: celiac, Crohn, infection, ischemic/drug injury, normal.","literature":[{"short_citation":"Zheng et al., 2022","citation":"Zheng H, Zhang W, Wu Z, et al. The impact of aging on intestinal mucosal immune function and clinical applications. Frontiers in Immunology. 2022","pmid":"36524122","pmcid":"PMC9745321","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9745321/","evidence_status":"needs claim-level validation"},{"short_citation":"Villanacci et al., 2020","citation":"Villanacci V, Ceppa P, Tavani E, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","pmcid":"PMC7931573","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7931573/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Normal or nonspecific biopsies may encode workflow rather than biology.","mechanism":"Race-associated health-care access and endoscopy thresholds can alter the fraction of normal/nonspecific small-bowel biopsies.","features":"Normal villi, mild chronic inflammation, nonspecific IELs, tissue quantity/orientation.","confounders":"Procedure indication, site, pathologist reporting style, institution.","validation":"Audit normal-biopsy rate and report text categories by demographic group.","literature":[{"short_citation":"Lebwohl et al., 2012","citation":"Lebwohl B, Tennyson CA, Holub JL, et al. Sex and racial disparities in duodenal biopsy to evaluate for celiac disease. Gastrointestinal Endoscopy. 2012","pmid":"22732871","url":"https://pubmed.ncbi.nlm.nih.gov/22732871/","evidence_status":"needs claim-level validation"},{"short_citation":"Krigel et al., 2016","citation":"Krigel A, Turner KO, Makharia GK, et al. Ethnic Variations in Duodenal Villous Atrophy Consistent with Celiac Disease in the United States. Clinical Gastroenterology and Hepatology. 2016","pmcid":"PMC4955830","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4955830/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Villous atrophy pattern may mediate much of the apparent race/ancestry signal.","mechanism":"Ethnic variation in celiac-compatible villous atrophy changes overt mucosal architecture.","features":"Villus height, crypt depth, villus:crypt ratio, Marsh pattern, IEL density.","confounders":"Celiac diagnosis, gluten exposure, HLA/geography, H. pylori, age/sex.","validation":"Morphometrically compare villous architecture after celiac-grade matching.","literature":[{"short_citation":"Krigel et al., 2016","citation":"Krigel A, Turner KO, Makharia GK, et al. Ethnic Variations in Duodenal Villous Atrophy Consistent with Celiac Disease in the United States. Clinical Gastroenterology and Hepatology. 2016","pmcid":"PMC4955830","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4955830/","evidence_status":"source metadata incomplete"},{"short_citation":"Villanacci et al., 2020","citation":"Villanacci V, Ceppa P, Tavani E, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","pmcid":"PMC7931573","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7931573/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"IEL and lamina propria immune patterns may reflect diagnostic mix.","mechanism":"Celiac disease, infection, H. pylori-associated duodenal changes, and autoimmune context can produce lymphocyte-rich mucosa.","features":"IELs, plasma cells, lymphoid aggregates, eosinophils, active inflammation.","confounders":"Celiac, H. pylori, infection, medication, IBD, immune disease.","validation":"Cell-count review in diagnosis-matched biopsies; separate IEL-predominant from active-enteritis patterns.","literature":[{"short_citation":"Villanacci et al., 2020","citation":"Villanacci V, Ceppa P, Tavani E, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","pmcid":"PMC7931573","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7931573/","evidence_status":"source metadata incomplete"},{"short_citation":"Zheng et al., 2022","citation":"Zheng H, Zhang W, Wu Z, et al. The impact of aging on intestinal mucosal immune function and clinical applications. Frontiers in Immunology. 2022","pmid":"36524122","pmcid":"PMC9745321","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9745321/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Crohn/infectious patterns can produce localized morphology unrelated to intrinsic ancestry.","mechanism":"Granulomatous or ulcerative injury may track geography, exposure, or care pathway.","features":"Granulomas, fissuring ulcers, chronic active inflammation, parasites, eosinophils.","confounders":"Crohn diagnosis, infection testing, travel/geography, medication, site.","validation":"Exclude Crohn/infection or match these categories before interpreting residual signal.","literature":[{"short_citation":"Zheng et al., 2022","citation":"Zheng H, Zhang W, Wu Z, et al. The impact of aging on intestinal mucosal immune function and clinical applications. Frontiers in Immunology. 2022","pmid":"36524122","pmcid":"PMC9745321","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9745321/","evidence_status":"needs claim-level validation"},{"short_citation":"Villanacci et al., 2020","citation":"Villanacci V, Ceppa P, Tavani E, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","pmcid":"PMC7931573","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7931573/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Direct benign race-specific small-bowel morphology is not established.","mechanism":"Any persistent signal in normal mucosa may reflect unmeasured diet, microbiome, geography, sectioning, or reporting workflow.","features":"Normal villous architecture, subtle IELs, goblet/Paneth cell distribution, orientation.","confounders":"Diet/geography, endoscopy indication, lab/site, orientation, tissue quality.","validation":"Treat residual normal-mucosa signal as exploratory; require manual review and external validation.","literature":[{"short_citation":"Lebwohl et al., 2012","citation":"Lebwohl B, Tennyson CA, Holub JL, et al. Sex and racial disparities in duodenal biopsy to evaluate for celiac disease. Gastrointestinal Endoscopy. 2012","pmid":"22732871","url":"https://pubmed.ncbi.nlm.nih.gov/22732871/","evidence_status":"needs claim-level validation"},{"short_citation":"Krigel et al., 2016","citation":"Krigel A, Turner KO, Makharia GK, et al. Ethnic Variations in Duodenal Villous Atrophy Consistent with Celiac Disease in the United States. Clinical Gastroenterology and Hepatology. 2016","pmcid":"PMC4955830","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4955830/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["This combo should be reviewed primarily as a workflow/disease-prevalence hypothesis.","The most visible H&E carrier is villous atrophy/IEL/crypt hyperplasia, especially celiac-compatible injury.","The main guardrail is to avoid interpreting socially defined race as intrinsic small-bowel morphology."],"references":[{"n":1,"raw":"Lebwohl B, Tennyson CA, Holub JL, et al. Sex and racial disparities in duodenal biopsy to evaluate for celiac disease. Gastrointestinal Endoscopy. 2012. PMID: 22732871. https://pubmed.ncbi.nlm.nih.gov/22732871/","citation":"Lebwohl B, Tennyson CA, Holub JL, et al. Sex and racial disparities in duodenal biopsy to evaluate for celiac disease. Gastrointestinal Endoscopy. 2012","year":"2012","pmid":"22732871","url":"https://pubmed.ncbi.nlm.nih.gov/22732871/"},{"n":2,"raw":"Krigel A, Turner KO, Makharia GK, et al. Ethnic Variations in Duodenal Villous Atrophy Consistent with Celiac Disease in the United States. Clinical Gastroenterology and Hepatology. 2016. PMCID: PMC4955830. https://pmc.ncbi.nlm.nih.gov/articles/PMC4955830/","citation":"Krigel A, Turner KO, Makharia GK, et al. Ethnic Variations in Duodenal Villous Atrophy Consistent with Celiac Disease in the United States. Clinical Gastroenterology and Hepatology. 2016","year":"2016","pmcid":"PMC4955830","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4955830/"},{"n":3,"raw":"Villanacci V, Ceppa P, Tavani E, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020. PMCID: PMC7931573. https://pmc.ncbi.nlm.nih.gov/articles/PMC7931573/","citation":"Villanacci V, Ceppa P, Tavani E, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","year":"2020","pmcid":"PMC7931573","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7931573/"},{"n":4,"raw":"Zheng H, Zhang W, Wu Z, et al. The impact of aging on intestinal mucosal immune function and clinical applications. Frontiers in Immunology. 2022. PMID: 36524122; PMCID: PMC9745321. https://pmc.ncbi.nlm.nih.gov/articles/PMC9745321/","citation":"Zheng H, Zhang W, Wu Z, et al. The impact of aging on intestinal mucosal immune function and clinical applications. Frontiers in Immunology. 2022","year":"2022","pmid":"36524122","pmcid":"PMC9745321","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9745321/"}],"filename":"small_bowel__race_self_reported_ancestry.yaml"},{"combo":"small_bowel__sex","organ_slug":"small_bowel","organ":"Small Bowel","demographic":"sex","demographic_label":"Sex","summary":"Small bowel sex signal is a residual candidate likely mediated by celiac disease, autoimmune/inflammatory workup, IBD phenotype, healthcare utilization, and biopsy indication. Direct sex-specific small bowel H&E morphology outside diagnosis is not well established.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Women are more often diagnosed with celiac disease in many cohorts.","mechanism":"Celiac workup and diagnosis can produce sex-skewed biopsy mix.","features":"Villous atrophy, intraepithelial lymphocytes, crypt hyperplasia, chronic inflammation.","confounders":"Celiac diagnosis, serology, biopsy indication, age, duodenum vs small bowel site.","validation":"Match or exclude celiac disease and villous atrophy; retest residual sex signal.","literature":[{"short_citation":"Villanacci et al., 2020","citation":"Villanacci V, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","pmcid":"PMC7931573","evidence_status":"source metadata incomplete"},{"short_citation":"Vivas et al., 2015","citation":"Vivas S, et al. Age-related differences in celiac disease. 2015","pmcid":"PMC4635160","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Sex differences in IBD phenotype or healthcare utilization may alter small bowel case mix.","mechanism":"Workup for Crohn disease, chronic enteritis, anemia, malabsorption, or autoimmune disease can differ by sex.","features":"Chronic active enteritis, granulomas, ulcers, stricturing/ischemic changes.","confounders":"Diagnosis, procedure, site, inflammation severity, medication.","validation":"Stratify by Crohn/IBD, celiac, ischemia, neoplasm, and nonspecific biopsy categories.","literature":[{"short_citation":"Vivas et al., 2015","citation":"Vivas S, et al. Age-related differences in celiac disease. 2015","pmcid":"PMC4635160","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Anemia and malabsorption workups may create sex-associated duodenal biopsy patterns.","mechanism":"Iron deficiency and autoimmune screening pathways can affect who receives small-bowel biopsies.","features":"Normal biopsies, mild IEL increase, villous blunting, chronic inflammation.","confounders":"Indication, anemia, celiac serology, age, menstrual status if available.","validation":"Match biopsy indication and celiac status before reviewing residual sex signal.","literature":[{"short_citation":"Villanacci et al., 2020","citation":"Villanacci V, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","pmcid":"PMC7931573","evidence_status":"source metadata incomplete"},{"short_citation":"Vivas et al., 2015","citation":"Vivas S, et al. Age-related differences in celiac disease. 2015","pmcid":"PMC4635160","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Neoplasm, ischemia, and obstruction categories may differ by age/sex context.","mechanism":"Small-bowel resections and biopsies include heterogeneous entities whose distribution can encode sex indirectly.","features":"Tumor, ischemic injury, ulceration, fibrosis, metastatic disease.","confounders":"Diagnosis, procedure, site, age, treatment.","validation":"Group cases into biopsy vs resection and diagnosis families before testing.","literature":[{"short_citation":"Vivas et al., 2015","citation":"Vivas S, et al. Age-related differences in celiac disease. 2015","pmcid":"PMC4635160","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Celiac-type injury is the strongest H&E-visible sex carrier.","mechanism":"Female enrichment for celiac disease can produce villous/crypt/IEL patterns that encode sex indirectly.","features":"Villous height, crypt hyperplasia, IEL density, lamina propria inflammation.","confounders":"Celiac diagnosis, duodenal site, age, biopsy orientation.","validation":"Compare sex signal within non-celiac biopsies and within matched Marsh/injury grades.","literature":[{"short_citation":"Villanacci et al., 2020","citation":"Villanacci V, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","pmcid":"PMC7931573","evidence_status":"source metadata incomplete"},{"short_citation":"Vivas et al., 2015","citation":"Vivas S, et al. Age-related differences in celiac disease. 2015","pmcid":"PMC4635160","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Diffuse immune differences are plausible but weakly supported.","mechanism":"Sex-related immune regulation may influence autoimmune enteropathy/celiac/inflammatory patterns.","features":"IELs, lymphoid aggregates, plasma cells, eosinophils.","confounders":"Diagnosis, autoimmune disease, infection, medication.","validation":"Treat as indirect unless residual signal persists after diagnosis/inflammation matching.","literature":[{"short_citation":"Vivas et al., 2015","citation":"Vivas S, et al. Age-related differences in celiac disease. 2015","pmcid":"PMC4635160","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Chronic active enteritis and granulomatous patterns may reflect IBD mix.","mechanism":"Crohn disease and infection produce visible ulceration, granulomas, and chronic architectural distortion.","features":"Granulomas, ulcers, pyloric metaplasia, crypt distortion, active inflammation.","confounders":"IBD diagnosis, medication, infection, site, age.","validation":"Exclude IBD/infection or match these categories before interpreting residual sex signal.","literature":[{"short_citation":"Villanacci et al., 2020","citation":"Villanacci V, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","pmcid":"PMC7931573","evidence_status":"source metadata incomplete"},{"short_citation":"Vivas et al., 2015","citation":"Vivas S, et al. Age-related differences in celiac disease. 2015","pmcid":"PMC4635160","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Direct normal small-bowel sex morphology is not established.","mechanism":"A signal in normal biopsies may reflect orientation, tissue quantity, indication, or reporting workflow.","features":"Normal villi, goblet/Paneth cells, mild IELs, lamina propria cellularity.","confounders":"Site, orientation, indication, institution, celiac serology.","validation":"Treat as exploratory until reviewer-added DOI-backed references support a direct mechanism.","literature":[{"short_citation":"Villanacci et al., 2020","citation":"Villanacci V, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","pmcid":"PMC7931573","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"}],"key_takeaways":["Best review target: celiac-type injury, villous atrophy, IELs, and crypt hyperplasia.","Main shortcut risk: celiac/IBD diagnosis and biopsy indication.","Direct intrinsic sex morphology evidence is limited; prioritize diagnosis-matched validation."],"references":[{"n":1,"raw":"Villanacci V, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020. PMCID: PMC7931573.","citation":"Villanacci V, et al. Celiac disease: histology-differential diagnosis-complications. A practical approach. Pathologica. 2020","year":"2020","pmcid":"PMC7931573"},{"n":2,"raw":"Vivas S, et al. Age-related differences in celiac disease. 2015. PMCID: PMC4635160.","citation":"Vivas S, et al. Age-related differences in celiac disease. 2015","year":"2015","pmcid":"PMC4635160"}],"filename":"small_bowel__sex.yaml"},{"combo":"thyroid__age","organ_slug":"thyroid","organ":"Thyroid","demographic":"age","demographic_label":"Age Group","summary":"Age signal in thyroid histology is likely strong and mixed. Clinical-context signal can arise from age-associated nodules, multinodular goiter, thyroiditis, incidental microcarcinoma, cancer workup, and procedure type. Direct morphology signal is plausible because aging thyroid follicles show size heterogeneity, irregular architecture, colloid/Tg changes, oncocytic change, empty/dilated follicles, lipofuscin, and fibrosis.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Older patients are enriched for nodular thyroid disease.","mechanism":"Thyroid nodules and multinodular goiter increase with age and can dominate surgical specimens.","features":"Nodular architecture, variable follicles, colloid nodules, fibrosis, thyroidectomy specimens.","confounders":"Nodule status, goiter diagnosis, procedure type, institution.","validation":"Match nodule/goiter status; test age prediction in non-nodular background tissue.","literature":[{"short_citation":"Lee et al., 2016","citation":"Lee J, Yi S, Kang YE, et al. Morphological and Functional Changes in the Thyroid Follicles of the Aged Murine and Humans. Journal of Pathology and Translational Medicine. 2016","pmid":"27737529","pmcid":"PMC5122729","doi":"10.4132/jptm.2016.07.19","url":"https://pubmed.ncbi.nlm.nih.gov/27737529/","evidence_status":"needs claim-level validation"},{"short_citation":"Faggiano et al., 2004","citation":"Faggiano A, Coulot J, Bellon N, et al. Age-dependent variation of follicular size and expression of iodine transporters in human thyroid tissue. Journal of Nuclear Medicine. 2004","pmid":"14960641","url":"https://pubmed.ncbi.nlm.nih.gov/14960641/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Older patients may be enriched for thyroid cancer workup.","mechanism":"Cancer detection and incidental carcinoma can alter diagnosis and specimen mix.","features":"Papillary carcinoma nuclear features, tumor foci, capsular/vascular invasion, tumor size/stage.","confounders":"Benign/malignant status, histologic subtype, tumor size/stage, procedure.","validation":"Match benign/malignant status and subtype/stage; test residual signal.","literature":[{"short_citation":"Meza & Chang, 2015","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Thyroiditis and endocrine workup may vary with age.","mechanism":"Autoimmune/chronic thyroiditis and endocrine evaluation can alter tissue mix.","features":"Lymphocytic thyroiditis, germinal centers, Hurthle cells, fibrosis.","confounders":"Thyroiditis status, autoimmune disease, sex, diagnosis.","validation":"Stratify by thyroiditis diagnosis and inflammation burden.","literature":[{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Procedure type may encode age.","mechanism":"Lobectomy/thyroidectomy for nodules/cancer versus other samples changes tissue context.","features":"Whole thyroid architecture, capsule, tumor margins, biopsy/surgical specimen type.","confounders":"Procedure type, diagnosis, institution, year.","validation":"Train/evaluate within procedure-type strata.","literature":[{"short_citation":"Meza & Chang, 2015","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Follicle size heterogeneity increases with age.","mechanism":"Aging thyroid shows variable follicular size and altered follicular organization.","features":"Follicle diameter variability, macro/microfollicles, irregular follicle shape.","confounders":"Nodules, goiter, fixation, subsite within gland.","validation":"Quantify follicle size distribution in benign non-nodular background.","literature":[{"short_citation":"Lee et al., 2016","citation":"Lee J, Yi S, Kang YE, et al. Morphological and Functional Changes in the Thyroid Follicles of the Aged Murine and Humans. Journal of Pathology and Translational Medicine. 2016","pmid":"27737529","pmcid":"PMC5122729","doi":"10.4132/jptm.2016.07.19","url":"https://pubmed.ncbi.nlm.nih.gov/27737529/","evidence_status":"needs claim-level validation"},{"short_citation":"Faggiano et al., 2004","citation":"Faggiano A, Coulot J, Bellon N, et al. Age-dependent variation of follicular size and expression of iodine transporters in human thyroid tissue. Journal of Nuclear Medicine. 2004","pmid":"14960641","url":"https://pubmed.ncbi.nlm.nih.gov/14960641/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Colloid/Tg appearance changes with age.","mechanism":"Aging follicles may show large/fragmented Tg globules and empty or dilated follicles.","features":"Colloid density, vacuolation, scalloping, empty follicles, Tg globules.","confounders":"Graves disease, fixation, nodular disease, thyroid function.","validation":"Compare colloid texture in diagnosis-matched benign follicles.","literature":[{"short_citation":"Lee et al., 2016","citation":"Lee J, Yi S, Kang YE, et al. Morphological and Functional Changes in the Thyroid Follicles of the Aged Murine and Humans. Journal of Pathology and Translational Medicine. 2016","pmid":"27737529","pmcid":"PMC5122729","doi":"10.4132/jptm.2016.07.19","url":"https://pubmed.ncbi.nlm.nih.gov/27737529/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Oncocytic/Hurthle-like follicular change may increase with age/context.","mechanism":"Mitochondrial and chronic injury changes can produce eosinophilic oncocytic cells.","features":"Hurthle cells, eosinophilic granular cytoplasm, follicular epithelial height.","confounders":"Thyroiditis, nodules, neoplasia, fixation.","validation":"Match thyroiditis/nodule status; quantify oncocytic cell prevalence.","literature":[{"short_citation":"Lee et al., 2016","citation":"Lee J, Yi S, Kang YE, et al. Morphological and Functional Changes in the Thyroid Follicles of the Aged Murine and Humans. Journal of Pathology and Translational Medicine. 2016","pmid":"27737529","pmcid":"PMC5122729","doi":"10.4132/jptm.2016.07.19","url":"https://pubmed.ncbi.nlm.nih.gov/27737529/","evidence_status":"needs claim-level validation"},{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Lipofuscin/pigment-like aging changes may encode age.","mechanism":"Accumulation of intracellular aging pigment has been described in thyroid follicular cells.","features":"Fine brown cytoplasmic pigment, follicular epithelial cells, autofluorescent/lipofuscin-like material if visible.","confounders":"Hemosiderin, artifact, species/source differences, stain quality.","validation":"Pathologist review of pigment candidates; validate with special stains only if feasible.","literature":[{"short_citation":"Ives et al., 1975","citation":"Ives PJ, Haensly WE, Maxwell PA, McArthur NH. A histochemical and ultrastructural study of lipofuscin accumulation in thyroid follicular cells of aging domestic cats. Mechanisms of Ageing and Development. 1975","pmid":"1228338","doi":"10.1016/0047-6374(75)90041-X","url":"https://pubmed.ncbi.nlm.nih.gov/1228338/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M5","section":"histomorphology","status":"active","hypothesis":"Stromal fibrosis and gland architectural remodeling may encode age.","mechanism":"Aging, nodules, and chronic injury can increase fibrosis and architectural heterogeneity.","features":"Fibrous septa, stromal fibrosis, capsular fibrosis, nodular remodeling.","confounders":"Nodular goiter, thyroiditis, tumor desmoplasia, prior procedure.","validation":"Quantify fibrosis after excluding tumors and matching nodular/thyroiditis status.","literature":[{"short_citation":"Lee et al., 2016","citation":"Lee J, Yi S, Kang YE, et al. Morphological and Functional Changes in the Thyroid Follicles of the Aged Murine and Humans. Journal of Pathology and Translational Medicine. 2016","pmid":"27737529","pmcid":"PMC5122729","doi":"10.4132/jptm.2016.07.19","url":"https://pubmed.ncbi.nlm.nih.gov/27737529/","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The strongest clinical-context hypotheses are nodular disease, cancer workup, thyroiditis/endocrine context, and procedure type.","The strongest morphology hypotheses are follicle size heterogeneity, colloid/Tg changes, oncocytic change, lipofuscin/pigment, and fibrosis.","The most important validation is matching by diagnosis, nodule status, thyroiditis, malignancy/subtype/stage, and procedure type."],"references":[{"n":1,"raw":"Lee J, Yi S, Kang YE, et al. Morphological and Functional Changes in the Thyroid Follicles of the Aged Murine and Humans. Journal of Pathology and Translational Medicine. 2016. PMID: 27737529. PMCID: PMC5122729. DOI: 10.4132/jptm.2016.07.19. https://pubmed.ncbi.nlm.nih.gov/27737529/","citation":"Lee J, Yi S, Kang YE, et al. Morphological and Functional Changes in the Thyroid Follicles of the Aged Murine and Humans. Journal of Pathology and Translational Medicine. 2016","year":"2016","pmid":"27737529","pmcid":"PMC5122729","doi":"10.4132/jptm.2016.07.19","url":"https://pubmed.ncbi.nlm.nih.gov/27737529/"},{"n":2,"raw":"Faggiano A, Coulot J, Bellon N, et al. Age-dependent variation of follicular size and expression of iodine transporters in human thyroid tissue. Journal of Nuclear Medicine. 2004. PMID: 14960641. https://pubmed.ncbi.nlm.nih.gov/14960641/","citation":"Faggiano A, Coulot J, Bellon N, et al. Age-dependent variation of follicular size and expression of iodine transporters in human thyroid tissue. Journal of Nuclear Medicine. 2004","year":"2004","pmid":"14960641","url":"https://pubmed.ncbi.nlm.nih.gov/14960641/"},{"n":3,"raw":"Ives PJ, Haensly WE, Maxwell PA, McArthur NH. A histochemical and ultrastructural study of lipofuscin accumulation in thyroid follicular cells of aging domestic cats. Mechanisms of Ageing and Development. 1975. PMID: 1228338. DOI: 10.1016/0047-6374(75)90041-X. https://pubmed.ncbi.nlm.nih.gov/1228338/","citation":"Ives PJ, Haensly WE, Maxwell PA, McArthur NH. A histochemical and ultrastructural study of lipofuscin accumulation in thyroid follicular cells of aging domestic cats. Mechanisms of Ageing and Development. 1975","year":"1975","pmid":"1228338","doi":"10.1016/0047-6374(75)90041-X","url":"https://pubmed.ncbi.nlm.nih.gov/1228338/"},{"n":4,"raw":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015. DOI: 10.1186/s12889-015-2108-4. https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","year":"2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4"},{"n":5,"raw":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017. https://www.ncbi.nlm.nih.gov/books/NBK285557/","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","year":"2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/"}],"filename":"thyroid__age.yaml"},{"combo":"thyroid__race_self_reported_ancestry","organ_slug":"thyroid","organ":"Thyroid","demographic":"race_self_reported_ancestry","demographic_label":"Race / Self-Reported Ancestry","summary":"Race/self-reported ancestry signal in thyroid histology is expected to be mostly clinical-context mediated. Candidate shortcuts include thyroid cancer incidence/detection, histology/stage distributions, nodule workup, autoimmune thyroid disease evaluation, iodine/geography, access, and institution/procedure mix. Direct intrinsic race-specific thyroid morphology is not established.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Race signal may reflect thyroid cancer incidence or detection differences.","mechanism":"Population incidence and detection patterns vary by race/ethnicity.","features":"Benign vs malignant, papillary thyroid carcinoma, tumor foci, thyroidectomy specimens.","confounders":"Diagnosis, tumor subtype, stage/size, institution, access.","validation":"Match benign/malignant status and tumor subtype/stage.","literature":[{"short_citation":"Magreni et al., 2015","citation":"Magreni A, Bann DV, Schubart JR, Goldenberg D. The effects of race and ethnicity on thyroid cancer incidence. JAMA Otolaryngology-Head & Neck Surgery. 2015","pmid":"25654447","doi":"10.1001/jamaoto.2014.3740","url":"https://jamanetwork.com/journals/jamaotolaryngology/fullarticle/2108342","evidence_status":"needs claim-level validation"},{"short_citation":"Meza & Chang, 2015","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Histologic subtype or stage distribution may mediate signal.","mechanism":"Differences in histology/stage can produce visible tumor morphology.","features":"Papillary variants, follicular-pattern lesions, aggressive features, invasion.","confounders":"Histologic subtype, stage, tumor size, treatment.","validation":"Cancer-only analysis matched by histologic subtype and stage.","literature":[{"short_citation":"Meza & Chang, 2015","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","evidence_status":"needs claim-level validation"},{"short_citation":"Finlayson et al., 2014","citation":"Finlayson A, Barnes I, Sayeed S, et al. Incidence of thyroid cancer in England by ethnic group, 2001-2007. British Journal of Cancer. 2014","url":"https://www.nature.com/articles/bjc20144","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Nodule evaluation and surgery access may create specimen-mix shortcuts.","mechanism":"Differential access and diagnostic workup can shift nodule and procedure distributions.","features":"Nodular hyperplasia, goiter, thyroidectomy vs lobectomy, incidental tumors.","confounders":"Nodule status, procedure type, institution, insurance/access proxy.","validation":"Match nodule status/procedure and include institution controls.","literature":[{"short_citation":"Magreni et al., 2015","citation":"Magreni A, Bann DV, Schubart JR, Goldenberg D. The effects of race and ethnicity on thyroid cancer incidence. JAMA Otolaryngology-Head & Neck Surgery. 2015","pmid":"25654447","doi":"10.1001/jamaoto.2014.3740","url":"https://jamanetwork.com/journals/jamaotolaryngology/fullarticle/2108342","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Autoimmune/endocrine disease context may vary across groups.","mechanism":"Graves disease, TSH distribution, thyroiditis workup, and geography/iodine may alter tissue context.","features":"Graves-like hyperplasia, scalloped colloid, lymphocytic thyroiditis, germinal centers.","confounders":"Thyroiditis/Graves status, iodine/geography, sex, age.","validation":"Stratify by thyroiditis/Graves diagnosis and endocrine metadata when available.","literature":[{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C5","section":"clinical_context","status":"active","hypothesis":"Institution/workflow may encode race.","mechanism":"Referral patterns, scanner/site, and block selection can correlate with demographics.","features":"Scanner/stain style, tissue size, procedure type, cautery/artifact.","confounders":"Institution, scanner, year, procedure, diagnosis.","validation":"Institution-balanced and scanner-balanced evaluation.","literature":[{"short_citation":"Magreni et al., 2015","citation":"Magreni A, Bann DV, Schubart JR, Goldenberg D. The effects of race and ethnicity on thyroid cancer incidence. JAMA Otolaryngology-Head & Neck Surgery. 2015","pmid":"25654447","doi":"10.1001/jamaoto.2014.3740","url":"https://jamanetwork.com/journals/jamaotolaryngology/fullarticle/2108342","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Tumor morphology may mediate apparent race signal.","mechanism":"Subtype/stage differences produce visible morphology without implying intrinsic race biology.","features":"Papillary nuclear features, follicular architecture, invasion, desmoplasia.","confounders":"Tumor subtype, stage, diagnosis, treatment.","validation":"Match tumor subtype/stage; compare tumor vs background regions.","literature":[{"short_citation":"Meza & Chang, 2015","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","evidence_status":"needs claim-level validation"},{"short_citation":"Finlayson et al., 2014","citation":"Finlayson A, Barnes I, Sayeed S, et al. Incidence of thyroid cancer in England by ethnic group, 2001-2007. British Journal of Cancer. 2014","url":"https://www.nature.com/articles/bjc20144","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Autoimmune thyroiditis morphology may mediate residual signal.","mechanism":"Differences in autoimmune/endocrine context can affect inflammatory architecture.","features":"Lymphoid aggregates, germinal centers, Hurthle cells, follicular destruction, fibrosis.","confounders":"Thyroiditis status, sex, age, diagnosis.","validation":"Match thyroiditis status and inflammation grade.","literature":[{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Graves-like hyperplasia may mediate endocrine-context signal.","mechanism":"Thyroid functional state can alter follicular morphology.","features":"Tall follicular epithelium, scalloped colloid, hyperplastic follicles, vascularity.","confounders":"Graves diagnosis, treatment, thyroid function, iodine/geography.","validation":"Use diagnosis/endocrine metadata; test within non-Graves cases.","literature":[{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Direct intrinsic thyroid morphology by race is unsupported.","mechanism":"Race/self-report should not be interpreted as direct tissue biology without ancestry-linked evidence.","features":"Benign background follicles after strict matching.","confounders":"Diagnosis, nodule, thyroiditis, institution, geography, procedure.","validation":"Test matched benign background thyroid; require external replication.","literature":[{"short_citation":"Magreni et al., 2015","citation":"Magreni A, Bann DV, Schubart JR, Goldenberg D. The effects of race and ethnicity on thyroid cancer incidence. JAMA Otolaryngology-Head & Neck Surgery. 2015","pmid":"25654447","doi":"10.1001/jamaoto.2014.3740","url":"https://jamanetwork.com/journals/jamaotolaryngology/fullarticle/2108342","evidence_status":"needs claim-level validation"},{"short_citation":"Meza & Chang, 2015","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The strongest clinical-context hypotheses are cancer detection/incidence, subtype/stage, nodule/procedure mix, autoimmune/endocrine context, and institution/workflow.","Morphology hypotheses should be framed as tumor-, thyroiditis-, Graves-, geography-, or workflow-mediated rather than direct race biology.","The most important validation is matching by diagnosis, tumor subtype/stage, nodule status, thyroiditis/Graves status, procedure type, institution, and scanner."],"references":[{"n":1,"raw":"Magreni A, Bann DV, Schubart JR, Goldenberg D. The effects of race and ethnicity on thyroid cancer incidence. JAMA Otolaryngology-Head & Neck Surgery. 2015. PMID: 25654447. DOI: 10.1001/jamaoto.2014.3740. https://jamanetwork.com/journals/jamaotolaryngology/fullarticle/2108342","citation":"Magreni A, Bann DV, Schubart JR, Goldenberg D. The effects of race and ethnicity on thyroid cancer incidence. JAMA Otolaryngology-Head & Neck Surgery. 2015","year":"2015","pmid":"25654447","doi":"10.1001/jamaoto.2014.3740","url":"https://jamanetwork.com/journals/jamaotolaryngology/fullarticle/2108342"},{"n":2,"raw":"Finlayson A, Barnes I, Sayeed S, et al. Incidence of thyroid cancer in England by ethnic group, 2001-2007. British Journal of Cancer. 2014. https://www.nature.com/articles/bjc20144","citation":"Finlayson A, Barnes I, Sayeed S, et al. Incidence of thyroid cancer in England by ethnic group, 2001-2007. British Journal of Cancer. 2014","year":"2001","url":"https://www.nature.com/articles/bjc20144"},{"n":3,"raw":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015. DOI: 10.1186/s12889-015-2108-4. https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","year":"2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4"},{"n":4,"raw":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017. https://www.ncbi.nlm.nih.gov/books/NBK285557/","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","year":"2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/"}],"filename":"thyroid__race_self_reported_ancestry.yaml"},{"combo":"thyroid__sex","organ_slug":"thyroid","organ":"Thyroid","demographic":"sex","demographic_label":"Sex","summary":"Sex signal in thyroid histology is likely mixed. Clinical-context signal is expected because thyroid nodules, thyroid cancer detection, Hashimoto thyroiditis, and autoimmune thyroid disease are more common in females. Morphology signal may persist through lymphocytic thyroiditis, germinal centers, Hurthle/oncocytic change, follicular destruction, fibrosis, Graves-like hyperplasia, and sex-biased thyroid aging biology, but much of this may remain diagnosis-mediated.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Female patients are enriched for thyroid nodule/cancer workup.","mechanism":"Higher thyroid nodule and cancer detection in females can create diagnosis/procedure shortcuts.","features":"Nodular hyperplasia, papillary carcinoma, follicular-pattern lesions, thyroidectomy/lobectomy.","confounders":"Nodule status, malignancy, subtype/stage, procedure, age.","validation":"Match nodule and cancer status; compare within benign and cancer-only subsets.","literature":[{"short_citation":"Meza & Chang, 2015","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Female patients are enriched for Hashimoto thyroiditis/autoimmune thyroid disease.","mechanism":"Autoimmune thyroid disease is sex-skewed and strongly H&E-visible.","features":"Lymphocytic thyroiditis, germinal centers, Hurthle cells, follicular destruction, fibrosis.","confounders":"Thyroiditis diagnosis, age, nodule/cancer status.","validation":"Match thyroiditis status and inflammation severity; test attenuation.","literature":[{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"},{"short_citation":"Le et al., 2024","citation":"Le Y, Geng C, Gao X, et al. The risk of thyroid cancer and sex differences in Hashimoto's thyroiditis, a meta-analysis. BMC Endocrine Disorders. 2024","doi":"10.1186/s12902-024-01670-w","url":"https://bmcendocrdisord.biomedcentral.com/articles/10.1186/s12902-024-01670-w","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Graves disease/endocrine hyperfunction context may contribute.","mechanism":"Autoimmune endocrine disease can alter follicular architecture and colloid.","features":"Follicular hyperplasia, tall epithelium, scalloped colloid, vascularity.","confounders":"Graves diagnosis, treatment, thyroid function, age.","validation":"Stratify by Graves/hyperthyroid diagnosis if metadata exist.","literature":[{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Procedure type may differ by sex through nodule/autoimmune pathways.","mechanism":"Sex-skewed indications can alter lobectomy/thyroidectomy mix.","features":"Whole gland architecture, nodular specimens, biopsy/resection context.","confounders":"Procedure type, diagnosis, institution.","validation":"Procedure-matched analysis and institution controls.","literature":[{"short_citation":"Meza & Chang, 2015","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Lymphocytic thyroiditis morphology may be the strongest sex-visible carrier.","mechanism":"Female enrichment for autoimmune thyroiditis creates H&E-visible immune architecture.","features":"Lymphoid aggregates, germinal centers, plasma cells, follicular destruction.","confounders":"Thyroiditis status, age, diagnosis, treatment.","validation":"Compare sex prediction before/after matching or excluding thyroiditis.","literature":[{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"},{"short_citation":"Le et al., 2024","citation":"Le Y, Geng C, Gao X, et al. The risk of thyroid cancer and sex differences in Hashimoto's thyroiditis, a meta-analysis. BMC Endocrine Disorders. 2024","doi":"10.1186/s12902-024-01670-w","url":"https://bmcendocrdisord.biomedcentral.com/articles/10.1186/s12902-024-01670-w","evidence_status":"needs claim-level validation"}],"evidence_status":"needs claim-level validation"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Hurthle/oncocytic change may mediate sex signal through thyroiditis.","mechanism":"Chronic autoimmune injury produces oncocytic follicular epithelial change.","features":"Hurthle cells, eosinophilic granular cytoplasm, follicular destruction.","confounders":"Thyroiditis, nodules, neoplasia, age.","validation":"Quantify oncocytic change in thyroiditis-matched tissue.","literature":[{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Graves-like follicular hyperplasia may encode endocrine sex context.","mechanism":"Autoimmune hyperthyroid morphology can be sex-skewed.","features":"Tall crowded epithelium, scalloped colloid, hyperplastic follicles, vascularity.","confounders":"Graves diagnosis, treatment, thyroid function.","validation":"Test within and excluding Graves/hyperthyroid diagnoses.","literature":[{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Sex-biased thyroid aging/gene regulation may create subtle residual morphology.","mechanism":"Sex-specific molecular aging could affect follicular or immune compartments, though H&E linkage is indirect.","features":"Follicle size/colloid patterns, stromal fibrosis, immune infiltrate.","confounders":"Age, thyroiditis, nodules, cancer, treatment.","validation":"Age- and diagnosis-matched benign background analysis; interpret as indirect unless pathologist-confirmed.","literature":[{"short_citation":"Lopes-Ramos et al., 2024","citation":"Lopes-Ramos et al. Sex-biased thyroid aging / gene regulation. 2024","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12636590/","evidence_status":"source metadata incomplete"}],"evidence_status":"source metadata incomplete"},{"id":"M5","section":"histomorphology","status":"active","hypothesis":"Direct sex morphology independent of thyroid diagnosis is uncertain.","mechanism":"Residual signal may reflect unmeasured autoimmune/nodule context rather than intrinsic sex morphology.","features":"Benign follicles and stroma after strict matching.","confounders":"Diagnosis, age, thyroiditis, nodule, procedure, institution.","validation":"Strict matched benign-background test with thyroiditis and nodule exclusions.","literature":[{"short_citation":"Meza & Chang, 2015","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","evidence_status":"needs claim-level validation"},{"short_citation":"Akamizu & Amino, 2017","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/","evidence_status":"source metadata incomplete"}],"evidence_status":"needs claim-level validation"}],"key_takeaways":["The strongest clinical-context hypotheses are female enrichment for nodules/cancer workup, Hashimoto thyroiditis, Graves/endocrine context, and procedure mix.","The strongest morphology hypotheses are lymphocytic thyroiditis, Hurthle change, Graves-like hyperplasia, and possibly subtle sex-biased thyroid aging.","The most important validation is matching by thyroiditis/Graves status, nodule status, malignancy/subtype/stage, age, procedure type, and institution."],"references":[{"n":1,"raw":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015. DOI: 10.1186/s12889-015-2108-4. https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4","citation":"Meza R, Chang JT. Multistage carcinogenesis and the incidence of thyroid cancer in the US by sex, race, stage and histology. BMC Public Health. 2015","year":"2015","doi":"10.1186/s12889-015-2108-4","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-015-2108-4"},{"n":2,"raw":"Le Y, Geng C, Gao X, et al. The risk of thyroid cancer and sex differences in Hashimoto's thyroiditis, a meta-analysis. BMC Endocrine Disorders. 2024. DOI: 10.1186/s12902-024-01670-w. https://bmcendocrdisord.biomedcentral.com/articles/10.1186/s12902-024-01670-w","citation":"Le Y, Geng C, Gao X, et al. The risk of thyroid cancer and sex differences in Hashimoto's thyroiditis, a meta-analysis. BMC Endocrine Disorders. 2024","year":"2024","doi":"10.1186/s12902-024-01670-w","url":"https://bmcendocrdisord.biomedcentral.com/articles/10.1186/s12902-024-01670-w"},{"n":3,"raw":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017. https://www.ncbi.nlm.nih.gov/books/NBK285557/","citation":"Akamizu T, Amino N. Hashimoto's Thyroiditis. Endotext. Updated 2017","year":"2017","url":"https://www.ncbi.nlm.nih.gov/books/NBK285557/"},{"n":4,"raw":"Hashimoto Thyroiditis. StatPearls. Updated 2025. https://www.ncbi.nlm.nih.gov/books/NBK459262/","citation":"Hashimoto Thyroiditis. StatPearls. Updated 2025","year":"2025","url":"https://www.ncbi.nlm.nih.gov/books/NBK459262/"},{"n":5,"raw":"Lopes-Ramos et al. Sex-biased thyroid aging / gene regulation. 2024. https://pmc.ncbi.nlm.nih.gov/articles/PMC12636590/","citation":"Lopes-Ramos et al. Sex-biased thyroid aging / gene regulation. 2024","year":"2024","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12636590/"}],"filename":"thyroid__sex.yaml"},{"combo":"uterus__age","organ_slug":"uterus","organ":"Uterus","demographic":"age","demographic_label":"Age","summary":"Uterus age signal is a stable residual candidate. The main plausible carriers are menopausal/endometrial hormonal state, endometrial atrophy, gland density, stromal cellularity/fibrosis, cystic atrophy, and myometrial or leiomyoma-related sampling context. Current master evidence E40 is incomplete and should be replaced with modern pathology sources.","claims":[{"id":"C1","section":"clinical_context","status":"active","hypothesis":"Biopsy and hysterectomy indications differ strongly by age.","mechanism":"Younger patients are enriched for proliferative/secretory endometrium and abnormal bleeding workups; older patients for postmenopausal bleeding, atrophy, hyperplasia, and carcinoma exclusion.","features":"Endometrial biopsy vs hysterectomy, hyperplasia/carcinoma, polyp, leiomyoma, atrophy.","confounders":"Procedure, diagnosis, menopausal status, hormone therapy, cancer history.","validation":"Match procedure and diagnosis; compare residual age signal in benign endometrium.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"C2","section":"clinical_context","status":"active","hypothesis":"Menopause creates a strong clinical-context and morphology axis.","mechanism":"Postmenopausal status changes sampling indications and background endometrium.","features":"Atrophic endometrium, cystic atrophy, inactive glands, scant stroma.","confounders":"Menopausal status, hormone therapy, tamoxifen, bleeding indication.","validation":"Add menopausal/hormone-therapy metadata where possible.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"C3","section":"clinical_context","status":"active","hypothesis":"Endometrial hyperplasia and carcinoma exclusion may enrich older cases.","mechanism":"Postmenopausal bleeding and obesity/tamoxifen contexts can increase hyperplasia/cancer workups.","features":"Hyperplasia, EIN/atypia, carcinoma, polyp, biopsy adequacy.","confounders":"Diagnosis, BMI, hormone therapy, tamoxifen, procedure type.","validation":"Exclude hyperplasia/cancer or match these labels before reviewing intrinsic age morphology.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"C4","section":"clinical_context","status":"active","hypothesis":"Leiomyoma, polyp, and hysterectomy sampling can create age-associated tissue composition.","mechanism":"Procedure indication changes the amount of myometrium, leiomyoma, polyp, and background endometrium sampled.","features":"Leiomyoma hyalinization, endometrial polyp, myometrium, adenomyosis, hysterectomy blocks.","confounders":"Procedure, diagnosis, block site, menopausal status.","validation":"Match biopsy vs hysterectomy and benign lesion category.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"M1","section":"histomorphology","status":"active","hypothesis":"Endometrial gland density and architecture encode age/hormonal state.","mechanism":"Cycling endometrium, inactive endometrium, and postmenopausal atrophy have distinct gland/stroma patterns.","features":"Gland density, gland size, cystic atrophy, gland:stroma ratio.","confounders":"Cycle phase, hormone therapy, hyperplasia, polyp, sampling adequacy.","validation":"Stratify by diagnosis/cycle/hormone state and quantify gland density.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"M2","section":"histomorphology","status":"active","hypothesis":"Stromal cellularity and fibrosis may encode postmenopausal involution.","mechanism":"Endometrial and myometrial stromal compartments remodel with age and hormonal withdrawal.","features":"Stromal cellularity, fibrosis, vascular sclerosis, myometrial fibrosis.","confounders":"Leiomyoma, adenomyosis, prior procedure, inflammation.","validation":"Review benign background endometrium and myometrium separately.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"M3","section":"histomorphology","status":"active","hypothesis":"Uterine age signal may persist even after diagnosis matching through tissue composition.","mechanism":"Menopause changes the amount and morphology of endometrium, myometrium, polyps, and leiomyomas sampled.","features":"Endometrial thickness, atrophy, myometrium, leiomyoma hyalinization.","confounders":"Procedure type, block sampling, diagnosis, hormone therapy.","validation":"Match hysterectomy vs biopsy and separately test endometrium-only regions.","literature":[],"evidence_status":"source metadata incomplete"},{"id":"M4","section":"histomorphology","status":"active","hypothesis":"Vascular and stromal sclerosis may be an age-associated background feature.","mechanism":"Aging and menopause can alter stromal vessels, myometrium, and endometrial support tissue.","features":"Thick-walled vessels, stromal fibrosis, myometrial sclerosis, hyalinized leiomyoma.","confounders":"Leiomyoma, hypertension, procedure, block site.","validation":"Quantify vascular/stromal features only after benign diagnosis and procedure matching.","literature":[],"evidence_status":"source metadata incomplete"}],"key_takeaways":["Best review target: benign endometrial gland density, atrophy, cystic change, and stromal cellularity.","Main shortcut risk: procedure type, postmenopausal bleeding workup, hyperplasia/carcinoma exclusion.","Literature status: high-priority search gap because E40 metadata are incomplete."],"references":[{"n":1,"raw":"Endometrial aging / menopausal atrophy source. E40 in master evidence registry. Source metadata incomplete; needs PMID/DOI replacement before final use.","citation":"Endometrial aging / menopausal atrophy source. E40 in master evidence registry. Source metadata incomplete; needs PMID/DOI replacement before final use","year":""}],"filename":"uterus__age.yaml"}]};
